/* Master glossary. Schema: CLAUDE.md §9.
   { term, definition, category, chapters: [slug, ...] }
   Appended to as chapters are built — check for name collisions before adding a new term;
   extend an existing entry's `chapters` array instead of duplicating.

   Merge note (GATE-1 reference set): chapter 01's proposed "Offboarding (deprovisioning)" was merged
   into chapter 02's "Deprovisioning" entry (same concept, chapter 02 owns the lifecycle-stage framing)
   instead of being added as a second, duplicate entry — see BUILD_STATUS.md. */
window.GLOSSARY = [
  { term: "IAM (Identity and Access Management)", definition: "The discipline and category of software responsible for answering two questions on behalf of every connected application: who is this (authentication), and what are they allowed to do (authorization) — solved once, centrally, instead of separately by each application.", category: "IAM Foundations", chapters: ["what-is-iam"] },
  { term: "Authentication (AuthN)", definition: "The process of proving who a user or system is, typically via a password, one-time code, hardware key, or combination of factors. Answers \"who are you?\" Full depth in chapter 3, including why a system can authenticate someone perfectly and still make the wrong access-control decision right after — authentication and authorization are evaluated as independent steps, not one checkbox.", category: "IAM Foundations", chapters: ["what-is-iam", "authn-authz-accounting"] },
  { term: "Authorization (AuthZ)", definition: "The process of deciding what an already-authenticated identity is permitted to do. Answers \"what can you do, now that I know who you are?\" A system can authenticate correctly and still authorize incorrectly — they are distinct problems. Full depth in chapter 3; a common real-world bug is checking only \"is this user authenticated\" instead of \"is this specific user allowed to act on this specific resource.\"", category: "IAM Foundations", chapters: ["what-is-iam", "authn-authz-accounting"] },
  { term: "Single Sign-On (SSO)", definition: "A property of centralized authentication where one login session is usable across multiple connected applications, without re-entering credentials for each one. Mechanically: the authentication act happens once against a shared Identity Provider (IdP); the browser carries a session the IdP recognizes, and each connected application (SP/RP) establishes its own trust in that result via a redirect-and-assertion handshake with the same IdP, rather than the user re-typing credentials app by app or the apps sharing a password. Protocol-specific mechanics (OAuth/OIDC/SAML) are covered in Part III; Keycloak's realm-level session implementation is covered in chapter 29.", category: "IAM Foundations", chapters: ["what-is-iam", "sso-and-federation"] },
  { term: "Centralized authentication", definition: "The practice of delegating login, credential storage, and session management to one shared system that every application trusts, instead of each application implementing its own.", category: "IAM Foundations", chapters: ["what-is-iam"] },
  { term: "Identity broker", definition: "An IAM system acting as an intermediary that delegates the act of authentication to an external identity provider (e.g. Google, a corporate SAML IdP) that the user already has an independent account with, and translates the result into a form the connecting applications understand — without those applications needing to integrate with the external provider directly, and without the broker ever storing or managing the user's credential at that external IdP. Contrast with federation, which reuses an existing directory rather than delegating a single login event. Full depth in chapter 7; implemented in chapter 31 (a built-in broker type) and chapter 40 (a custom broker type written from scratch).", category: "IAM Foundations", chapters: ["what-is-iam", "sso-and-federation", "custom-idp-and-required-actions"] },
  { term: "Federation (identity federation)", definition: "Connecting an IAM system to an existing external identity store or directory (such as an LDAP directory or Active Directory) so its existing population of accounts can be reused — checked via operations like an LDAP bind — without migrating every user into the IAM system or asking an external IdP to authenticate them. Contrast with identity brokering, which delegates a single login event to an external IdP rather than reusing a directory the organization already runs. Full depth in chapter 7; implemented in chapter 32.", category: "IAM Foundations", chapters: ["what-is-iam", "sso-and-federation", "user-federation-ldap"] },
  { term: "Self-service (account management)", definition: "Capability letting end users manage their own account — resetting a password, updating a profile, reviewing active sessions — without filing a help-desk request.", category: "IAM Foundations", chapters: ["what-is-iam", "users-and-credentials"] },
  { term: "Admin console", definition: "A generic term for the administrative interface an IAM system provides for managing users, applications, and policy without touching the underlying database directly. Keycloak's Admin Console is a web UI (reachable at /admin) backed entirely by the Admin REST API — every click it performs is a REST call any script could make instead (this course verifies that equivalence directly via kcadm.sh throughout Parts IV-V). Per Keycloak's own Server Administration Guide: the top-left 'Current realm' selector shows which realm you're currently managing and lets you switch; its dropdown includes a 'Create realm' button that opens a form with a single required realm-name field — submitting it makes the new realm the current realm automatically, and generates a key pair and self-signed certificate for it. Below the realm selector, the left nav groups screens under 'Manage' (users, groups, sessions, events) and 'Configure' (realm settings, clients, roles, identity providers, authentication). The exact screen layout above is drawn from Keycloak's current official documentation, not personally screenshot-verified in this course (no browser tool is available in this environment) — every underlying mechanism it describes was independently confirmed via the Admin REST API through kcadm.sh.", category: "IAM Foundations", chapters: ["what-is-iam", "installing-keycloak", "admin-api-and-cli"] },
  { term: "Extensibility (plugin architecture)", definition: "An IAM system's ability to be customized — custom authentication steps, custom data sources, custom branding — via a defined plugin interface rather than forking the product's source code. Keycloak's SPI architecture is covered in Part VIII.", category: "IAM Foundations", chapters: ["what-is-iam", "themes-and-branding", "custom-spis"] },
  { term: "Audit trail", definition: "The recorded output of accounting — a consistent, centrally recorded log of authentication and access events (logins, permission changes, admin actions) that lets an organization answer \"who accessed what, and when.\" Audit, more precisely, is the separate, later activity of reviewing that output (a compliance review, an incident investigation); the audit trail is what accounting produces for audit to consume. Full depth in chapter 3 (as part of AAA, including a note on an industry terminology ambiguity around \"accounting\") and chapter 28 (Keycloak's event logging).", category: "IAM Foundations", chapters: ["what-is-iam", "authn-authz-accounting", "events-and-auditing"] },
  { term: "Compliance-readiness", definition: "The degree to which an IAM system's authentication (including MFA), authorization, and accounting/audit-logging capabilities already satisfy what regulatory and contractual frameworks demand, reducing the work needed to pass an audit. In practice, no major framework — GDPR, SOC 2's Trust Services Criteria, the HIPAA Security Rule, PCI-DSS, or ISO/IEC 27001 — invents new IAM theory: each independently demands authentication, authorization (often phrased as least privilege or need-to-know), and accounting (phrased as audit controls, logging, or monitoring) under its own vocabulary and numbering. Full framework-by-framework treatment in chapter 11.", category: "IAM Foundations", chapters: ["what-is-iam", "compliance-for-iam"] },
  { term: "Workforce IAM", definition: "IAM focused on managing an organization's own employees, contractors, and the service accounts they operate — a bounded, HR-backed population (identity count roughly tracks headcount, and most identities are tied to a joiner-mover-leaver record, chapter 10). Covers SSO into internal and SaaS business applications, directory federation, and role/group-based authorization. Distinct from CIAM (external, self-registering, consumer-scale populations) and from PAM (the smaller, higher-risk slice of privileged/admin accounts within the workforce). Full market-category depth, including vendor comparison, in chapter 12.", category: "IAM Foundations", chapters: ["what-is-iam", "iam-market-landscape"] },
  { term: "CIAM (Customer Identity and Access Management)", definition: "IAM focused on managing external, customer-facing identities — an unbounded, self-registering population (anyone can sign up any time) at consumer scale, typically in the millions rather than hundreds or thousands. Prioritizes social login, progressive profiling, login-page branding/conversion impact, and consumer-grade uptime over directory federation. The buyer is usually the product organization, not IT, unlike workforce IAM. Distinct from Workforce IAM (an organization's own bounded, HR-backed population). Full market-category depth, including vendor comparison, in chapter 12.", category: "IAM Foundations", chapters: ["what-is-iam", "iam-market-landscape"] },
  { term: "Multi-factor authentication (MFA)", definition: "Requiring proof from two or more different factor categories to authenticate — typically something you know (a password) combined with something you have (a hardware key, an authenticator app) or something you are (biometrics). Two proofs from the same category (e.g. a password plus a security question) are not genuine MFA. Full treatment of factor categories, OTP mechanics, WebAuthn/FIDO2/passkeys, and risk-based/step-up authentication in chapter 5; Keycloak's MFA/OTP configuration in chapter 30.", category: "IAM Foundations", chapters: ["what-is-iam", "authentication-factors-mfa", "authentication-flows", "password-policies-and-mfa"] },
  { term: "Single point of failure (IAM context)", definition: "A risk introduced by centralizing authentication: if the shared IAM system is unavailable, login for every connected application is unavailable too, unlike independent per-app login systems which fail separately.", category: "IAM Foundations", chapters: ["what-is-iam"] },

  { term: "Identity", definition: "The complete record representing a particular person, service, or device within a system: the bundle that ties an identifier, one or more credentials, and a set of attributes together under one entity.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Identifier", definition: "The unique value used to look an identity up within a given namespace — a username, email address, or employee ID. An identifier doesn't need to be secret; it only needs to be unique enough to pick one identity out from the rest.", category: "Core concepts", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Credential", definition: "Evidence presented to prove control of an identifier — a password, a one-time code, a private key, a fingerprint. Credentials can be rotated or replaced without changing who the identity is.", category: "Core concepts", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Attribute", definition: "A fact recorded about an identity that isn't itself proof of anything — department, job title, phone number, subscription tier. Attributes describe the identity; they don't authenticate it.", category: "Core concepts", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Principal", definition: "The entity being identified — the real-world person, service, or device an identity refers to, independent of any particular login session.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Subject", definition: "A principal as represented inside an active security context, such as a signed token or a live session. The same principal produces a new subject every time it authenticates.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Digital identity", definition: "The electronic representation of a principal inside a system — in practice, the identity record (identifier + credentials + attributes) that stands in for a real-world person, service, or device.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Identity lifecycle", definition: "The generalized sequence an identity moves through over time: create, activate, modify, suspend, and (eventually) delete. Vendor products implement this sequence with their own screens and states, but the stages themselves are the same everywhere.", category: "Identity lifecycle", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Provisioning", definition: "The act of creating an identity and granting it the initial access it needs. As a lifecycle stage (chapter 2) this is a single event; chapter 10 covers the surrounding governance discipline — access reviews, segregation of duties, and the Joiner-Mover-Leaver (JML) vocabulary — that keeps checking whether what was provisioned is still correct long after the provisioning event itself is over.", category: "Identity lifecycle", chapters: ["identity-fundamentals", "identity-governance"] },
  { term: "Deprovisioning", definition: "The act of removing or disabling an identity's access, typically at the end of its lifecycle — for example, when an employee leaves. With centralized IAM, this collapses into a single action (disabling one identity) instead of chasing down access across every application individually. As a lifecycle stage (chapter 2) this is a single event; chapter 10 covers what happens when that event is missed — an orphaned account, an identity whose owner has left but whose access was never actually removed — and why periodic access review exists as a backstop for exactly that failure mode, not just a nice-to-have on top of working deprovisioning.", category: "Identity lifecycle", chapters: ["identity-fundamentals", "what-is-iam", "identity-governance"] },
  { term: "Service account", definition: "A non-human identity created for an application or automated process to authenticate with, rather than for a person. Typically long-lived and often over-privileged if not reviewed regularly.", category: "Identity types", chapters: ["identity-fundamentals", "securing-a-backend-api", "service-to-service-auth"] },
  { term: "Machine identity", definition: "An identity that represents a device, server, or piece of infrastructure rather than a person — for example, a certificate-backed identity for a server. Overlaps with, but isn't identical to, a service account.", category: "Identity types", chapters: ["identity-fundamentals"] },
  { term: "Workload identity", definition: "An identity assigned to a running piece of software — a container, function, or process — so it can authenticate to other services without embedding a long-lived secret in its code. A modern refinement of the machine-identity idea, common in cloud and Kubernetes environments.", category: "Identity types", chapters: ["identity-fundamentals"] },
  { term: "Human identity", definition: "An identity that represents a person — an employee, customer, patient, or clinician — as opposed to a service, device, or workload.", category: "Identity types", chapters: ["identity-fundamentals"] },
  { term: "Self-registration", definition: "An identity lifecycle entry point where the principal creates their own identity through a signup form, rather than an administrator creating it for them. The federated/brokered variant, where the identity is instead created automatically from an external identity provider's data, is covered in chapter 7.", category: "Identity lifecycle", chapters: ["identity-fundamentals"] },
  { term: "Northwind Apps", definition: "One of this course's three running case-study organizations: a B2B SaaS company whose identity population is split between its own internal staff and the employees of the business customers who use its product.", category: "Case-study orgs", chapters: ["identity-fundamentals"] },
  { term: "Riverside Health", definition: "One of this course's three running case-study organizations: a hospital network operating under HIPAA, whose identity population includes clinician workforce identities and patient identities using a patient portal.", category: "Case-study orgs", chapters: ["identity-fundamentals"] },
  { term: "Meridian Trust", definition: "One of this course's three running case-study organizations: a retail bank operating under PCI-DSS, whose identity population includes bank employees and retail customers, and whose IAM work emphasizes step-up authentication and fraud-aware access decisions.", category: "Case-study orgs", chapters: ["identity-fundamentals", "service-to-service-auth"] },

  { term: "Accounting", definition: "The third formal part of the AAA model (Authentication, Authorization, Accounting): the act of recording identity and access events — logins, permission checks, administrative changes — as structured, timestamped data, continuously and in real time as they occur. Distinct from audit, which is the later activity of reviewing those records. Note: in classic network-access-control contexts (RADIUS, dial-up/VPN access control) \"accounting\" leans toward usage metering for billing; in general modern IAM usage the word has broadened to mean security-event logging for audit and forensic purposes. Keycloak implements this as its realm Events subsystem (chapter 28).", category: "IAM Foundations", chapters: ["authn-authz-accounting", "events-and-auditing"] },

  { term: "Directory service", definition: "A specialized, read-optimized data store for records about people, systems, and resources, organized hierarchically and built for fast lookups rather than transactions. Most organizations already have one — frequently Active Directory — before they ever adopt a dedicated IAM product.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "X.500", definition: "An ITU-T standard from the 1980s defining a comprehensive, heavyweight model for directories and the protocols to access them. LDAP's data model is inherited from X.500, though LDAP itself runs over plain TCP/IP.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "LDAP (Lightweight Directory Access Protocol)", definition: "A lightweight, TCP/IP-based protocol for accessing directories that follow the X.500 data model. It is the protocol most real directory products — including Active Directory — expose for interoperability, and the one Keycloak speaks for user federation (chapter 32).", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Directory Information Tree (DIT)", definition: "The hierarchical structure an LDAP directory's data is organized into — a tree of entries, typically shaped around an organization's domain and internal structure.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Entry (directory entry)", definition: "One record inside a Directory Information Tree — a person, group, or device. Roughly analogous to a database row, except entries live in a tree rather than a flat table.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Distinguished Name (DN)", definition: "The full, unique path to one entry from the root of the Directory Information Tree — an entry's unique address inside the directory. Moving an entry to a different position in the tree can change its DN.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Relative Distinguished Name (RDN)", definition: "The single component of a Distinguished Name that distinguishes an entry from its siblings under the same parent. A DN is a chain of RDNs read from the entry up to the root.", category: "Directory services", chapters: ["directory-services"] },
  { term: "objectClass", definition: "A declaration on a directory entry of what kind of thing it is and which attributes it's allowed or required to carry — e.g. person, organizationalPerson, inetOrgPerson. An entry can carry more than one objectClass.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Bind operation", definition: "The LDAP operation where a client presents a Distinguished Name and a credential and the directory checks whether the credential is correct for that entry. A simple bind is, functionally, an authentication attempt phrased in LDAP's own terms — but a successful bind proves nothing about authorization.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Simple bind", definition: "A bind operation performed with a Distinguished Name and a plaintext (or TLS-protected) password — the most common way an LDAP client authenticates against a directory.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Anonymous bind", definition: "A bind operation performed without presenting any credential, used for unauthenticated read-only lookups. Left enabled unintentionally on a production directory, it is a real security exposure.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Active Directory (AD)", definition: "Microsoft's directory product and the dominant store for enterprise workforce identities. It exposes an LDAP interface among others, while also using its own native mechanisms (such as Kerberos) for day-to-day authentication.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Domain (AD domain)", definition: "A security and administrative boundary in Active Directory — a set of users, computers, and policies managed together, identified by a DNS-style name such as riversidehealth.local.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Organizational Unit (OU)", definition: "A container within an Active Directory domain used to group users, computers, or groups for the purpose of applying policy and delegating administration — the rough AD analogue of a generic LDAP ou entry.", category: "Directory services", chapters: ["directory-services", "user-federation-ldap"] },
  { term: "Domain Controller (DC)", definition: "A server that holds a copy of an Active Directory domain's directory data and services authentication requests against it — the directory server itself, in AD's vocabulary.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Kerberos", definition: "A ticket-based authentication protocol and Active Directory's native mechanism for day-to-day login, distinct from a plain LDAP bind. Deliberately not covered in depth in this course — only its existence and role need to be known here.", category: "Directory services", chapters: ["directory-services"] },

  { term: "Knowledge factor", definition: "An authentication factor based on something the user knows, such as a password, PIN, or security question. Vulnerable to phishing, guessing, reuse, and shoulder-surfing — and combining two knowledge factors does not produce genuine MFA.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "Possession factor", definition: "An authentication factor based on something the user has, such as a phone running an authenticator app, a hardware security key, or a badge. Vulnerable to theft or loss, and to SIM-swap attacks specifically for SMS-based possession factors.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "Inherence factor", definition: "An authentication factor based on something the user is, such as a fingerprint, face, iris, or voice. Unlike a credential, an inherence factor cannot be rotated if its stored template is compromised, which makes that kind of incident categorically different from a leaked password.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "Context/behavior signal", definition: "Information about the situation surrounding a login attempt — device, location, network, typing rhythm, time of day — rather than a traditional proof of identity. Not a classical authentication factor on its own; used as input to risk-based and adaptive authentication decisions.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "OTP (One-Time Password)", definition: "A short, single-use code generated from a shared secret, used as a possession-factor proof. The two standard variants, TOTP and HOTP, differ only in what moving factor advances the code.", category: "OTP mechanics", chapters: ["authentication-factors-mfa", "password-policies-and-mfa"] },
  { term: "TOTP (Time-based One-Time Password)", definition: "An OTP variant (RFC 6238) whose moving factor is the current time, rounded to a fixed step (commonly 30 seconds) — the code changes automatically as time passes. Requires the device and server clocks to stay reasonably synchronized.", category: "OTP mechanics", chapters: ["authentication-factors-mfa", "password-policies-and-mfa"] },
  { term: "HOTP (HMAC-based One-Time Password)", definition: "An OTP variant (RFC 4226) whose moving factor is a counter that increments each time a code is consumed, rather than the clock. Can desync from the server if a code is generated but never actually used.", category: "OTP mechanics", chapters: ["authentication-factors-mfa", "password-policies-and-mfa"] },
  { term: "Moving factor", definition: "The changing input — current time for TOTP, an incrementing counter for HOTP — that both the device and the server combine with a shared secret to independently compute the same one-time code, without needing to transmit the secret again.", category: "OTP mechanics", chapters: ["authentication-factors-mfa", "password-policies-and-mfa"] },
  { term: "WebAuthn", definition: "A W3C web standard providing a browser-level API for public-key-based authentication: a device generates a public/private key pair at registration, the private key never leaves the device, and the server verifies challenge signatures using the public key. The mechanism behind passkeys and hardware security key logins.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "FIDO2", definition: "The broader family of standards that WebAuthn belongs to, covering how a browser or platform communicates with an authenticator device to perform public-key-based authentication.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "Passkey", definition: "The user-facing name for a FIDO2/WebAuthn credential designed to sync across a person's own devices via their platform account, so using it feels like an ordinary login rather than carrying a separate security key.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "Authenticator (WebAuthn/FIDO2)", definition: "The device or module — a phone, a hardware security key, a platform's built-in secure element — that holds a WebAuthn/FIDO2 private key and performs the signing operation, without ever exposing that key to the browser, the server, or the user.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "Phishing-resistant authentication", definition: "An authentication method that cannot be defeated by tricking a user into entering credentials or codes on a fake site, because the proof itself (e.g. a WebAuthn signature) is cryptographically bound to the real site's origin and has nothing a human can be tricked into copying or typing. Typed passwords and OTP codes do not have this property; WebAuthn/FIDO2/passkeys do.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa", "iam-threat-landscape"] },
  { term: "Risk-based authentication (adaptive authentication)", definition: "An authentication strategy that evaluates contextual signals — device, location, action sensitivity — to raise or lower how much proof is required for a given login or action, instead of applying the same fixed requirement every time.", category: "Risk-based authentication", chapters: ["authentication-factors-mfa"] },
  { term: "Step-up authentication", definition: "Demanding one additional authentication factor mid-session, triggered by an elevated-risk signal such as a sensitive action or an unfamiliar device, rather than on a fixed schedule. Layered on top of an already-successful login, not a replacement for it.", category: "Risk-based authentication", chapters: ["authentication-factors-mfa", "authentication-flows", "case-study-riverside", "case-study-meridian"] },
  { term: "Authenticator Assurance Level (AAL)", definition: "NIST SP 800-63B's tiered classification (AAL1-AAL3) of how strong an authentication method's combined factors are, used as a reference point when deciding what level of proof a given risk or compliance requirement calls for.", category: "Risk-based authentication", chapters: ["authentication-factors-mfa"] },

  { term: "Access Control List (ACL)", definition: "An authorization model that attaches permissions directly to a resource, listing exactly which subjects can do what to it. Simple to reason about for one resource at a time, but scales poorly as roughly N resources × M subjects of entries to maintain.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Role-Based Access Control (RBAC)", definition: "An authorization model where permissions attach to roles rather than directly to subjects, and subjects are assigned to one or more roles. Scales well for stable job functions; degrades into \"role explosion\" when access depends on conditions that aren't really job functions. Keycloak's realm and client roles are a direct implementation (chapter 23).", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Role explosion", definition: "The failure mode of an RBAC system where access conditions that aren't really distinct job functions get forced into roles anyway, producing a long list of near-duplicate, hard-to-reason-about roles instead of a small, stable set.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Attribute-Based Access Control (ABAC)", definition: "An authorization model that computes the access decision at request time from attributes of the subject, resource, and environment, rather than from a pre-assigned role or a static list. Puts the general Attribute concept (chapter 2) directly to work as live input to an access decision.", category: "Authorization models", chapters: ["authorization-models", "keycloak-authorization-services", "fine-grained-access-patterns"] },
  { term: "Policy-Based Access Control (PBAC)", definition: "An authorization model where access decisions are made by evaluating explicit, often centrally managed policy rules — frequently combining multiple attributes and conditions in one rule. Heavily overlaps with ABAC in practice, since most policies are evaluated over attributes; the literature does not draw a crisp, universal line between the two.", category: "Authorization models", chapters: ["authorization-models", "keycloak-authorization-services"] },
  { term: "Relationship-Based Access Control (ReBAC)", definition: "An authorization model that bases access decisions on relationships between subjects and resources, modeled as a graph — e.g. \"is the owner of\" or \"is on the care team for\" — rather than on roles or attribute values alone. Fits fine-grained, frequently changing access patterns that roles and attributes alone express poorly. Keycloak's Authorization Services can express relationship-flavored policies on top of its resource/scope model (chapters 37-38).", category: "Authorization models", chapters: ["authorization-models", "keycloak-authorization-services", "fine-grained-access-patterns", "case-study-meridian"] },
  { term: "Zero Trust", definition: "The security principle of \"never trust, always verify\": no request is trusted by default just because it came from inside a network perimeter or from an already-authenticated session — every request to a protected resource is independently verified. A cross-cutting principle that applies regardless of which authorization model (ACL/RBAC/ABAC/PBAC/ReBAC) is in use underneath.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Least privilege", definition: "The security principle of granting a subject only the minimum access needed to do its job, for only as long as it's needed, rather than standing access granted broadly \"just in case.\" Applies across every authorization model, not as a model of its own.", category: "Authorization models", chapters: ["authorization-models", "service-to-service-auth"] },
  { term: "Permission", definition: "A specific allowed action on a specific resource (or class of resource) — the unit of access that an authorization model attaches to a subject, directly (ACL), through a role (RBAC), or computed from a decision (ABAC/PBAC/ReBAC).", category: "Authorization models", chapters: ["authorization-models", "keycloak-authorization-services"] },
  { term: "Role", definition: "A named bundle of permissions, assigned to subjects rather than defining permissions per subject directly. The unit of indirection RBAC introduces between subjects and the permissions they hold. In Keycloak this is implemented as two scoped role types — a realm role (visible to every client in the realm) and a client role (a namespace dedicated to one specific client) — either of which can be assigned directly to a user or inherited via group membership, and either of which can be a composite role that transitively grants other roles it's \"associated with.\"", category: "Authorization models", chapters: ["authorization-models", "roles-and-groups"] },
  { term: "Policy engine", definition: "A system (often standalone) that evaluates explicit policy rules against a request to produce an allow/deny authorization decision, letting policies be authored, versioned, and audited independently of the applications that call them — the typical infrastructure a PBAC approach is built on.", category: "Authorization models", chapters: ["authorization-models", "keycloak-authorization-services"] },
  { term: "Resource scope (authorization)", definition: "The specific object or boundary (a tenant, a document, a patient record) that a permission or role assignment applies to. A role check that verifies only \"does this subject hold role X\" without also verifying the resource scope it applies to is a common and serious RBAC implementation bug.", category: "Authorization models", chapters: ["authorization-models", "keycloak-authorization-services"] },
  { term: "Relationship graph", definition: "A data structure modeling subjects and resources as nodes connected by labeled relationship edges (e.g. \"owns,\" \"is on the care team for\"), which a ReBAC system traverses at access-decision time to determine whether a subject's relationship to a resource grants access.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Account-risk attribute", definition: "An attribute recording how risky a given account is judged to be (e.g. new, flagged, high-value), used as one input to an ABAC decision such as how large a transaction a teller may approve against that account without further escalation.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Care team relationship", definition: "A ReBAC relationship type recording which clinicians are currently authorized to access a specific patient's records because they are actively treating that patient — changing as patients are admitted, transferred, and discharged, and used in place of a blanket \"clinician\" role to decide chart access.", category: "Authorization models", chapters: ["authorization-models", "case-study-riverside"] },

  { term: "Identity Provider (IdP)", definition: "The system in an SSO, brokering, or federation relationship that holds credentials, performs authentication, and asserts the user's identity to another system — a role name shared across SAML, OIDC, and OAuth terminology.", category: "SSO & Federation", chapters: ["sso-and-federation", "identity-brokering"] },
  { term: "Service Provider (SP)", definition: "SAML's name for the application that relies on an external IdP's assertion instead of authenticating the user itself. Refers to the same role as OIDC's Relying Party (RP) — the two terms are not different roles, just different protocols' vocabulary for one role.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Relying Party (RP)", definition: "OpenID Connect's name for the application that relies on an external IdP's assertion instead of authenticating the user itself. Refers to the same role as SAML's Service Provider (SP) — the two terms are not different roles, just different protocols' vocabulary for one role.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Trust (IdP/SP-RP trust)", definition: "The pre-configured agreement that lets an IdP and a relying application accept each other's messages: shared metadata describing endpoints and capabilities, certificates/signing keys to verify assertions weren't forged, and registered redirect URIs so login results can't be sent somewhere an attacker controls. Trust is configured in advance, never assumed. Full protocol-specific depth in chapter 15 (OIDC discovery) and chapter 17 (SAML metadata).", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "JIT (just-in-time) provisioning", definition: "Automatically creating a local identity from an external IdP's or directory's data the first time a user successfully authenticates through brokering or federation, rather than an administrator pre-creating the account. This is the mechanism behind the \"federated/brokered creation\" entry point into the identity lifecycle's create stage (chapter 2) — everything downstream (modify, suspend, delete) proceeds exactly as it would for any other identity.", category: "SSO & Federation", chapters: ["sso-and-federation", "identity-brokering", "custom-idp-and-required-actions", "case-study-northwind"] },
  { term: "Assertion", definition: "The message an Identity Provider sends to a relying application stating who the user is (and typically some attributes about them), after authenticating that user. The specific format and transport of an assertion differs by protocol (a SAML assertion vs. an OIDC ID token), but the conceptual role is the same across both. In SAML 2.0 specifically, an assertion is a signed XML <saml:Assertion> document with four key parts: a <saml:Subject> (a NameID plus a SubjectConfirmation tying the assertion to the specific browser exchange it was issued for), <saml:Conditions> (a NotBefore/NotOnOrAfter validity window plus an AudienceRestriction naming exactly which SP may accept it), a <saml:AuthnStatement> (when authentication happened and by what method), and an optional <saml:AttributeStatement> (arbitrary name/value user attributes). The whole assertion is wrapped in an XML digital signature the SP must validate against the IdP's trusted certificate — checking only that the HTTP response arrived over TLS is not the same as validating this signature.", category: "SSO & Federation", chapters: ["sso-and-federation", "saml2"] },
  { term: "Metadata (IdP/SP metadata)", definition: "A machine-readable description of an IdP's or SP/RP's endpoints and supported capabilities, exchanged so each side can configure itself to talk to the other correctly instead of guessing. One of the three ingredients of establishing trust between an IdP and a relying application. In SAML 2.0 specifically, this is an XML <EntityDescriptor> document: it names the entity's stable entityID, carries its signing (and sometimes encryption) certificate inside a <KeyDescriptor>, and lists concrete endpoint URLs per supported binding — an IdP's metadata lists its SingleSignOnService URLs inside an <IDPSSODescriptor>; an SP's metadata lists its AssertionConsumerService (ACS) URL inside an <SPSSODescriptor>. Compare OIDC's discovery document (chapter 15), which does the same job as JSON fetched live over HTTP rather than XML exchanged once during setup.", category: "SSO & Federation", chapters: ["sso-and-federation", "saml2"] },
  { term: "Redirect URI (registered)", definition: "A URL an application pre-registers with an IdP as a valid destination to send the browser back to after authentication. The IdP only redirects to registered URIs, preventing an attacker from redirecting a login result to a URL they control. One of the three ingredients of establishing trust between an IdP and a relying application; full mechanics in chapter 13 (OAuth 2.0 authorization code flow). Under OAuth 2.0 specifically, RFC 6749 §3.1.2.3 requires the authorization server to validate a submitted redirect_uri against the registered value using exact, simple string comparison — not a prefix, substring, or same-domain match — and §3.1.2.4 requires it to refuse to redirect at all on a mismatch rather than silently falling back to some other registered URI. This exact-match requirement is a real security control, not a formality: a looser match lets an attacker who controls any URL that merely resembles the registered one receive a legitimate user's authorization code and exchange it for tokens issued in that user's name. Chapter 13 verifies this concretely against a live authorization server — and found a public demo client that does NOT enforce this correctly, a live, reproducible finding (independently confirmed by the coordinator), used there as a cautionary, non-production example. Keycloak's own Valid Redirect URIs field enforces this same exact-match rule but documents a narrow extension: a trailing wildcard (https://host.com/path/*), with userinfo/path-traversal (/../) segments explicitly excluded from wildcard matching and the bare * wildcard explicitly warned against in production. Chapter 24 registers a path-scoped wildcard for exactly this reason. Chapter 45's hardening checklist cites this exact-match rule as its \"unspecific redirect URIs\" checklist row.", category: "SSO & Federation", chapters: ["sso-and-federation", "oauth2-core", "clients-and-scopes", "securing-a-frontend-spa", "security-hardening-and-upgrades"] },
  { term: "SSO session", definition: "The session an Identity Provider maintains for a browser after a successful login, tracked so that a later redirect from a different connected application is recognized without asking the user to re-authenticate. This session, not a shared password, is what makes SSO work. Keycloak implements this concretely at the realm level with two independent clocks: SSO Session Idle (an inactivity timeout — the session dies if unused longer than this) and SSO Session Max (an absolute ceiling regardless of activity), both configurable per realm (e.g. northwind-apps set these to 3,600s and 28,800s respectively in chapter 21, loosening idle for convenience while tightening max for the same underlying security reason). A third, independent, shorter-lived clock — Access Token Lifespan — governs individual bearer tokens minted during that session, not the session itself; a session commonly outlives many access-token refresh cycles. Full session-management depth (client sessions, offline sessions, concurrent-session limits) is chapter 29's subject. Chapter 29 demonstrated both halves of this for real against a live Keycloak 26.8.2: (1) revoking a session via DELETE sessions/{id} or POST users/{id}/logout immediately invalidates every token tied to it — a subsequent refresh attempt returns invalid_grant / 'Session not active,' confirmed with an independent GET users/{id}/sessions read showing an empty array; and (2) the SSO-across-clients mechanism itself, confirmed with a curl-only cookie-jar simulation: authenticating to one client sets a KEYCLOAK_SESSION cookie on Keycloak's own domain, and a second, completely separate registered client requesting authorization from the same browser received an immediate 302 redirect with its own authorization code — no login form, no credentials resubmitted — both tied to the exact same underlying session id.", category: "SSO & Federation", chapters: ["sso-and-federation", "realms", "sessions-deep-dive"] },
  { term: "LDAP bind (federation context)", definition: "The operation an IAM system performs against an external directory (LDAP or Active Directory) to check a submitted credential, as part of identity federation — the directory, not the IAM system, remains the authoritative store for the credential. Introduced conceptually in chapter 4; implemented in chapter 32.", category: "SSO & Federation", chapters: ["sso-and-federation", "user-federation-ldap"] },
  { term: "Enterprise SSO", definition: "An arrangement where a B2B application's enterprise customer wants its own employees to sign in using the customer's own corporate Identity Provider, rather than a password issued by the application vendor. From the vendor's point of view, this is identity brokering: the vendor is the SP/RP, and the customer's corporate IdP is the external IdP being trusted.", category: "SSO & Federation", chapters: ["sso-and-federation", "identity-brokering"] },
  { term: "Social login", definition: "A specific, consumer-facing case of identity brokering where the external IdP is a large consumer identity provider such as Google or Microsoft, rather than a corporate/enterprise IdP. Covered conceptually here; Keycloak's social-login identity provider configuration is covered in chapter 31.", category: "SSO & Federation", chapters: ["sso-and-federation", "identity-brokering"] },

  { term: "Bearer token", definition: "A token whose only required proof of authorization is possession of the token itself — whoever holds and presents it can use it, with no built-in check that the presenter is the party it was originally issued to. If a bearer token is stolen, the thief can use it exactly as the real owner could, until it expires.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions", "securing-a-backend-api"] },
  { term: "Claim", definition: "A key-value assertion carried inside a token that the issuer is vouching for — e.g. who the token is for, who issued it, when it expires, or what the subject is allowed to do. Purely conceptual here; the exact wire format (JWS/JWE/JWK) is chapter 16's subject.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Access token", definition: "A token presented to a resource server (an API) to prove an already-authenticated subject's authorization to use it, typically short-lived by design so a stolen copy stays useful for as little time as possible.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Refresh token", definition: "A longer-lived token used to obtain new access tokens without re-authenticating the principal from scratch. Its lifetime is a direct security/convenience trade-off: longer keeps users logged in with less friction, but gives a thief who steals it a longer usable path to new access tokens.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Refresh-token rotation", definition: "A mitigation for the revocation problem: keep access tokens very short-lived and use a refresh token (itself revocable, since refreshing typically involves a server-side check) to mint new ones — moving the \"can we still trust this\" check to a less frequent point rather than eliminating it.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Stateless authentication", definition: "An architecture where a token is self-contained and verifiable by any server with no database lookup required. Scales well across many independent servers with no shared session store, but makes early revocation hard — see the revocation problem.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Stateful authentication", definition: "An architecture where a short, opaque session identifier requires a server-side lookup against a shared store on every request. Trivially revocable (delete the server-side record), at the cost of needing that shared store reachable by every server.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Session (authentication session)", definition: "A server-side record of an authenticated subject's ongoing interaction, referenced by a short identifier the client holds (such as a cookie value) that is meaningless on its own without a server-side lookup. Full Keycloak session mechanics in chapter 29.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Session store", definition: "The shared, server-side data store that a stateful authentication system looks a session identifier up against on every request. Must be reachable by every server handling requests, which becomes its own piece of infrastructure to run and scale.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "The revocation problem", definition: "The genuine, unsolved-in-general tension that a stateless bearer token is valid until it expires, with no clean way to invalidate it early without reintroducing the server-side lookup statelessness exists to avoid. Managed with partial mitigations (short lifetimes, refresh rotation, introspection, key rotation), never fully solved.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Token lifetime", definition: "The configured validity window of a token, from issuance to expiry. Functions as a real security control under the revocation problem, not just a convenience setting — shorter lifetimes shrink how long a stolen token stays useful.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Token introspection", definition: "A mitigation for the revocation problem where a resource server calls back to the token issuer to ask whether a token is still valid, standardized by RFC 7662: a POST to an introspection endpoint with the token, authenticated as the calling party, returning a JSON body with an active boolean plus the token's claims if it's real (and almost nothing if it isn't, deliberately, to prevent fishing for valid tokens). Works, but reintroduces the server-side lookup that statelessness was meant to avoid — and its active result depends entirely on how the authorization server implements the check: for a reference token it's a real server-side lookup; for a self-contained JWT it typically only re-verifies the signature and expiry, which is why introspecting a 'revoked' JWT can still report active: true (confirmed live in chapter 14's revocation lab). Full mechanics in chapter 14.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions", "oauth2-extended"] },
  { term: "Signing-key rotation", definition: "Replacing the cryptographic key used to sign tokens, which invalidates every token signed with the old key at once. A blunt mitigation for the revocation problem — it revokes everything, not one specific token — but sometimes exactly the right tool, e.g. after a suspected key compromise. Mechanically: a verifier picks the right key for a given token via the token header's kid, matched against the issuer's JWKS response; rotation publishes a new key into JWKS before any token is signed with it, keeps the outgoing key listed in JWKS for an overlap period so tokens already signed with it remain verifiable, then removes the outgoing key once every token it signed has expired. Full JWS/JWKS mechanics in chapter 16.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions", "jwt-and-crypto"] },
  { term: "Issuer claim", definition: "A claim identifying which system vouches for a given token's contents — part of the trust basis a verifier relies on when accepting a token at all.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions", "securing-a-backend-api"] },
  { term: "Audience claim", definition: "A claim identifying which service or resource server a token is meant to be used against, so a token issued for one API can't be silently reused against an unrelated one.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Blast radius (token theft)", definition: "The scope and duration of damage a stolen credential or token can cause before it stops being useful — shrinking it (e.g. via short token lifetimes) is a core strategy for managing the revocation problem rather than solving it outright.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },

  { term: "Credential stuffing", definition: "Automated, large-scale reuse of username/password pairs leaked from other, unrelated sites' breaches against a login form, betting that some fraction of users reused the same credentials. The attacker never cracks or guesses anything — the credentials are already real.", category: "Threat landscape", chapters: ["iam-threat-landscape", "password-policies-and-mfa"] },
  { term: "Password reuse", definition: "Using the same password (or a trivial variation of it) across multiple unrelated accounts. The single behavior that makes credential stuffing effective: an attacker holding one site's breached password list can succeed against a different, unrelated site purely because of reuse.", category: "Threat landscape", chapters: ["iam-threat-landscape", "password-policies-and-mfa"] },
  { term: "Account takeover (ATO)", definition: "The end state of a successful credential-based attack: an attacker gains full, ongoing control of a legitimate user's account, typically able to change its password, email, or MFA settings and lock the real owner out.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Credential dump (breach corpus)", definition: "A large collection of username/password pairs exposed by a data breach, typically traded or published, and reused as raw input for credential-stuffing attacks against unrelated organizations.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Phishing", definition: "Tricking a user into disclosing credentials, or into approving a fraudulent MFA prompt, through a convincing fake login page, email, or message that impersonates someone or something the user trusts.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Spear phishing", definition: "Phishing targeted at a specific person or small group, using details about them (role, employer, recent events) to make the fraudulent message more convincing than a generic mass phishing email.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Adversary-in-the-middle (AiTM) phishing", definition: "A phishing technique that proxies the real login page live and relays whatever the victim submits — including a one-time MFA code — straight through to the real service in real time, which is why OTP-based MFA alone doesn't stop it.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Token theft", definition: "Stealing a valid bearer token — through a client-side vulnerability, misconfigured storage, or an intercepted network request — so it can be reused by someone other than its intended holder.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Token replay", definition: "Reusing a stolen token to authenticate again before it expires. Possible specifically because a bearer token proves nothing about who is presenting it — only that whoever holds it is trusted, which is the same property chapter 8's \"revocation problem\" is about.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Session hijacking", definition: "Stealing a session identifier or cookie to impersonate an already-authenticated session, as distinct from stealing a bearer token — the mechanism differs, but whoever holds the identifier is treated as the legitimate user until the session is invalidated.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "MFA fatigue (push bombing)", definition: "Repeatedly sending MFA approval push notifications to a target, often in rapid bursts or late at night, until a tired or confused user approves one by mistake. Requires the attacker to already hold a valid password; the bombing is how they get past the second factor.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Brute-force attack", definition: "Systematically trying many password guesses against a single account, as distinct from credential stuffing's use of already-known, previously breached credentials across many accounts.", category: "Threat landscape", chapters: ["iam-threat-landscape", "password-policies-and-mfa", "security-hardening-and-upgrades"] },
  { term: "Cross-site scripting (XSS)", definition: "A web application vulnerability that lets an attacker run arbitrary script in a victim's browser within the context of a trusted site, which can be used to read anything that browser session holds — including a bearer token kept in client-side storage.", category: "Threat landscape", chapters: ["iam-threat-landscape", "securing-a-frontend-spa"] },
  { term: "Rate limiting", definition: "Capping how many requests (such as login attempts) a client can make in a given time window, used as a direct defense against credential stuffing and brute-force attacks. Configured in Keycloak as part of Brute Force Detection, covered in chapter 30.", category: "Security practices", chapters: ["iam-threat-landscape"] },
  { term: "Threat model", definition: "A structured description of who might attack a system, how, and what they'd gain, used to decide which defenses are worth building. This chapter's five threats are a starting threat model for any IAM deployment.", category: "Security practices", chapters: ["iam-threat-landscape"] },
  { term: "Attack surface (IAM context)", definition: "The set of points in an identity system an attacker could target — the login form, the MFA step, token issuance, and active sessions are the four this chapter maps threats onto.", category: "Security practices", chapters: ["iam-threat-landscape"] },
  { term: "Defense in depth (IAM context)", definition: "Layering multiple independent defenses (rate limiting, MFA, short token lifetimes, session revocation) so that defeating any one of them isn't enough on its own to compromise an account or session.", category: "Security practices", chapters: ["iam-threat-landscape"] },

  { term: "IGA (Identity Governance & Administration)", definition: "The discipline of provisioning, reviewing, and governing access over an identity's entire lifetime — making sure access is granted correctly, stays correct as circumstances change, and is provably correct when audited. A process discipline, distinct from the market category of tooling (SailPoint, Saviynt, etc.) that automates it, which chapter 12 covers separately.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Joiner-Mover-Leaver (JML)", definition: "The enterprise HR-driven vocabulary for chapter 2's generalized identity lifecycle, not a separate model: Joiner maps onto create+activate, Mover maps onto modify, and Leaver maps onto suspend+delete. Mover is the event most often implemented incorrectly — it should remove access tied to the old role, not just add access for the new one.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Access review (recertification)", definition: "A periodic, deliberate check of who has access to what, specifically to catch access that accumulated over time but is no longer justified — a finished project's leftover grant, an exception nobody revoked, or access stacked from a role change that was only ever additive. Exists because event-driven provisioning/deprovisioning only reacts to events someone remembered to trigger; a review is the scheduled act of looking anyway.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Segregation of Duties (SoD)", definition: "The principle that no single identity should hold two permissions whose combination lets that identity both carry out a sensitive action and be the only check on that same action — also called Separation of Duties. Neither permission alone is the problem; the danger is one identity holding both, which erases the independent check the second permission exists to provide.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Toxic combination", definition: "The specific set of permissions that creates a Segregation of Duties violation: the ability to both perform an action and be the sole check on that same action (e.g. creating a payment and approving it). Combinations can form later from two separately reasonable-looking grants, which is why they must be re-checked at every access review, not only at grant time.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Access certification", definition: "The specific act of a reviewer with the authority to judge it examining one entitlement and deciding whether to keep it or revoke it — the granular unit of work inside a recertification campaign.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Attestation (access certification)", definition: "A reviewer's formal, recorded confirmation that a specific access entitlement is still correct (or a recorded decision to revoke it) — what turns an access review from an informal glance into something an auditor can later verify actually happened.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Entitlement", definition: "A single, specific grant of access — one role, one group membership, one permission on one system — rather than everything an identity can do treated as one undifferentiated blob. Access reviews and certifications operate entitlement by entitlement so a reviewer can judge each grant on its own merits.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Recertification campaign", definition: "An organized, scheduled exercise bundling many individual access certifications together — typically all of one manager's reports, or all access to one sensitive system — reviewed on the same cadence (often quarterly or annual) so an organization has a complete, dated record rather than an ad-hoc patchwork of individual checks.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Stale access", definition: "Access an identity still holds but no longer has a legitimate business reason to hold — the specific thing access reviews exist to find, typically left over from a finished project, a prior role, or a temporary exception that was never revoked.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Role change (mover event)", definition: "The JML 'Mover' event: an identity changes team, job function, or location within the organization. Correctly implemented, it both grants access tied to the new role and removes access tied to the old role — treating it as purely additive (granting only) is the most common beginner mistake in identity governance. Reproduced for real against a running Keycloak realm in chapter 23: moving Northwind Apps' Priya from support-agent/Support to platform-engineer/Engineering required two grants (add-roles + group update) and two removals (remove-roles + group delete) — confirmed by re-querying role-mappings/realm and groups before and after and observing the old role/group were completely absent afterward, not merely superseded.", category: "Identity governance", chapters: ["identity-governance", "roles-and-groups"] },
  { term: "Compensating control", definition: "A documented, explicit alternative safeguard used when true Segregation of Duties isn't practically achievable (e.g. on a very small team) — such as a mandatory secondary review by someone outside the team, or an automatic flag on any transaction a conflicted identity both created and approved. An acknowledged trade-off, not a silent gap.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Four-eyes principle (dual control)", definition: "The underlying principle behind Segregation of Duties: a sensitive action requires two different people to look at it — one to perform it, one to independently verify it — before it takes effect. SoD is the organizational policy that structurally guarantees four-eyes rather than merely hoping for it.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Orphaned account", definition: "An account whose owning identity has left the organization or a role, but whose access was never actually removed — usually caused not by a missing deprovisioning process but by a missing trigger for an existing one. Periodic access review is the backstop that catches orphaned accounts when the event that should have deprovisioned them was missed.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Rubber-stamping", definition: "The failure mode where a reviewer in a recertification campaign approves all entitlements without actually evaluating any of them individually, usually under time pressure. Produces a campaign record indistinguishable from a genuine review while providing none of its security value, since a review's benefit comes entirely from the judgment applied during it.", category: "Identity governance", chapters: ["identity-governance"] },

  { term: "GDPR", definition: "The EU's General Data Protection Regulation (Regulation (EU) 2016/679, in force since 25 May 2018), establishing data subject rights, a lawful-basis requirement, and data minimization obligations for anyone processing EU residents' personal data — including the accounts, profiles, and access logs an IAM system manages.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Data subject rights", definition: "The set of rights GDPR grants a person over their own personal data, including the right of access (Art. 15), erasure (Art. 17), and portability (Art. 20) — an IAM system must be able to locate, export, and delete a specific person's account and attribute data on request.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Right to erasure (right to be forgotten)", definition: "GDPR Article 17's right for a person to have their personal data deleted on request. For IAM systems this creates a real tension with audit-trail retention requirements; the common compromise is pseudonymizing rather than deleting log entries, with legal sign-off — not a universally clean resolution.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Data minimization", definition: "GDPR Article 5(1)(c)'s principle that only the personal data actually necessary for a stated purpose should be collected and retained — applies directly to which identity attributes an IAM system is allowed to ask for and keep.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Lawful basis for processing", definition: "GDPR Article 6's requirement that every instance of processing personal data have a documented legal justification (consent, contract necessity, legal obligation, legitimate interest, etc.) — an IAM system can't collect or retain identity attributes without one.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Data portability", definition: "GDPR Article 20's right for a person to receive their personal data in a structured, commonly used, machine-readable format and transmit it to another controller — relevant to how an IAM system exports a user's account data on request.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "SOC 2", definition: "An attestation framework, maintained by the AICPA, under which an independent auditor reports on an organization's controls against the Trust Services Criteria. The Security criterion — the only one required in every report — is the one most relevant to IAM, testing for evidence of access reviews, MFA enforcement, and logging.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Trust Services Criteria (TSC)", definition: "The AICPA's set of criteria categories (Security, Availability, Processing Integrity, Confidentiality, Privacy) that a SOC 2 report is audited against. The version currently in force is the 2017 criteria as revised in 2022; a further revision exists only as an exposure draft under public comment, not yet in force.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "HIPAA Security Rule", definition: "The U.S. regulation (45 CFR Part 164, Subpart C) setting administrative, physical, and technical safeguard requirements for protecting electronic protected health information (ePHI) — its technical safeguards (access control, unique user identification, audit controls, person/entity authentication) map directly onto this course's AAA model.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Minimum necessary standard", definition: "A HIPAA Privacy Rule requirement (45 CFR §164.502(b), §164.514(d)) — not the Security Rule, despite the two often being discussed together — that covered entities and business associates make reasonable efforts to limit PHI use, disclosure, and access requests to the minimum needed for the purpose at hand. Access control design is one of the main ways this is operationally implemented, concretely via relationship-based 'care team' access models.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Protected Health Information (PHI / ePHI)", definition: "Individually identifiable health information that HIPAA regulates; electronic PHI (ePHI) specifically is what the HIPAA Security Rule's safeguards protect.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "PCI-DSS", definition: "The Payment Card Industry Data Security Standard, maintained by the PCI Security Standards Council, mandatory for any organization that stores, processes, or transmits payment card data. Its Requirements 7, 8, and 10 are, respectively, least privilege, authentication/MFA, and accounting/audit trail under PCI-DSS's own numbering.", category: "Compliance & Governance", chapters: ["compliance-for-iam", "case-study-riverside"] },
  { term: "Cardholder Data Environment (CDE)", definition: "The scope boundary PCI-DSS defines: the systems, people, and processes that store, process, or transmit cardholder data, plus anything connected to them — PCI-DSS's access, authentication, and logging requirements apply within this boundary.", category: "Compliance & Governance", chapters: ["compliance-for-iam", "case-study-meridian"] },
  { term: "ISO/IEC 27001", definition: "The international standard for information security management systems (ISMS). The current edition, ISO/IEC 27001:2022, reorganized its Annex A control list from the 2013 edition's 114 controls across 14 categories into 93 controls across 4 themes, renumbering access-control content into the 5.x/8.x ranges.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Annex A (ISO 27001)", definition: "The normative list of security controls an ISO/IEC 27001-certified organization selects from and documents in its Statement of Applicability. Its exact numbering differs materially between the 2013 and 2022 editions — always confirm which edition a document cites before trusting a control number.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Statement of Applicability (SoA)", definition: "The document an ISO/IEC 27001-certified organization produces listing which Annex A controls it has selected, excluded, and implemented, and why — the artifact an auditor actually reviews rather than the standard's text itself.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },

  { term: "PAM (Privileged Access Management)", definition: "The IAM market category and discipline focused on managing the smallest, highest-risk slice of identities in an organization — privileged accounts whose compromise would cause outsized damage. Adds credential vaulting, session recording, and just-in-time privilege elevation on top of whatever workforce IAM/CIAM system already handles everyday authentication and authorization.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Privileged account", definition: "Any account whose normal operating permissions exceed what a typical end user holds — root/domain-admin accounts, database admin accounts, cloud-provider root accounts, and broadly-permissioned service accounts. Not every admin account is privileged in the PAM sense; scope and blast radius, not the word \"admin,\" determine it.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Credential vaulting", definition: "Storing privileged credentials (root passwords, database connection strings, SSH keys, API secrets) in an encrypted vault rather than having them memorized or shared directly; a human or script checks a credential out when needed instead of holding it permanently.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Session recording (PAM context)", definition: "Recording keystrokes and/or screen activity during a privileged session (e.g. an SSH session to a production database) for later audit — the PAM-specific analogue of a security camera on a vault door, capturing what happened during access, not just that access occurred.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Just-in-time (JIT) privilege elevation", definition: "Granting elevated permissions for a limited window and a specific task rather than holding them permanently; the permission is automatically revoked afterward, shrinking how long a compromised privileged credential would remain dangerous. Contrast with standing privileged access.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Standing privileged access", definition: "Elevated permissions held permanently rather than granted just-in-time for a specific task — the default a PAM program tries to reduce, since a permanently-elevated account is dangerous for as long as its credential exists, not just while it's actively being used.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Break-glass access", definition: "A deliberately logged, alarm-raising emergency path that bypasses a PAM program's normal request-approval loop when something urgent requires immediate privileged access; used rarely and audited heavily whenever it is used.", category: "Market & vendors", chapters: ["iam-market-landscape", "case-study-riverside"] },
  { term: "Bastion host (jump server)", definition: "A single hardened chokepoint that all privileged connections to sensitive systems must pass through, giving a PAM program one place to monitor, record, and cut off access instead of administrators connecting directly to sensitive systems from anywhere.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Total cost of ownership (TCO) in an IAM context", definition: "The full cost of running an identity system, not just its license or subscription price — including infrastructure, operational expertise, patching/tuning labor, data-residency implications, and vendor lock-in risk. The right lens for comparing a self-hosted open-source system to a commercial SaaS alternative, since \"no license fee\" is not the same claim as \"cheap overall.\"", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Open-source vs. commercial IAM", definition: "A framing axis for comparing identity products: an open-source product (like Keycloak) carries no license fee and can be inspected/modified freely, in exchange for the adopting organization owning more of the operational and expertise burden; a commercial product bundles that operational work into its price. Not the same axis as self-hosted vs. SaaS — a commercial product can still be self-hosted, and some open-source projects are offered as managed SaaS by third parties.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Self-hosted vs. SaaS/managed IAM", definition: "A framing axis for comparing identity products based on who operates the running system: self-hosted means the adopting organization runs its own infrastructure (full control, full operational responsibility); SaaS/managed means a vendor runs it (less control and less visibility into exactly how it behaves or where data lives, in exchange for outsourcing the operational burden).", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Data residency (IAM context)", definition: "Where identity data is physically stored and which jurisdiction's laws govern it — a real driver toward self-hosting an identity system for regulated organizations, independent of the pure dollar-cost TCO comparison between self-hosted and SaaS options.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Vendor lock-in (IAM context)", definition: "The cost and difficulty of leaving a given identity product later — driven by proprietary extensions, migration tooling quality, and contract terms. Rarely shows up on an invoice, but belongs in the same total-cost-of-ownership conversation as subscription price and operational burden.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Operational burden (IAM context)", definition: "The ongoing work of keeping an identity system running correctly and securely — patching, monitoring, capacity planning, clustering/failover, and maintaining the protocol expertise to configure it correctly. The main thing a self-hosted deployment takes on that a SaaS deployment largely outsources to the vendor.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Four-category IAM market taxonomy", definition: "This course's framing of the IAM market as four distinct, overlapping-but-separate categories — Workforce IAM, CIAM, PAM, and IGA — distinguished by who is managed (an organization's own people vs. external customers) and what kind of access is at stake (everyday application access vs. elevated/governance-level access). A vendor's strength in one category doesn't imply fitness for another.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Point solution vs. platform IAM", definition: "A framing distinction between a vendor/product that does one IAM job well (e.g. a dedicated PAM-only or IGA-only tool) versus a broader platform that bundles multiple categories (e.g. workforce IAM and CIAM together). Bundling convenience is a real benefit, but it doesn't guarantee best-in-category depth in every bundled piece.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Corporate ownership volatility (IAM market)", definition: "The IAM/PAM/IGA vendor landscape changes ownership and branding fast via acquisition and rebrand (e.g. ForgeRock into Ping Identity, CyberArk into Palo Alto Networks' Idira) — a reason to re-verify a vendor's current corporate status before relying on it in a real purchasing decision, rather than trusting a reference written even a year earlier.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Privileged session", definition: "A connected, active use of a privileged account against a sensitive system (e.g. an SSH session to a production database or an RDP session to a domain controller) — the unit of work that PAM tooling specifically targets for routing through a bastion host, recording, and time-boxing via just-in-time elevation.", category: "Market & vendors", chapters: ["iam-market-landscape"] },

  { term: "Resource Owner", definition: "OAuth 2.0's name for the entity capable of granting access to a protected resource — in nearly every real scenario, the human end user. Distinct from chapter 7's IdP/SP/RP vocabulary, which never needed to name the end user as a formal role.", category: "OAuth 2.0", chapters: ["oauth2-core", "keycloak-authorization-services"] },
  { term: "Client (OAuth role)", definition: "OAuth 2.0's name for the application requesting access to a protected resource on the resource owner's behalf — \"the app.\" Not identical in shape to chapter 7's SP/RP: an OAuth client requests and holds tokens to call APIs, while authenticating the end user directly is OpenID Connect's job (chapter 15), layered on top. In Keycloak, this abstract role becomes a concrete, realm-scoped client record. Two settings decide its real-world behavior: publicClient (confidential clients get an auto-generated client secret and are expected to run somewhere that secret stays hidden; public clients get none and rely on PKCE instead) and which grant-type toggles (standardFlowEnabled, directAccessGrantsEnabled, serviceAccountsEnabled) are turned on. Registering a client the wrong type (e.g. a secret on a browser SPA) is a real, exploitable mistake, not a style choice.", category: "OAuth 2.0", chapters: ["oauth2-core", "clients-and-scopes", "securing-a-frontend-spa"] },
  { term: "Authorization Server", definition: "The OAuth 2.0 role that authenticates the resource owner, obtains their authorization, and issues access tokens to the client. Roughly fills chapter 7's Identity Provider (IdP) role, though the two vocabularies aren't a clean 1:1 rename. Concretely, a Keycloak realm is this role's Keycloak instantiation: a fully isolated namespace of its own users, credentials, clients, roles, groups, identity providers, and authentication flows, invisible to every other realm on the same server. One Keycloak installation can host many realms side by side, each independently playing the Authorization Server role for its own clients — chapters 13-15 used a third-party Authorization Server (Duende's public demo IdentityServer); starting chapter 20 the reader runs their own realm instead.", category: "OAuth 2.0", chapters: ["oauth2-core", "keycloak-architecture"] },
  { term: "Resource Server", definition: "The OAuth 2.0 role hosting protected resources and accepting requests bearing an access token — in plain terms, an API. Has no equivalent in chapter 7's IdP/SP/RP vocabulary, because SSO/federation never needed to name \"a protected API\" as a role.", category: "OAuth 2.0", chapters: ["oauth2-core", "securing-a-backend-api"] },
  { term: "Authorization grant", definition: "The general OAuth 2.0 term for whatever a client presents to the authorization server to prove it's entitled to a token on the resource owner's behalf — an authorization code, a set of client credentials, a device code, etc. \"Grant type\" names which specific kind is in use for a given request.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Grant type", definition: "A defined way for an OAuth 2.0 client to obtain an access token — authorization code, client credentials, device code, and the discouraged ROPC and Implicit grants among them. Full survey in chapter 13; client credentials and device code get full depth in chapter 14.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Authorization code", definition: "A short-lived, single-use value returned to the client via browser redirect after the resource owner authenticates, deliberately not powerful enough on its own to be worth stealing — it must still be exchanged at the token endpoint, server-to-server, for an actual access token.", category: "OAuth 2.0", chapters: ["oauth2-core", "securing-a-frontend-spa"] },
  { term: "Authorization endpoint", definition: "The OAuth 2.0 authorization server endpoint (conventionally /authorize) the client redirects the resource owner's browser to, to begin authentication and authorization — e.g. /connect/authorize on the Duende demo server used in chapter 13's lab.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Token endpoint", definition: "The OAuth 2.0 authorization server endpoint (conventionally /token) a client calls directly, server-to-server, to exchange an authorization grant (a code, client credentials, etc.) for an actual access token — never called from inside the browser redirect flow itself.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Scope (OAuth)", definition: "A client-requested, space-separated identifier naming a slice of access being asked for (e.g. openid, profile, api) — the mechanism by which an OAuth token's power is limited to only what was actually requested and granted, rather than full access to everything the resource owner could authorize. In Keycloak, this becomes a concrete client scope: a named, reusable bundle of protocol mapper configuration and role-scope mappings, attachable to any client as either a default scope (always included, no scope= parameter needed) or an optional scope (only included if explicitly requested). Defining a scope once and attaching it to many clients means a later claim change propagates everywhere at once. Contrast with chapter 37's Authorization scope (Keycloak) — a different, unrelated mechanism that happens to share the word \"scope.\"", category: "OAuth 2.0", chapters: ["oauth2-core", "clients-and-scopes", "securing-a-backend-api", "service-to-service-auth", "keycloak-authorization-services"] },
  { term: "Consent (OAuth)", definition: "The resource owner's explicit approval of the specific scopes a client is requesting, typically shown as a screen during the authorization code flow. Some authorization servers skip it for pre-trusted first-party clients — the live lab's demo clients proceed straight from login to redirect with no separate consent screen.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Resource Owner Password Credentials (ROPC)", definition: "A legacy OAuth 2.0 grant type where the client collects the resource owner's username and password directly and trades them for a token in one request, with no redirect to the authorization server at all. Discouraged by current best practice: it trains users to type credentials into arbitrary client apps and defeats the authorization server's ability to apply its own MFA or step-up checks. Full security reasoning in chapter 18.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Implicit grant (OAuth)", definition: "A legacy OAuth 2.0 grant type that returns an access token directly in the browser's URL fragment, skipping the authorization-code exchange step. Discouraged by current best practice: a token in a URL fragment is exposed to browser history, referrer leakage, and any script able to read the current URL. Full security reasoning in chapter 18.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "PKCE (Proof Key for Code Exchange)", definition: "An OAuth 2.0 extension (RFC 7636) where the client generates a secret (code_verifier) and sends only its one-way hash (code_challenge) in the initial authorize request; the plaintext verifier is only revealed at the final token exchange, so an intercepted authorization code alone isn't enough to obtain tokens. Current best practice recommends it on every authorization code flow, not only for public clients that lack a secret.", category: "OAuth 2.0", chapters: ["oauth2-core", "securing-a-frontend-spa"] },
  { term: "Code verifier", definition: "PKCE's client-generated, high-entropy random string (43-128 characters per RFC 7636 §4.1), created fresh per authorization attempt and kept on the client until the final token exchange, where it's sent in plaintext so the server can verify it matches the earlier code_challenge.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Code challenge", definition: "PKCE's derived value sent in the clear in the initial authorize request: SHA-256(code_verifier), base64url-encoded with padding stripped, under the S256 method. One-way — it cannot be reversed back into the verifier, which is exactly why intercepting it in transit doesn't help an attacker.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "code_challenge_method", definition: "The PKCE authorize-request parameter naming how code_challenge was derived from code_verifier — \"S256\" (SHA-256 hash, mandatory to implement on the server) or \"plain\" (the challenge equals the verifier itself, kept only for constrained clients that can't hash, and strictly weaker since it offers no protection if the challenge itself is intercepted).", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Open redirector (OAuth context)", definition: "The security failure RFC 6749 §3.1.2.2 names directly: an authorization endpoint that lacks a redirect-URI registration requirement can be abused as a generic open redirector, sending a user-agent anywhere an attacker specifies under the trusted authorization server's own domain.", category: "OAuth 2.0 security", chapters: ["oauth2-core"] },
  { term: "Authorization code injection", definition: "An attack where an authorization code intended for one redirect destination is captured and submitted to a different destination (often the attacker's own), exploiting loose or missing redirect_uri exact-match validation. Chapter 13 demonstrates this live and concretely against a public demo server whose redirect_uri validation was found not to enforce RFC 6749's exact-match requirement.", category: "OAuth 2.0 security", chapters: ["oauth2-core"] },

  { term: "Device code", definition: "The opaque code an authorization server issues to the constrained device itself during a device authorization request, used only in the device's own polling requests to the token endpoint — never shown to the human user.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "User code", definition: "The short, human-typeable code issued alongside a device code, displayed by the constrained device and entered by the human at the verification URI to link their browser session to that specific pending device authorization request.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Verification URI", definition: "The URL a device-flow user visits on a separate, browser-capable device to enter the user code and complete login/consent. verification_uri_complete embeds the user code as a query parameter so it can be opened directly (e.g. from a QR code) without the human retyping the code.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Device-flow polling", definition: "The repeated token-endpoint requests a device-flow client makes while waiting for the human step to finish, honoring the server-advertised interval. The authorization server responds authorization_pending until approval, slow_down if the client polls faster than instructed, and an error (or real tokens) once the code is resolved or expires.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Client credentials grant", definition: "An OAuth 2.0 grant (RFC 6749 §4.4) for pure machine-to-machine access: the client authenticates directly to the token endpoint with its own credentials and receives an access token scoped to itself, with no resource owner, browser, or user context involved at any point. Previewed in chapter 13 (confirmed live against the demo server's m2m client).", category: "OAuth grants", chapters: ["oauth2-extended", "oauth2-core", "securing-a-backend-api", "service-to-service-auth"] },
  { term: "Device authorization grant", definition: "An OAuth 2.0 grant (RFC 8628) for clients that cannot receive a browser redirect at all — a CLI tool, a smart TV, an IoT device. The constrained device requests a device code and a short user code from the authorization server, displays the user code and a verification URL, and polls the token endpoint until a human completes login and approval on a separate, more capable device. Needs no registered redirect_uri. Previewed in chapter 13; this course's primary \"real human step, real round trip\" lab here in chapter 14.", category: "OAuth grants", chapters: ["oauth2-extended", "oauth2-core"] },
  { term: "Machine-to-machine (M2M) authentication", definition: "One backend system or service authenticating directly to another with no human or user context in the request at all. The client credentials grant is OAuth's standard mechanism for this.", category: "OAuth grants", chapters: ["oauth2-extended", "service-to-service-auth"] },
  { term: "Token revocation", definition: "Asking an authorization server to invalidate a specific, already-issued token before its natural expiry, via a dedicated revocation endpoint (RFC 7009). Whether this actually stops the token from working depends on whether the server has a server-side record of that token to delete — see self-contained access token.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Revocation endpoint", definition: "The OAuth endpoint a client calls to request that a specific token be invalidated early. RFC 7009 §2.1 permits the authorization server to return success (HTTP 200) even when it cannot actually invalidate the identified token, specifically so the endpoint can't be used to probe which tokens are real.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Reference token (opaque access token)", definition: "An access-token design where the token itself is a meaningless random string and the authorization server stores the actual token data server-side. Revocation is immediately effective — deleting the server-side record makes the very next introspection call correctly report the token inactive — at the cost of needing a store the server must maintain and look up on every check.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Self-contained access token", definition: "An access-token design (typically a JWT) where every claim and a signature live inside the token itself, verifiable by anyone holding the signing key's public half with zero server-side lookup. Revoking one can return success without any effect, because there is no server-side record to delete — introspection against it typically re-checks only the signature and expiry, not a revocation list. A direct, concrete instance of chapter 8's revocation problem, confirmed live in this chapter's own lab.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Token exchange", definition: "An OAuth 2.0 extension grant (RFC 8693, urn:ietf:params:oauth:grant-type:token-exchange) letting a client trade one security token for another — commonly to downscope a token's privilege before forwarding it downstream, or to support one service acting for another via delegation or impersonation. Covered conceptually only here, since this course's live demo server doesn't support a live lab for it.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Subject token", definition: "In a token-exchange request (RFC 8693), the token identifying the party on whose behalf, or as whom, the newly issued token is being requested.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Actor token", definition: "In a token-exchange request (RFC 8693), an optional second token identifying the immediate party making the exchange request itself, distinct from the subject the resulting token is about — present when the exchange needs to record who is actually making the call.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Impersonation (token exchange)", definition: "A token-exchange outcome (RFC 8693) where the issued token asserts the subject's identity with no act claim recording that it was exchanged on their behalf — a downstream service cannot distinguish the resulting request from one the original subject made directly.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Delegation (token exchange)", definition: "A token-exchange outcome (RFC 8693) where the issued token asserts the subject's identity but retains an act claim identifying the actor exercising it — a downstream service can see that one party is acting on behalf of another, rather than being indistinguishable from the subject's own request.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Downscoping", definition: "Using token exchange (or a similar mechanism) to trade a token for a new one with a narrower scope and/or audience than the original, so a token forwarded to a less-trusted downstream service carries only the minimum privilege it actually needs.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Active (introspection claim)", definition: "The boolean field at the center of an RFC 7662 introspection response: true if the authorization server currently considers the token valid, false otherwise (including for tokens it has never heard of, which get back almost no other information deliberately).", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },

  { term: "OpenID Connect (OIDC)", definition: "An identity layer built on top of OAuth 2.0, adding a standardized ID token, a discovery document, and a UserInfo endpoint so a client can learn who authenticated, not just get authorization to call an API. Reuses OAuth's grants (authorization code, device, etc.) unchanged.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "Discovery document", definition: "A single, well-known JSON document (fetched from /.well-known/openid-configuration, appended to an issuer URL) that an OIDC provider publishes describing its own endpoints and capabilities, so a client can learn them without hardcoding. The concrete, standardized implementation of chapter 7's general metadata/trust concept.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "ID token", definition: "A JWT issued alongside the usual OAuth tokens when a request includes the openid scope, carrying claims about who authenticated and when. Proves authentication, not authorization — its audience (aud) claim names the client itself, never a resource server, so it should never be sent to an API in place of an access token.", category: "OpenID Connect", chapters: ["openid-connect", "securing-a-frontend-spa"] },
  { term: "UserInfo endpoint", definition: "An OIDC endpoint, named in the discovery document, that returns the same kind of standard claims as an ID token when called live with a valid access token issued with at least the openid scope. Useful when claims might have changed since login or when only an access token (not an ID token) is available.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "openid scope", definition: "The OIDC scope that makes a request an identity request rather than plain OAuth — including it is what tells the authorization server to also issue an ID token. Required for OIDC; without it, no ID token is issued and UserInfo access is not granted.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "profile scope", definition: "A standard OIDC scope that unlocks a bundle of standard profile claims (name, given_name, family_name, preferred_username, picture, locale, and others) on the ID token and/or UserInfo response, if requested.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "email scope", definition: "A standard OIDC scope that unlocks the email and email_verified claims on the ID token and/or UserInfo response, if requested.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "Standard claim (OIDC)", definition: "A claim OIDC Core itself defines and names (e.g. sub, name, email, email_verified), as opposed to a custom claim a specific provider adds on top. Standard claims are organized into scope bundles (profile, email) so a client requests one scope rather than naming claims individually.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "Custom claim", definition: "A claim beyond OIDC's standard set that a provider defines and advertises itself (e.g. a tenant_id or subscription-tier claim) — not something a client can request into existence by trying arbitrary scope names. In Keycloak, configured via a client scope's protocol mapper. Concretely demonstrated in chapter 24: a Keycloak client scope's protocol mapper (type oidc-usermodel-attribute-mapper) reading a real user attribute (department) and writing it under a chosen claim name into the ID token, access token, and/or UserInfo response via three independent boolean flags (id.token.claim, access.token.claim, userinfo.token.claim). Verified live: a real token minted for a real user carried \"department\": \"Engineering\" in both the ID token and access token, and the same value came back from a live UserInfo call.", category: "OpenID Connect", chapters: ["openid-connect", "clients-and-scopes"] },
  { term: "claims_supported", definition: "A field in the OIDC discovery document listing every claim a provider is willing to return, across all of its supported scopes — an advertised ceiling. A claim missing from this list can never be produced by any scope combination; getting it requires the provider to add and advertise a custom claim.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "scopes_supported", definition: "A field in the OIDC discovery document listing every scope a provider accepts, standard and provider-specific. Requesting a scope not in this list is simply not honored, not silently granted.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "sub (subject claim)", definition: "The ID token/UserInfo claim carrying a stable, provider-assigned identifier for the authenticated principal — the OIDC-specific instance of chapter 2's general Subject concept, concretely realized as one JSON field every ID token must carry.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "email_verified claim", definition: "A standard OIDC claim distinguishing 'this email address was confirmed through a verification flow' from merely 'a user typed this into a form.' Conflating a successful login with a verified email is a real, consequential application bug this claim exists specifically to prevent.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "nonce (OIDC)", definition: "A random value a client optionally sends in the authorization request and the provider echoes back unchanged inside the ID token, letting the client verify this specific ID token was issued in response to this specific request it made — a defense against replay and mix-up attacks, covered in full in chapter 18.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "auth_time claim", definition: "An ID token claim recording when the user actually authenticated, distinct from iat (when this particular token was issued) — the distinction matters once refresh tokens can mint a new ID token well after the original login event.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "jwks_uri", definition: "A discovery-document field naming where a client fetches the provider's current public key set to verify an ID token's signature, looked up by kid rather than hardcoded. Full signature-verification mechanics are chapter 16's subject; this chapter only establishes that the URL itself comes from discovery, not a hardcoded value.", category: "OpenID Connect", chapters: ["openid-connect"] },

  { term: "JWS (JSON Web Signature)", definition: "A JSON-based format (RFC 7515) for cryptographically signing a payload so a recipient can verify who signed it and that it hasn't been altered, without hiding the payload's contents — anyone who has the token can still read it. Most access and ID tokens issued by OAuth/OIDC providers, including every token this course has decoded so far, are JWS, not JWE.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWE (JSON Web Encryption)", definition: "A JSON-based format (RFC 7516) for encrypting a payload so only a holder of the right decryption key can read its contents. Far less common in everyday OAuth/OIDC deployments than JWS — most access and ID tokens are signed, not encrypted — but used when a token's claims themselves need to stay confidential from anyone but the intended recipient.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWK (JSON Web Key)", definition: "A single cryptographic key represented as a JSON object (RFC 7517), carrying its key type (kty), intended use, algorithm, key id (kid), and the key material itself (e.g. an RSA public key's modulus n and exponent e). A verifier fetches JWKs, not raw key files, to check a JWS signature.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWKS (JSON Web Key Set)", definition: "A JSON document (RFC 7517 §5) containing an array of JWKs — typically every signing key an issuer currently considers valid, past and present, until retired. A verifier fetches the JWKS endpoint (often published in the discovery document's jwks_uri field, chapter 15) to get the current public keys needed to verify a JWS signature, without the issuer ever sharing a private key.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto", "securing-a-backend-api"] },
  { term: "kid (Key ID)", definition: "A header parameter inside a JWT identifying which specific key, out of possibly several in a JWKS response, was used to sign it. A verifier reads the token's kid, finds the JWK in the JWKS response whose own kid matches, and uses that key to check the signature — the mechanism that makes key rotation possible without immediately breaking every already-issued token.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWT header", definition: "The first of a JWT's three base64url-encoded, dot-separated segments. A small JSON object declaring at minimum the signing algorithm (alg) and typically the key id (kid) the verifier should use, plus a token type (typ). Readable by anyone — it is not encrypted.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWT payload", definition: "The second of a JWT's three base64url-encoded segments: the JSON object holding the token's claims (subject, issuer, audience, expiry, and so on — chapter 8). Base64url is an encoding, not encryption, so the payload is readable by anyone who has the token, a very common and consequential beginner misconception to correct early.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWT signature", definition: "The third of a JWT's three base64url-encoded segments: the cryptographic signature computed over the header and payload segments (the signing input), proving the token wasn't altered after signing and, for asymmetric algorithms, which private key signed it. It does not hide the header or payload's contents.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "base64url encoding", definition: "A URL- and filename-safe variant of base64 encoding (RFC 4648 §5) that swaps +/ for -/_ and drops padding, used to pack each JWT segment's raw bytes into text that survives being placed in a URL or HTTP header. It is reversible by anyone with no key or secret required — encoding is not encryption.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Compact serialization", definition: "The dot-separated, three-segment text form (header.payload.signature) that JWS most commonly uses on the wire — the format this course calls simply 'a JWT.' JWS also defines a more verbose JSON serialization for cases needing multiple signatures, rarely seen in everyday OAuth/OIDC use.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "alg (algorithm) header parameter", definition: "The JWT header field naming the cryptographic algorithm used to sign (or encrypt) the token, e.g. HS256 or RS256. A verifier that blindly trusts this field's value from an untrusted token, rather than enforcing an algorithm it already expects, opens the door to algorithm confusion attacks.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Algorithm confusion (alg validation)", definition: "A real, named JWT security flaw where a verifier accepts whatever algorithm a token's own alg header claims rather than enforcing an algorithm the verifier expects, letting an attacker craft a forged token using a weaker or inappropriate scheme the issuer never intended for that key (for example, tricking an RS256 verifier into treating a public key as an HMAC secret). Full defenses are chapter 18's subject; this chapter names the problem so it isn't a surprise there.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Symmetric signing (HS256)", definition: "Signing a JWT with a single shared secret key, used both to sign and to verify (HMAC-SHA256, hence HS256). Fast and simple, but every party that needs to verify a token must hold the same secret a signer uses to create one — exposing that secret anywhere lets the holder forge tokens, not just read them.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Asymmetric signing (RS256 / ES256)", definition: "Signing a JWT with a private key that only the issuer holds, verifiable by anyone holding the corresponding public key (RS256 uses RSA, ES256 uses elliptic-curve cryptography). This is why an issuer can safely publish its verification keys in a public JWKS endpoint: the public key only lets you check a signature, never forge one, unlike a symmetric secret.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Signing input", definition: "The exact bytes a JWS signature is computed over: the base64url-encoded header, a literal dot, and the base64url-encoded payload — nothing else. A verifier must reconstruct this same signing input from the token it received and check the signature against it, which is also why altering even one character of the header or payload invalidates the signature.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Key overlap period", definition: "The deliberate window during signing-key rotation where a JWKS response lists both the outgoing and incoming signing keys at once: new tokens are already signed with the new key, while tokens signed earlier with the old key remain verifiable because the old key is still present in JWKS. Ending the overlap too early — removing the old key before every token it signed has expired — breaks verification for still-valid tokens.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Digital signature", definition: "A cryptographic value computed over a message with a private (or shared secret) key, letting anyone with the matching verification key confirm both that the message hasn't been altered and, for asymmetric schemes, which key produced it — the general cryptographic primitive a JWS token applies to its header and payload.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },

  { term: "NameID", definition: "The element inside a SAML assertion's Subject that identifies the user to the SP, in a declared format (e.g. email address, or an opaque persistent identifier). Not always human-readable or reusable as an email — an SP should key its local account mapping on whatever format the IdP actually declares, not assume a specific one.", category: "Protocols", chapters: ["saml2"] },
  { term: "SubjectConfirmation", definition: "The part of a SAML assertion's Subject that ties the assertion to the specific browser exchange it was issued for (typically the bearer confirmation method, with a recipient URL and expiry), making it harder for a captured assertion to be replayed in an unrelated context.", category: "Protocols", chapters: ["saml2"] },
  { term: "AuthnRequest", definition: "The SAML protocol message an SP sends to an IdP to begin SP-initiated SSO, asking the IdP to authenticate the user and return an assertion. Small enough to be carried over the HTTP-Redirect binding as a URL parameter.", category: "Protocols", chapters: ["saml2"] },
  { term: "AuthnStatement", definition: "The part of a SAML assertion recording that authentication actually happened: when (AuthnInstant) and by what method (AuthnContextClassRef, e.g. password vs. a stronger multi-factor context).", category: "Protocols", chapters: ["saml2"] },
  { term: "AttributeStatement", definition: "The optional part of a SAML assertion carrying arbitrary name/value attributes about the user (department, role, email) that the IdP is willing to hand to this specific SP — where most of the useful payload in a SAML login lives in practice.", category: "Protocols", chapters: ["saml2"] },
  { term: "Conditions (SAML)", definition: "The part of a SAML assertion an SP must check before trusting it: a NotBefore/NotOnOrAfter validity window, plus an AudienceRestriction naming exactly which SP the assertion was issued for.", category: "Protocols", chapters: ["saml2"] },
  { term: "AudienceRestriction", definition: "A constraint inside a SAML assertion's Conditions naming exactly which SP (by entityID) is permitted to accept the assertion, preventing an assertion issued for one SP from being replayed and accepted by a different one.", category: "Protocols", chapters: ["saml2"] },
  { term: "EntityDescriptor", definition: "The root XML element of a SAML metadata document, describing one entity (an IdP or an SP) — its entityID, its certificates, and its supported endpoints/bindings — exchanged so each side can configure itself correctly against the other.", category: "Protocols", chapters: ["saml2"] },
  { term: "AssertionConsumerService (ACS)", definition: "The URL on an SP where an IdP posts a SAML assertion response, declared in the SP's metadata. The SAML equivalent of a registered redirect URI, specific to where assertions (not authorization codes) land.", category: "Protocols", chapters: ["saml2"] },
  { term: "HTTP-POST binding (SAML)", definition: "A SAML transport binding that delivers a message via an auto-submitting HTML form POST, with no practical size ceiling — the near-universal choice for carrying a signed assertion response back to the SP, since assertions routinely exceed what a URL can hold.", category: "Protocols", chapters: ["saml2"] },
  { term: "HTTP-Redirect binding (SAML)", definition: "A SAML transport binding that delivers a deflate-compressed, URL-encoded message as a query parameter on a browser redirect. Limited by practical browser URL-length ceilings, so it's typically used only for small messages like the initial AuthnRequest.", category: "Protocols", chapters: ["saml2"] },
  { term: "SP-initiated SSO", definition: "A SAML login that begins at the Service Provider: the user visits the SP first, the SP builds and sends an AuthnRequest to the IdP, and the IdP's eventual Response can be correlated back to that specific request.", category: "Protocols", chapters: ["saml2"] },
  { term: "IdP-initiated SSO", definition: "A SAML login that begins at the Identity Provider (e.g. an app-launcher portal): the user clicks a link for a specific SP with no preceding AuthnRequest, and the IdP sends an unsolicited Response directly to the SP's ACS. Harder to defend against replay than SP-initiated SSO, since there's no request to correlate against — the SP leans more heavily on Conditions validation instead.", category: "Protocols", chapters: ["saml2"] },
  { term: "XML digital signature (XML-DSig)", definition: "The signature mechanism wrapping a SAML assertion (or metadata document), letting the relying party cryptographically verify the content came from the claimed issuer and wasn't tampered with. Requires canonicalizing the XML before verifying, which is notoriously fiddlier to implement correctly than JWS (chapter 16) — a real factor in SAML's historically higher integration cost.", category: "Protocols", chapters: ["saml2"] },
  { term: "RelayState", definition: "An opaque value an SP attaches to a SAML request (or an IdP echoes back with a response) to preserve application state across the redirect/POST round trip — e.g. which page the user was trying to reach — so the SP can send them to the right place after login completes.", category: "Protocols", chapters: ["saml2"] },
  { term: "XML signature wrapping attack", definition: "A class of attack against careless SAML implementations where an attacker restructures a signed assertion's XML (e.g. duplicating or relocating elements) so that the part the application reads differs from the part the signature actually covers, causing a tampered assertion to pass signature validation. A key reason mature, well-audited SAML libraries — not hand-rolled XML parsing — are the only safe way to consume SAML in production.", category: "Protocols", chapters: ["saml2"] },
  { term: "AuthnContextClassRef", definition: "The field inside a SAML assertion's AuthnStatement declaring which authentication method or context class was used (e.g. password-protected transport vs. a stronger multi-factor context) — the SAML analog of OIDC's acr claim.", category: "Protocols", chapters: ["saml2"] },

  { term: "Mix-up attack", definition: "An attack against a client configured to trust more than one authorization server, where the attacker gets the client confused about which authorization server actually issued a given authorization response — potentially causing the client to send a real authorization code or credential to the wrong (attacker-controlled) server. RFC 9700 treats defending against it as required, not optional, for any client with more than one trusted AS.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "iss validation", definition: "The mix-up-attack defense where an authorization server includes an iss parameter (RFC 9207) stating its own issuer identity in every authorization response, and the client compares that value against the issuer it expected before proceeding — aborting the flow on any mismatch. RFC 9700's preferred defense against mix-up attacks.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "State parameter (CSRF defense)", definition: "A random, unguessable value a client generates before redirecting to an authorization server, binds to the specific browser session initiating the request, and requires the callback to echo back unchanged — defeating a forged callback from a different flow (e.g. one an attacker started) because that callback would carry a different, unbound state value. The security property comes from the session binding, not merely from the value surviving the round trip. Used mechanically throughout chapter 13's lab; this is the security rationale and failure modes.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security", "oauth2-core", "securing-a-frontend-spa"] },
  { term: "PKCE-everywhere", definition: "The current RFC 9700 guidance (§2.1.1) that PKCE should be used by confidential clients too, not only public clients — because PKCE protects the authorization code in flight, a layer a client secret never covers (the secret only matters at the later token-endpoint exchange). Distinct from chapter 13's PKCE mechanics (the code_verifier/code_challenge handshake itself) — this is the policy point about which clients should use it.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Token storage", definition: "The design decision of where a browser-based OAuth/OIDC client keeps the tokens it's issued — JavaScript-accessible storage (localStorage/sessionStorage), an httpOnly cookie, or (per RFC 10017) a server-side component that never exposes the token to the browser at all. Each option trades one exposure category (XSS readability vs. CSRF) for another; none is risk-free.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security", "securing-a-frontend-spa", "security-hardening-and-upgrades"] },
  { term: "httpOnly cookie", definition: "A cookie attribute that makes the cookie's value invisible to JavaScript (document.cookie never returns it) — only the browser attaches it to outgoing requests and only the server reads it. Closes the XSS-reads-the-token exposure that localStorage/sessionStorage have, but doesn't remove CSRF exposure, since the browser still attaches the cookie automatically to requests.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Authorization code interception attack", definition: "An attack where an authorization code is captured in transit — via a leaked referrer header, a malicious app sharing a native client's custom redirect URI scheme, or a misconfigured proxy/log — before it reaches the token endpoint. PKCE defeats it regardless of whether the client is public or confidential, since the attacker lacks the original code_verifier needed to redeem the stolen code.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "OAuth 2.0 Security Best Current Practice (RFC 9700 / BCP 240)", definition: "A published, final IETF Best Current Practice (January 2025) consolidating OAuth 2.0 threat-model advice previously spread across RFC 6749, RFC 6750, and the now-superseded RFC 6819 — the normative source for this chapter's PKCE-everywhere, mix-up, and CSRF guidance.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Backend-for-Frontend (BFF) pattern", definition: "A server-side component, specific to a browser-based application's own backend, that holds OAuth/OIDC tokens itself and gives the browser only an httpOnly, Secure, SameSite session cookie — so tokens never reach browser-readable storage or browser-visible JavaScript at all. RFC 10017 calls this pattern \"strongly recommended for business applications\" because it removes the token-in-the-browser exposure as a category rather than merely hardening where the token sits.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Token-mediating backend", definition: "A lighter-weight variant of the BFF pattern (RFC 10017) where a backend component still exchanges codes for tokens and sets a cookie, but the browser-based application may still receive and use some tokens directly — less isolating than a full BFF, which RFC 10017 recommends evaluating as the stronger alternative where feasible.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "SameSite cookie attribute", definition: "A cookie attribute controlling whether the browser attaches the cookie to cross-site requests. Used alongside httpOnly to reduce (not eliminate) the CSRF exposure that a cookie-based session or BFF pattern reintroduces once a token is moved out of JavaScript-readable storage.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "CSRF token", definition: "A random, single-use value generated by a client and checked on return to confirm a request genuinely originated from the session that's claimed — the generic security pattern that the OAuth state parameter is one specific application of.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Sender-constrained token", definition: "A token bound to proof that the presenter is the same party it was issued to (e.g. via a key the client holds), rather than a plain bearer token usable by whoever has it. RFC 9700 names sender-constraining as a further hardening step beyond storage/lifetime controls; full mechanics are a forward pointer to Keycloak's client/token configuration (chapters 24-25), not built out in this concept chapter.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Issuer identification (RFC 9207)", definition: "The IETF Proposed Standard (March 2022) defining the iss authorization-response parameter an authorization server uses to state its own identity, giving a client certainty about which server a response actually came from — the mechanism iss validation relies on, and RFC 9700's preferred mix-up-attack defense.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Browser-based application (OAuth security context)", definition: "An OAuth/OIDC client running as JavaScript inside a user's browser (an SPA or similar) — the specific client category RFC 10017 (\"OAuth 2.0 for Browser-Based Applications\") targets, because it's the category most exposed to XSS-driven token theft and the one with the most storage-location trade-offs to choose between.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security", "securing-a-frontend-spa"] },
  { term: "Cross-Site Request Forgery (CSRF) via authorization callback", definition: "A CSRF attack specifically against the OAuth/OIDC redirect handshake: an attacker starts their own legitimate authorization flow and tricks a victim's browser into completing that callback instead of one the victim initiated, potentially linking the victim's session to the attacker's identity. The state parameter is the standard defense.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },

  { term: "Quarkus distribution", definition: "The Java framework Keycloak's server is built on, chosen for fast startup and a small memory footprint in containerized environments — the opposite design goal from the older general-purpose Java EE application servers Keycloak originally shipped on. Became Keycloak's fully-supported default starting with Keycloak 17 (December 2021), replacing an earlier WildFly-based distribution that was phased out over the following releases (sources differ slightly on the exact final-removal version).", category: "Keycloak Architecture", chapters: ["keycloak-architecture", "performance-tuning"] },
  { term: "Build-time configuration (Keycloak)", definition: "Keycloak settings baked into the server image when running kc build — e.g. which database vendor, whether clustering is enabled, which features are turned on. Changing one requires re-running kc build to re-optimize the server; this is the deliberate, slower half of Keycloak's configuration split, contrasted with runtime configuration.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Runtime configuration (Keycloak)", definition: "Keycloak settings read fresh every time the server starts, via kc start/kc start-dev, environment variables, or conf/keycloak.conf — e.g. the database connection URL/credentials, hostname, HTTP(S) port, log level. Changing one only needs a restart, not a rebuild, unlike build-time configuration.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "kc build / kc start", definition: "The two-stage Quarkus-distribution workflow: kc build produces an optimized server image from build-time configuration choices, and kc start (or kc start-dev for development) launches that image with runtime configuration supplied fresh at startup.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Database backend (Keycloak)", definition: "The relational database Keycloak persists realms, users, credentials, clients, and (depending on deployment mode) sessions to — it is not a database-free product. Live-verified tested versions as of 2026-11-11 (26.8.2): PostgreSQL 18 (supporting 14.x-18.x), MariaDB 11.8, MySQL 8.4, Microsoft SQL Server 2022 (plus Azure SQL variants), and Oracle Database 23.5, plus EnterpriseDB Advanced and Amazon Aurora PostgreSQL; dev-file/dev-mem exist but are development-only and explicitly deprecated as a production default.", category: "Keycloak Architecture", chapters: ["keycloak-architecture", "performance-tuning"] },
  { term: "Standalone deployment", definition: "Running Keycloak as a single kc process directly on a VM or bare host, talking to a nearby database with no container or orchestration layer involved — the simplest point on Keycloak's deployment spectrum, suited to small internal tools or quick evaluation.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Containerized deployment", definition: "Running Keycloak and its database each as a container, typically wired together with Docker Compose — the middle point on Keycloak's deployment spectrum, and the shape this course's own lab environment uses starting chapter 20 (Keycloak 26.8.2 + PostgreSQL 17).", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Kubernetes deployment (Keycloak)", definition: "Running Keycloak as one or more pods managed by the Keycloak Operator or a Helm chart, letting Kubernetes handle scheduling, restarts, and elastic scaling of nodes — the far end of Keycloak's deployment spectrum, suited to organizations needing elastic scale and already operating Kubernetes. Full depth in chapter 42.", category: "Keycloak Architecture", chapters: ["keycloak-architecture", "keycloak-on-kubernetes"] },
  { term: "Infinispan", definition: "The distributed, in-memory data grid Keycloak embeds as its caching layer for clustering, configured by default via conf/cache-ispn.xml. Multiple Keycloak nodes share session and authentication-session state through Infinispan so a request can land on any node in the cluster and still see consistent data. Still Keycloak's current clustering technology as of 26.x. Chapter 41 configures and proves this for real: a two-node cluster, confirmed live from the server's own --help-all output to split its embedded caches into two genuinely different behaviors — session-family caches (sessions, clientSessions, offlineSessions, offlineClientSessions) are distributed/replicated across nodes, while realms/users/keys/authorization/crl are local caches kept fresh by cross-node invalidation rather than full replication, falling back to the always-authoritative database.", category: "Keycloak Architecture", chapters: ["keycloak-architecture", "high-availability-clustering", "performance-tuning"] },
  { term: "Clustering (Keycloak)", definition: "Running multiple Keycloak nodes that share session and authentication-session state (via embedded Infinispan) behind a load balancer, so throughput scales beyond one node and no single node is a point of failure within one site. Distinct from multi-site high availability, which addresses resilience across data centers/regions rather than throughput/failover within one. Chapter 41 built and proved this live: two real Keycloak 26.8.2 containers, clustered via JGroups JDBC_PING discovery (confirmed as this version's documented non-Kubernetes default), with a session created on one node provably recognized by the other via a cross-node refresh-token grant and a cross-node Admin REST session list/revoke — genuine cross-node session-cache replication, demonstrated end to end rather than merely configured.", category: "Keycloak Architecture", chapters: ["keycloak-architecture", "high-availability-clustering"] },
  { term: "High availability (Keycloak context)", definition: "Keycloak's resilience strategy against node or site failure, ranging from single-cluster deployments (embedded Infinispan, no external dependency) to multi-site architectures spanning multiple data centers/regions. Chapter 41 covers the single-cluster half concretely and hands-on, with an explicit, honest scope limit: its own two-node lab runs both nodes as containers on one Docker host, which proves cross-node cache-replication logic but not real multi-host failover or network-partition behavior — that would require genuinely separate hosts (or a real multi-node Kubernetes deployment, chapter 42) to demonstrate honestly. Multi-site/multi-region HA is chapter 44's subject.", category: "Keycloak Architecture", chapters: ["keycloak-architecture", "high-availability-clustering"] },
  { term: "Multi-site (multi-cluster) deployment", definition: "A Keycloak high-availability architecture spanning more than one data center or region, distinct from single-site clustering. Keycloak's own documentation describes more than one approach: an older one (multi-cluster v1, now deprecated and scheduled for removal) requiring a separate external Infinispan cluster per site, and a newer, current one (multi-cluster v2) that relies on the shared database to carry session state across sites instead — each trading a different kind of operational cost. This term's own \"full depth in chapter 41\" promise covers single-site clustering only; the multi-site half is chapter 44's subject.", category: "Keycloak Architecture", chapters: ["keycloak-architecture", "backup-and-disaster-recovery"] },
  { term: "Load balancer (Keycloak context)", definition: "The component that distributes incoming requests across multiple Keycloak nodes in a cluster or multi-site deployment. Required for any multi-node Keycloak architecture; often included automatically by a Kubernetes platform but a separate, explicit dependency in standalone or Docker Compose clustering setups.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Realm (Keycloak)", definition: "A fully isolated management namespace within one Keycloak server — its own users, credentials, clients, roles, groups, identity providers, and authentication flows, invisible to and unreachable from every other realm on the same server. Concretely implements chapter 13's OAuth 2.0 Authorization Server role. Keycloak ships with a built-in master realm reserved for administering Keycloak itself; this course creates a separate northwind-apps realm starting chapter 20 rather than mixing application use into master.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },

  { term: "Bootstrap admin", definition: "The administrator account Keycloak creates automatically the very first time it starts, from KC_BOOTSTRAP_ADMIN_USERNAME/KC_BOOTSTRAP_ADMIN_PASSWORD (or an auto-generated temp-admin/password if omitted). It exists solely to get an administrator logged in before any other admin account exists, and is created only once — only when the master realm doesn't yet exist. See Temporary admin user for what 'temporary' means here.", category: "Keycloak Core", chapters: ["keycloak-architecture", "installing-keycloak"] },
  { term: "Temporary admin user", definition: "The label Keycloak itself applies to a bootstrap admin account: fully functional (it can log into the Admin Console, the Admin REST API, or kcadm.sh with full privileges) but meant to be removed manually once a real, named administrator account exists. 'Temporary' describes how long it should be kept, not a technical restriction on what it can do.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "start-dev mode", definition: "Keycloak's development startup command. Relative to production mode it disables strict hostname checking, enables plain HTTP without requiring TLS, uses local-only (non-distributed) caching, disables theme/template caching, and starts with no further configuration at all — convenient for a local lab, unsafe for anything reachable outside one developer's own machine. This course's lab stack runs it via docker-compose's command: start-dev.", category: "Keycloak Core", chapters: ["keycloak-architecture", "installing-keycloak"] },
  { term: "Production mode (Keycloak)", definition: "Keycloak's start command (as opposed to start-dev): requires explicit hostname configuration, disables plain HTTP and expects HTTPS/TLS to be configured, supports distributed/clustered caching, and refuses to start at all without that configuration present — Keycloak's own docs call this 'secure by default'. Full production checklist in chapter 45.", category: "Keycloak Core", chapters: ["keycloak-architecture", "installing-keycloak", "security-hardening-and-upgrades"] },
  { term: "kcadm.sh", definition: "Keycloak's bundled command-line client for the Admin REST API, shipped at /opt/keycloak/bin/kcadm.sh in the official image. Used throughout chapters 20-26 as the scriptable, verifiable way to confirm an Admin Console step actually worked; full depth (scripting, batch operations, automation patterns) is chapter 27's subject.", category: "Keycloak Core", chapters: ["installing-keycloak", "admin-api-and-cli"] },
  { term: "Realm creation (kcadm.sh / Admin Console)", definition: "The practical act of creating a new Keycloak realm, either via the Admin Console's 'Create realm' button plus a name field, or scriptably via kcadm.sh create realms -s realm=<name> -s enabled=true against the Admin REST API. The two are mechanically equivalent — the Console is a thin UI layer over the same API kcadm.sh calls directly. A newly created realm has a key pair and self-signed certificate generated automatically.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Health endpoint (Keycloak)", definition: "Keycloak's built-in liveness/readiness checks, enabled via KC_HEALTH_ENABLED=true and served on the management port (9000 by default) rather than the main HTTP port. /health/started covers initial startup, /health/live whether the instance should be restarted, /health/ready whether it can serve traffic, and /health aggregates all three — each returns 200 (healthy) or 503 with a JSON status body. The Keycloak container image itself lacks curl/wget, a documented fact this course's own lab run independently reproduced.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Management interface (Keycloak)", definition: "A separate port (9000 by default, set via KC_HEALTH_ENABLED and related options) Keycloak serves operational endpoints like health checks and metrics on, distinct from the main port (8080/8443) that serves the Admin Console, Admin REST API, and realm/user-facing endpoints — intended to be reachable only internally, not exposed the way the main port is. Chapter 28 exercises /health and /metrics on this interface hands-on, including confirming they 404 on the main port.", category: "Keycloak Core", chapters: ["installing-keycloak", "events-and-auditing"] },
  { term: "Secure by default (Keycloak)", definition: "Keycloak's own stated design principle that its production start command deliberately refuses to run without explicit configuration (hostname, TLS, etc.) rather than silently falling back to insecure defaults — the opposite philosophy from start-dev, which is designed to run with zero configuration specifically for local development convenience.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "bootstrap-admin command", definition: "A separate kc.sh/kc.bat subcommand (bootstrap-admin user or bootstrap-admin service) for recovering admin access after the fact — distinct from the KC_BOOTSTRAP_ADMIN_* environment variables used only on first start. Can be run even before Keycloak's first-ever start, but requires every node in a cluster to be stopped first, and running it causes any pending first-start bootstrap environment variables to be ignored.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Strict hostname resolution", definition: "Keycloak's production-mode requirement that the hostname used to build links (password reset emails, redirect validation, issuer URLs) is explicitly configured rather than inferred from an incoming request's Host header. start-dev disables this, which is one of the specific reasons it's unsafe outside a local lab — an attacker-controlled Host header can otherwise influence URLs Keycloak generates.", category: "Keycloak Core", chapters: ["installing-keycloak", "security-hardening-and-upgrades"] },
  { term: "Current realm (Admin Console)", definition: "The realm selector shown in the top-left of Keycloak's Admin Console, naming which realm the console is currently managing (master by default on a fresh instance) and letting an administrator switch to or create another realm from its dropdown, per Keycloak's official Server Administration Guide.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "docker-compose.yml (Keycloak lab stack)", definition: "This course's own two-service Docker Compose file (labs/docker/docker-compose.yml) defining a Keycloak 26.8.2 container and a PostgreSQL 17 container, with Keycloak's startup gated on Postgres's healthcheck via depends_on: condition: service_healthy. Reused, fresh (docker compose up then down -v), by every Part IV chapter's hands-on lab.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "KC-SERVICES0077", definition: "The Keycloak log-message code printed exactly once, on an instance's first-ever start, reading 'Created temporary admin user with username <name>' — the concrete, grep-able evidence that the bootstrap admin creation path actually ran.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Quarkus distribution (boot timing)", definition: "Keycloak 26's Quarkus-based runtime reports its own internal startup time in its boot log (e.g. 'started in 19.441s') separately from how long a container takes to become reachable from outside — the latter also includes container-runtime overhead and the TCP listener coming up, which is why polling a real endpoint rather than sleeping a fixed duration is the correct way to detect readiness.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Master realm application-boundary rule", definition: "The operational rule that the master realm (created automatically on first start, used only to create/manage other realms and hold Keycloak's own administrative accounts) must never host an organization's actual application users, roles, or OAuth/OIDC clients — doing so places ordinary application-level risk one hop away from instance-wide administrative control. This course's own realm plan (chapters 20-26) deliberately creates and uses northwind-apps instead.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Readiness polling (vs. fixed sleep)", definition: "Confirming a service is actually ready by repeatedly checking a real endpoint until it answers successfully, instead of sleeping a fixed, guessed duration and assuming readiness. This chapter's lab needed 10 polling attempts (about 30 seconds) before Keycloak's discovery endpoint returned 200, demonstrating why a fixed-sleep assumption is fragile.", category: "DevOps / Lab practice", chapters: ["installing-keycloak"] },
  { term: "northwind-apps realm", definition: "The Keycloak realm created in chapter 20 (kcadm.sh create realms -s realm=northwind-apps -s enabled=true) as the shared running example for chapters 20-26: realm settings and branding (ch21), users jane.doe and priya.patel (ch22), roles/groups including the Mover-event payoff from chapter 10 (ch23), clients and protocol mappers (ch24), custom auth flows (ch25), and theming (ch26).", category: "Keycloak Core", chapters: ["installing-keycloak"] },

  { term: "Realm Settings (General tab)", definition: "The first Realm Settings tab in Keycloak's Admin Console, carrying a realm's Display Name (a human-readable label shown on login/branding surfaces instead of the internal realm id), Frontend URL (the base URL Keycloak uses to generate links back to itself, useful behind a reverse proxy), and Require SSL (External requests / None / All requests — External requests, the default, requires SSL except from private/loopback addresses).", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Require SSL (realm setting)", definition: "A General-tab realm setting with three modes, per Keycloak's official documentation: External requests (SSL required except from private IP addresses like localhost, the default), None (no SSL required — development only), and All requests (SSL required everywhere, no exceptions).", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Login tab (Realm Settings)", definition: "The Realm Settings tab controlling login-page self-service behavior: User registration, Forgot password, Remember Me, Verify email, Login with email, and Duplicate emails allowed — each a toggle on what the login screen offers, not on authentication mechanics themselves.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Forgot password (realm setting)", definition: "A Login-tab toggle that adds a \"Forgot Password?\" link to the login page. Requires realm or server SMTP settings (host and From address) to be configured, or reset emails never send. By default, federated users must log in again after a reset while internal database users on the same browser session stay logged in.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Remember Me (realm setting)", definition: "A Login-tab toggle that adds a checkbox keeping a user's session alive after the browser closes. Disabling it does not immediately invalidate sessions already created with the checkbox selected — invalidation happens lazily, the next time that session's cookie/token is used or during a background process.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "SSO Session Idle", definition: "A realm-level Tokens/Sessions setting: if a user is inactive longer than this timeout, their SSO session is invalidated. The concrete Keycloak field implementing chapter 7's generic SSO-session concept's inactivity half. Northwind Apps set this to 3,600 seconds (1 hour) in chapter 21, up from Keycloak's 1,800-second default, to tolerate meeting-length interruptions.", category: "Keycloak Core", chapters: ["realms", "sessions-deep-dive"] },
  { term: "SSO Session Max", definition: "A realm-level Tokens/Sessions setting: the absolute maximum time before a user's SSO session expires, regardless of continued activity. Independent of SSO Session Idle — a session that keeps getting used can still be forced to end once this ceiling is reached. Northwind Apps tightened this to 28,800 seconds (8 hours, one working day) in chapter 21, down from the 36,000-second default, specifically because it had just lengthened its idle timeout.", category: "Keycloak Core", chapters: ["realms", "sessions-deep-dive"] },
  { term: "SSO Session Idle/Max Remember Me", definition: "A separate pair of idle/max timeout values that apply only to sessions created with the Remember Me checkbox selected at login, distinct from the realm's regular SSO Session Idle/Max fields — enabling Remember Me does not by itself change how long a non-Remember-Me session lasts.", category: "Keycloak Core", chapters: ["realms", "sessions-deep-dive"] },
  { term: "Client Session Idle/Max", definition: "Realm-level timeouts scoped to a specific client's own session rather than the overall SSO session: Client Session Idle is that client session's inactivity timeout, and Client Session Max is the maximum time for the client session before its refresh token expires and invalidates. Confirmed live on a fresh realm: both fields default to 0, which per Keycloak's own Server Administration Guide means 'uses the same idle timeout [or max lifespan] in the SSO Session Idle [Max] configuration' — i.e. 0 means inherit the parent SSO session's value, not 'no limit.' The guide also states the session hierarchy directly: 'the SSO user session is the parent of zero or more client sessions, one client session is created for every different client app the user logs in' — confirmed live with one SSO session whose clients map held two distinct client UUIDs.", category: "Keycloak Core", chapters: ["realms", "sessions-deep-dive"] },
  { term: "Offline Session Idle / Offline Session Max Limited", definition: "Realm settings governing offline tokens (issued with the offline_access scope for long-lived, refresh-without-re-login access): Offline Session Idle is how long an offline session may sit idle before its token is revoked; Offline Session Max Limited is a flag controlling whether a separate absolute ceiling applies at all, or whether the offline session only ever expires via idle timeout.", category: "Keycloak Core", chapters: ["realms", "sessions-deep-dive"] },
  { term: "Access Token Lifespan", definition: "A realm-level Tokens setting controlling how long an OIDC access token Keycloak issues remains valid. Independent of SSO Session Idle/Max — a single SSO session commonly outlives many access-token mint-expire-refresh cycles. Northwind Apps raised this to 600 seconds (10 minutes) in chapter 21, up from Keycloak's 300-second default, to halve refresh round-trips while keeping a stolen token's useful window short. Concretely implements chapter 8's token-lifetime trade-off.", category: "Keycloak Core", chapters: ["realms", "sessions-deep-dive"] },
  { term: "Access Token Lifespan For Implicit Flow", definition: "A separate, dedicated token-lifetime setting for access tokens issued via the OAuth 2.0 Implicit Flow, which issues no refresh token and so cannot rely on the regular refresh-driven access-token lifecycle.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Revoke Refresh Token", definition: "A realm-level Tokens setting: when enabled, Keycloak revokes a presented refresh token and issues a new one the client must switch to, rather than letting the same refresh token be reused indefinitely across its lifespan — a defense against a leaked refresh token being replayed after the legitimate client has already rotated past it. Observed live against Keycloak 26.8.2: with this enabled, reusing an already-exchanged refresh token returns invalid_grant / 'Maximum allowed refresh token reuse exceeded' — but the underlying SSO session itself remains alive (confirmed via a separate GET users/{id}/sessions call) when only a stale refresh token, not the session, is rejected. This is the concrete difference between refresh-token-level revocation and session-level revocation chapter 29 demonstrates.", category: "Keycloak Core", chapters: ["realms", "sessions-deep-dive"] },
  { term: "Security Defenses tab (Realm Settings)", definition: "The Realm Settings tab hosting security headers (e.g. X-Frame-Options, Content-Security-Policy) and brute-force detection configuration. Previewed in chapter 21 without being configured; full depth, including the specific lockout fields, is chapter 30's subject. Chapter 30 configures and tests the real fields behind this tab: bruteForceProtected, failureFactor (Max Login Failures), waitIncrementSeconds (Wait Increment), maxFailureWaitSeconds (Max Wait), minimumQuickLoginWaitSeconds, quickLoginCheckMilliSeconds, maxDeltaTimeSeconds (Failure Reset Time), permanentLockout, bruteForceStrategy, and maxTemporaryLockouts — plus the realm's passwordPolicy string, confirmed live to be joined with the word \"and\", not a semicolon. Chapter 45's hardening checklist cites this tab's security headers as its clickjacking-mitigation checklist row.", category: "Keycloak Core", chapters: ["realms", "password-policies-and-mfa", "security-hardening-and-upgrades"] },
  { term: "Themes tab (Realm Settings)", definition: "The Realm Settings tab selecting which theme renders each of four surfaces — Login (username/password entry, OTP entry, registration, and similar login-adjacent screens), Account (the console end users manage their own account through), Admin console, and Email — plus a related Localization tab for enabling internationalization and choosing supported languages. Previewed in chapter 21 at Keycloak's built-in defaults; full branding/localization depth is chapter 26's subject.", category: "Keycloak Core", chapters: ["realms"] },

  { term: "User representation (Keycloak)", definition: "The JSON object the Admin REST API (and kcadm.sh, which wraps it) uses to read and write a user — fields like username, email, firstName, lastName, enabled, attributes, requiredActions, and a server-generated id. Every kcadm.sh user command in this chapter is a thin CLI wrapper over GET/POST/PUT requests against this representation.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Required action", definition: "Per Keycloak's own Server Administration Guide, \"actions that a user must perform at the first login\" — running after a correct credential check but before login is allowed to complete. Some are assigned deliberately by an admin (e.g. chapter 22's CONFIGURE_TOTP on priya.patel); others Keycloak adds automatically (e.g. UPDATE_PASSWORD when a credential is set as temporary). Distinct from an authentication-flow execution/Authenticator (chapters 25, 39), which runs during the credential check itself and can refuse a correct credential outright — a required action never can. Chapter 25 configures built-in required actions; chapter 40 writes a brand-new one from scratch via the Required Action SPI.", category: "Keycloak Core", chapters: ["users-and-credentials", "authentication-flows", "securing-a-backend-api", "custom-spis", "custom-idp-and-required-actions"] },
  { term: "Configure OTP (CONFIGURE_TOTP)", definition: "A required action that forces a user to enroll a one-time-password generator (via an authenticator app) before login completes. This chapter assigned it to priya.patel at creation time; chapter 5 covers the TOTP mechanics the resulting enrollment actually uses.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Update Password (UPDATE_PASSWORD)", definition: "A required action forcing a password change before login completes. Keycloak adds it automatically whenever a password is set with set-password --temporary=true — confirmed directly in this chapter's lab, where omitting --temporary left requiredActions empty and setting it to true added UPDATE_PASSWORD without any separate command.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Verify Email (VERIFY_EMAIL)", definition: "A required action Keycloak can add automatically when realm-level email verification is enabled, blocking login completion until the user confirms control of their email address. Used in this chapter's Riverside Health patient-portal case study as a different real use of the same enforcement mechanism as CONFIGURE_TOTP.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Credentials tab (Keycloak)", definition: "The Users screen's view of an identity's credentials (chapter 2's sense) — lists password and OTP credentials for a user. Backed by the Admin REST API's dedicated /users/{id}/credentials endpoint, used in this chapter to independently confirm a password credential's existence and storage format.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Password credential (Keycloak)", definition: "A credential record of type \"password\" stored under a user's credentials, holding an Argon2 hash and its parameters (iterations, memory, parallelism) rather than the password itself — confirmed directly in this chapter against jane.doe's real credentials response.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "OTP credential (Keycloak)", definition: "A credential record of type \"otp\" created once a user completes OTP enrollment, tracked separately from the password credential and reflected in the user's totp flag. Chapter 5 covers what the underlying TOTP secret and codes actually are.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Declarative User Profile", definition: "Keycloak's realm-level schema (configurable via the users/profile Admin REST resource) for defining exactly which user attributes exist and how they validate — any attribute not declared this way is an \"unmanaged attribute,\" governed by the realm's unmanagedAttributePolicy setting. By default declares only username/email/firstName/lastName. Hit directly in both chapter 22's and chapter 24's labs: a custom attribute (department) was silently dropped on write until the policy was changed.", category: "Keycloak Core", chapters: ["users-and-credentials", "clients-and-scopes", "custom-user-storage-spi", "securing-a-backend-api"] },
  { term: "Unmanaged attribute (Keycloak)", definition: "A user attribute not declared in the realm's Declarative User Profile. By default (unmanagedAttributePolicy unset/DISABLED), writes to it are silently dropped everywhere, with no error returned — confirmed live in chapter 22's, chapter 24's, chapter 33's, chapter 39's, and chapter 40's labs, across four different SPI families. Governed by the realm-level unmanagedAttributePolicy: DISABLED (default), ENABLED (allowed everywhere), ADMIN_VIEW (admin-readable only), or ADMIN_EDIT (admin-readable and writable). Keycloak's own docs recommend declaring the attribute formally, or using ADMIN_EDIT, over leaving ENABLED set broadly.", category: "Keycloak Core", chapters: ["users-and-credentials", "clients-and-scopes", "custom-user-storage-spi", "custom-spis", "custom-idp-and-required-actions"] },
  { term: "User attribute (Keycloak)", definition: "The concrete Keycloak implementation of chapter 2's generic Attribute concept, split into built-in attributes every user has (username, email, firstName, lastName) and custom attributes an organization adds (e.g. department, team) — the latter subject to Declarative User Profile validation, unlike the former.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Enabled/Disabled toggle (Keycloak)", definition: "The user-representation field (enabled: true/false) that implements chapter 2's generic \"suspend\" lifecycle stage concretely — a single field flip, reversible, leaving the rest of the record (attributes, id, credential history) untouched, as distinct from kcadm.sh delete, which this chapter confirmed returns a real 404 on the next lookup.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Credential storage (hashing)", definition: "Keycloak never stores a password credential's plaintext value; it stores a hash (Argon2, confirmed live in this chapter) plus the hashing algorithm's parameters, inside the credentialData field of the credential record. Full depth on hashing/crypto choices belongs to chapter 16; this chapter only confirms what's actually in the record.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Account Console (Keycloak)", definition: "Keycloak's separate, per-realm self-service UI (at /realms/<realm>/account) where an end user — not an admin — manages their own profile, credentials, and sessions, forward-referenced by chapter 1 and made concrete here as the self-service counterpart to the admin-facing Users screen this chapter used.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Temporary credential (Keycloak)", definition: "A password credential set with kcadm.sh set-password --temporary=true, which Keycloak automatically pairs with an UPDATE_PASSWORD required action so the user must choose their own password at next login. Confirmed in this chapter by running both the temporary and non-temporary cases and inspecting requiredActions after each.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Internal user ID vs. identifier (Keycloak)", definition: "Keycloak assigns every user a server-generated UUID (the id field) used as the actual lookup key for every Admin REST API call, distinct from the human-facing username/email identifiers chapter 2 described. Both are identifiers in chapter 2's sense (unique, not secret) — they just serve different callers.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Default required action (Keycloak)", definition: "A required action marked \"Set as default action\" under Authentication → Required Actions (REST field defaultAction), applied automatically to every new user created via Add User or self-registration, as distinct from a required action assigned to one specific user (as chapter 22 did for priya.patel). Chapter 25's lab sets CONFIGURE_TOTP's defaultAction to true for the northwind-apps realm, confirmed via a separate GET.", category: "Keycloak Core", chapters: ["users-and-credentials", "authentication-flows"] },

  { term: "Realm role", definition: "A Keycloak role that lives in the realm's own namespace and is visible to, and checkable by, every client registered in that realm — the right tool for \"what kind of identity is this,\" true regardless of which application is in use.", category: "Keycloak Core", chapters: ["roles-and-groups", "service-to-service-auth"] },
  { term: "Client role", definition: "A Keycloak role scoped to one specific client's own namespace — per Keycloak's documentation, \"a role namespace dedicated to the client.\" The same role name can exist as a realm role and, separately, as a different client role with no collision, since each lives in its own namespace. Concretely, it's a role with clientRole: true, created under that client's own /roles resource rather than the realm's — confirmed live in chapter 24 by checking a client role never appears in the realm's own role listing.", category: "Keycloak Core", chapters: ["roles-and-groups", "clients-and-scopes", "service-to-service-auth"] },
  { term: "Role namespace", definition: "The scope boundary that keeps realm roles and client roles from colliding by name: the realm itself is one namespace, and each client gets its own separate one, so identical role names in different namespaces mean entirely different things.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Composite role (Keycloak)", definition: "A Keycloak role that is \"associated with\" other roles, so assigning it to a user also grants every role it contains, transitively. Configured via a role's Action menu (\"Add associated roles\"). Not the same mechanism as group-based inheritance — a composite role bundles roles; a group bundles role mappings for a set of users.", category: "Keycloak Core", chapters: ["roles-and-groups", "service-to-service-auth"] },
  { term: "Associated roles", definition: "The set of other roles a Keycloak composite role contains — assigning the composite role to a user implicitly grants every associated role as well, without a separate assignment for each one.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Group (Keycloak)", definition: "A named collection of users that can carry its own role mappings and attributes, which every current member inherits automatically. Keycloak's own docs: \"Users that become members of a group inherit the attributes and role mappings that group defines.\" Adding or removing a membership immediately changes the member's effective, inherited access.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Subgroup", definition: "A Keycloak group created underneath an existing parent group, which inherits the parent's role mappings in addition to any role mappings defined on the subgroup itself.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Group role mapping (inherited role)", definition: "A role mapping defined on a Keycloak group rather than on an individual user. Every current member of the group inherits it automatically; it's distinct from a role assigned directly to one user, and a user's effective realm-role set is the union of both sources.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Default realm role (default-roles-<realm>)", definition: "An automatically created composite realm role (named default-roles-<realm-name>) that every user in that realm holds, bundling baseline roles like offline_access and uma_authorization. It shows up in every user's role-mapping listing and is not something a role change (Mover event) needs to add or remove.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Role mapping (Keycloak)", definition: "The association between a user (or a group) and a role it holds — the record Keycloak actually checks at an authorization decision. A user's full, effective role mapping is the union of roles assigned directly plus roles inherited from every group the user currently belongs to.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "kcadm.sh role assignment (add-roles / remove-roles)", definition: "The kcadm.sh subcommands that directly grant (add-roles) or revoke (remove-roles) a realm or client role on a specific user, identified by --uusername and --rolename. Both succeed silently; confirming the result requires a separate get on the user's role-mappings endpoint.", category: "Keycloak Core", chapters: ["roles-and-groups", "service-to-service-auth"] },
  { term: "kcadm.sh group membership (update / delete)", definition: "The kcadm.sh pattern for managing group membership against the Admin REST API's users/{id}/groups/{groupId} endpoint: update (a PUT) adds the user to the group, delete removes them. Both succeed silently; confirming the result requires a separate get on the user's groups endpoint.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Toxic-combination-resistant role design", definition: "A role-modeling choice that keeps a Segregation of Duties violation visible and checkable rather than hidden: defining narrow, independent roles (e.g. separate transfer-creator and transfer-approver roles) instead of one broad role that quietly bundles both abilities, so an access review can detect the dangerous combination as a simple query against role assignments rather than having to reverse-engineer a monolithic role's contents.", category: "Identity governance", chapters: ["roles-and-groups"] },
  { term: "Group-based role bundling", definition: "Using a Keycloak group's own role mappings to grant a whole team's worth of users the same role(s) in one place, instead of assigning (and later individually revoking) the same role on every member one at a time — the operational reason organizations track team membership as groups even when a role assignment alone would technically suffice.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Northwind Apps role model (tenant-admin / support-agent / platform-engineer)", definition: "The three independent, non-composite realm roles created in chapter 23 for the northwind-apps realm: tenant-admin (full administrative access within one customer tenant), support-agent (support tooling and tenant-facing queues), and platform-engineer (platform engineering tooling and infrastructure) — kept deliberately non-overlapping so a role change between them removes access cleanly rather than leaving it nested inside a composite role.", category: "Keycloak Core", chapters: ["roles-and-groups", "case-study-northwind"] },

  { term: "Client scope (Keycloak)", definition: "A named, realm-level, reusable bundle of protocol mapper configuration and role-scope mappings that can be attached to any number of clients. The concrete Keycloak object behind OAuth's abstract Scope (chapter 13) — defining one once and attaching it to many clients means a later claim change updates every one of them at once.", category: "Keycloak core", chapters: ["clients-and-scopes", "service-to-service-auth"] },
  { term: "Default client scope", definition: "A client scope attached to a client in default mode: automatically included in every token that client requests, with no scope= parameter needed. Contrast with optional client scope.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Optional client scope", definition: "A client scope attached to a client in optional mode: only included in a token if the request's own scope= parameter names it explicitly. Contrast with default client scope.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Protocol mapper", definition: "A single Keycloak rule, attached to a client scope (or directly to a client), that decides one claim: where its value comes from (a user attribute, a hardcoded value, a role name, a group membership) and which token types/responses it's allowed into, via independent id.token.claim/access.token.claim/userinfo.token.claim flags. The concrete mechanism behind OIDC custom claims (chapter 15).", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "User attribute mapper (oidc-usermodel-attribute-mapper)", definition: "The specific Keycloak protocol mapper type that reads a named Keycloak user attribute and writes its value under a chosen claim name. Requires the source attribute to actually be persisted on the user — a declarative User Profile that hasn't declared or enabled that attribute will silently produce no claim at all, with no error anywhere in the chain.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Confidential client (Keycloak)", definition: "A Keycloak client with publicClient: false, issued an auto-generated client secret that must be presented at the token endpoint. Meant for applications that run somewhere an attacker cannot read the source — a backend/server-rendered app, not a browser SPA or a decompiled mobile binary.", category: "Keycloak core", chapters: ["clients-and-scopes", "securing-a-frontend-spa", "service-to-service-auth"] },
  { term: "Public client (Keycloak)", definition: "A Keycloak client with publicClient: true, issued no client secret at all. Relies on PKCE (chapter 13) rather than a secret to protect its authorization code exchange — the correct configuration for a browser SPA or native/mobile app, where any embedded secret would be readable by anyone.", category: "Keycloak core", chapters: ["clients-and-scopes", "securing-a-frontend-spa"] },
  { term: "Client secret (Keycloak)", definition: "An auto-generated credential issued only to confidential clients, required alongside an authorization code (or other grant parameters) at the token endpoint. Retrievable via the Admin REST API/kcadm.sh (GET .../client-secret) or the Admin Console's Credentials tab — never meant to be embedded in code an attacker could read.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Standard flow (Keycloak client setting)", definition: "The standardFlowEnabled client toggle controlling whether this client may use the authorization code grant (chapter 13) at all. A client needs at least one grant-type toggle enabled to obtain tokens through any means.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Direct access grants (Keycloak client setting)", definition: "The directAccessGrantsEnabled client toggle controlling whether this client may use the Resource Owner Password Credentials grant (chapter 13's deprecated ROPC) directly, trading a username/password for tokens with no redirect at all. Discouraged for real applications; useful only as a lab/testing technique to mint a token without a browser. Chapter 30 reuses the same lab-only technique to deliberately submit wrong credentials and observe real brute-force lockout behavior.", category: "Keycloak core", chapters: ["clients-and-scopes", "password-policies-and-mfa", "user-federation-ldap"] },
  { term: "Service accounts (Keycloak client setting)", definition: "The serviceAccountsEnabled client toggle controlling whether this client gets its own dedicated service-account user and may use the client credentials grant (chapter 13/14) for machine-to-machine access with no human resource owner involved.", category: "Keycloak core", chapters: ["clients-and-scopes", "admin-api-and-cli", "service-to-service-auth"] },
  { term: "unmanagedAttributePolicy", definition: "A realm-level User Profile setting controlling whether attributes outside the declared schema are persisted at all. Unset (the effective default), such attributes are silently dropped on write; ENABLED (or an admin-only variant) allows them to be stored and later read by protocol mappers.", category: "Keycloak core", chapters: ["clients-and-scopes", "custom-user-storage-spi"] },
  { term: "Default client scopes (client relationship)", definition: "The list of client scopes a given Keycloak client has attached in default mode, retrievable via GET clients/<id>/default-client-scopes. Includes Keycloak's own built-in scopes (profile, email, roles, web-origins, acr, basic) alongside any custom scopes an admin attaches, such as northwind-profile in chapter 24.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Web origins (Keycloak client field)", definition: "A Keycloak client field listing browser origins allowed to make CORS requests against Keycloak endpoints on this client's behalf. Separate from Valid Redirect URIs — redirect URIs control where the browser is sent after login; Web Origins controls which origins' JavaScript may call Keycloak's APIs directly.", category: "Keycloak core", chapters: ["clients-and-scopes", "securing-a-frontend-spa"] },
  { term: "Consent screen attribute (client scope)", definition: "A client scope's display.on.consent.screen attribute, controlling whether that scope's claims are listed to the user on a consent prompt before being granted. Separate from include.in.token.scope, which controls whether the scope's name itself appears in the issued token's own scope claim.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "jsonType.label (protocol mapper config)", definition: "A protocol mapper config field declaring how to type a claim's value in the issued JSON payload — String, long, boolean, or JSON — independent of how the underlying Keycloak user attribute itself is stored (always as a string or list of strings).", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "multivalued (protocol mapper config)", definition: "A protocol mapper config boolean controlling whether a claim's value is always rendered as a JSON array, even when the underlying attribute has only one value — false renders a single value as a bare scalar instead.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Introspection token claim (protocol mapper config)", definition: "A protocol mapper config flag (introspection.token.claim) controlling whether this mapper's claim also appears in RFC 7662 token introspection responses (chapter 14), independent of the id.token.claim/access.token.claim/userinfo.token.claim flags that control the token/UserInfo paths.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Client ID vs. internal id (Keycloak)", definition: "A Keycloak client has two distinct identifiers: clientId, the human-chosen, OAuth-facing name (e.g. northwind-dashboard) used in authorize/token requests, and a separate internal UUID (Keycloak's own primary key) used in every Admin REST API path (clients/<uuid>/...). Confusing the two is a common kcadm.sh/REST scripting mistake.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Exclusive redirect URI pattern", definition: "Keycloak's own recommended practice (named directly in its Server Administration Guide) of registering the narrowest possible Valid Redirect URIs pattern for a client — a full path, or at most a trailing wildcard scoped to one specific subpath — rather than a broad or bare wildcard, to minimize the blast radius chapter 13's exact-match lesson warns about.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Resource owner password credentials as a lab technique", definition: "Using the deprecated ROPC/direct-access-grants flow deliberately and temporarily, in a disposable lab environment only, to mint a real token for a real user without needing a browser — explicitly not a recommended pattern for any real application (chapter 13), reverted immediately after use in chapter 24's lab.", category: "Keycloak core", chapters: ["clients-and-scopes", "user-federation-ldap"] },

  { term: "Authentication flow (Keycloak)", definition: "A realm-scoped, ordered tree of executions that decides what proof is demanded during a protocol-level action — browser login, direct grant, registration, and so on. Every realm ships five built-in top-level flows for these purposes (plus client-authentication and Docker-registry flows), and any of them can be cloned into an independently editable custom flow.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Execution (authentication flow)", definition: "One node in a Keycloak authentication flow's tree — either a single authenticator (e.g. Username Password Form, OTP Form) or a nested subflow containing more executions. Each execution carries its own requirement level and ordering (level/index/priority in the Admin REST API).", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Requirement level (REQUIRED / ALTERNATIVE / CONDITIONAL / DISABLED)", definition: "The four values a Keycloak flow execution can take: REQUIRED must succeed; ALTERNATIVE is one of several acceptable paths at that level; CONDITIONAL (subflows only) is evaluated at all only if every REQUIRED condition execution directly inside it evaluates true first; DISABLED is never evaluated. Which levels an execution can actually take is constrained by its own requirementChoices.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Browser flow (Keycloak)", definition: "The built-in top-level flow bound to standard interactive web login (a redirect to a login page). The realm's browserFlow setting selects which top-level flow actually plays this role, defaulting to the built-in alias \"browser\".", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Direct Grant flow (Keycloak)", definition: "The built-in flow executed for API-style, non-interactive logins (e.g. the resource-owner-password-credentials shape), where credentials arrive directly in a token request rather than via a redirected login page.", category: "Keycloak Core", chapters: ["authentication-flows", "securing-a-backend-api", "custom-spis"] },
  { term: "Registration flow (Keycloak)", definition: "The built-in flow governing self-service account creation via the login page's \"Register\" link — a distinct process from logging in, with its own steps such as terms-and-conditions and profile capture.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Reset Credentials flow (Keycloak)", definition: "The built-in flow governing the forgot-password / account-recovery process, bound to the realm via resetCredentialsFlow.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "First Broker Login flow (Keycloak)", definition: "The built-in flow that runs exactly once per user, the first time they authenticate through a brokered external identity provider — before Keycloak has decided whether to link, create, or reject a local account for them. Distinct from every ordinary login flow.", category: "Keycloak Core", chapters: ["authentication-flows", "identity-brokering"] },
  { term: "Conditional subflow", definition: "A subflow whose own requirement level is CONDITIONAL. Keycloak only evaluates (and potentially requires) its children if every REQUIRED condition-type execution directly inside it evaluates true first; multiple REQUIRED conditions in the same subflow are implicitly ANDed, and if any required condition fails, the whole subflow — and everything nested in it — is skipped outright.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Condition - user configured (authenticator)", definition: "A condition execution (provider conditional-user-configured) that evaluates true only if the authenticating user already has a credential configured for at least one authenticator later in the same subflow. Keycloak's own default browser flow uses this to ask returning MFA users for their second factor without demanding brand-new users enroll one mid-login.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Condition - user role (authenticator)", definition: "A condition execution (provider conditional-user-role) that evaluates true only if the authenticating user holds a specified realm or client role, configured via a single condUserRole value (optionally negated). The mechanism this course uses to gate OTP specifically to Northwind Apps's tenant-admin role rather than to every user.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Flow duplication (Keycloak)", definition: "Copying an entire built-in flow, including its full subflow tree, into a new, independently editable top-level flow — via the Admin Console's \"Duplicate\" action or the Admin REST API's POST .../copy endpoint. Required because built-in flows themselves cannot be edited in place, only copied and then modified.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Built-in flow (Keycloak)", definition: "One of the flows Keycloak creates automatically in every new realm (browser, direct grant, registration, reset credentials, clients, first broker login, plus docker auth). Shown read-only in the Admin Console specifically so a safe, known-good default always exists to fall back to or clone from.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Flow binding (realm)", definition: "The realm-level settings (browserFlow, registrationFlow, directGrantFlow, resetCredentialsFlow, clientAuthenticationFlow, firstBrokerLoginFlow, dockerAuthenticationFlow) that select which top-level flow actually runs for each purpose. Cloning a flow has no effect on real logins until the realm is rebound to the clone's alias.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Conditional OTP (step-up pattern)", definition: "Configuring OTP's authenticator execution inside a CONDITIONAL subflow instead of as a flat REQUIRED/ALTERNATIVE step in the main flow, so the possession factor (OTP) is demanded only when a condition — role membership, prior enrollment, client scope, risk signal — says it should be. The concrete Keycloak mechanism behind step-up authentication.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Authenticator SPI", definition: "Keycloak's pluggable provider interface for writing custom authenticators and conditions in Java (e.g. a transaction-context-aware condition a bank like Meridian Trust would need for action-triggered step-up, which no built-in condition provider covers). Chapter 25 only used built-in providers (conditional-user-role, conditional-user-configured); chapter 39 is where this forward-pointer is delivered, with a real custom authenticator built and run.", category: "Keycloak Core", chapters: ["authentication-flows", "custom-spis"] },

  { term: "Theme (Keycloak)", definition: "A named bundle of templates, stylesheets, and message bundles that controls how a category of Keycloak screen looks and speaks. Themes are assigned per realm (login/account/admin/email) or per instance (welcome), and Keycloak 26.x ships its built-in ones (base, keycloak, keycloak.v2) inside a JAR rather than as a plain editable directory.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Login theme", definition: "The realm theme setting (REST field loginTheme) controlling username/password entry, OTP entry, registration, and similar login-adjacent screens — the one every lab chapter since 20 has been implicitly hitting.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Account theme", definition: "The realm theme setting (REST field accountTheme) controlling the self-service Account Console a user manages their own profile, credentials, and sessions through.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Admin console theme", definition: "The realm theme setting (REST field adminTheme) controlling the skin of the Keycloak Admin Console itself, distinct from the login or account screens an ordinary user sees.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Email theme", definition: "The realm theme setting (REST field emailTheme) controlling the templates used for every email Keycloak sends — verification, password reset, OTP codes.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Welcome theme", definition: "The instance-wide default page shown at Keycloak's root URL with no realm context. Unlike the four realm-level theme fields, it is configured via a server startup option (--spi-theme--welcome-theme=<name>), not a per-realm REST field.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Theme type", definition: "One of the categories a Keycloak theme can provide templates/resources for — login, account, admin, email, welcome, or common (shared resources imported by others). A single theme name (e.g. keycloak) may implement several types but not necessarily all of them.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "theme.properties", definition: "The configuration file inside a theme type's directory (themes/<name>/<type>/theme.properties) that declares what the theme extends (parent=), imports (import=), its stylesheets, and whether it's abstract — confirmed by reading the real files inside Keycloak 26.8.2's bundled themes jar for this chapter.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Parent theme (theme inheritance)", definition: "A theme declared via parent=<name> in theme.properties that the current theme extends, inheriting its templates and resources except where explicitly overridden. Keycloak's own keycloak and keycloak.v2 themes both declare parent=base.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Abstract theme", definition: "A theme whose theme.properties sets abstract=true, marking it as meant only to be inherited from, not selected directly — Keycloak's own base theme is abstract. The Admin Console's Themes-tab dropdown hides abstract themes from direct selection, but this is a UI-level courtesy only: the Admin REST API does not enforce it, and will accept an abstract theme name as a realm's theme setting without complaint.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "FTL template override", definition: "A Freemarker (.ftl) template file placed at the exact relative path of a parent theme's own template (e.g. login/login.ftl) inside a custom theme directory, shadowing it. Only needed when a screen's markup itself must change, not merely its styling, which is handled through CSS/resources instead.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Theme caching", definition: "Keycloak's practice of caching compiled theme templates and static resources for performance. Disabled by default under start-dev (and via explicit --spi-theme--cache-themes=false/--spi-theme--cache-templates=false options) so edits appear without a restart; left enabled in production, where disabling it significantly impacts performance per Keycloak's own UI Customization Guide.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Internationalization (i18n, Keycloak realm setting)", definition: "A realm-level feature (REST field internationalizationEnabled, default false) that, once enabled alongside supportedLocales and defaultLocale, lets Keycloak's login/account/admin/email screens render in multiple languages rather than only the theme's default locale.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "supportedLocales", definition: "The realm REST field listing which locale codes a realm offers once internationalization is enabled. Declaring a locale here does not by itself guarantee translated text exists for it — that depends on a theme actually shipping a matching messages_<locale>.properties file.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "defaultLocale (realm setting)", definition: "The realm REST field naming which locale to fall back to when no higher-priority signal (user selection, user profile, client request, cookie, browser Accept-Language header) resolves one, second-to-last in Keycloak's documented locale resolution order before English itself.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Locale resolution order", definition: "Keycloak's documented sequence for picking which language to render: user-selected on the login page, then user-profile locale, then a client-requested locale (e.g. OIDC's ui_locales parameter), then a cookie, then the browser's Accept-Language header, then the realm's defaultLocale, then English as the final fallback. A custom LocaleSelectorProvider SPI can replace this order entirely.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Message bundle (theme)", definition: "A locale-specific .properties file (messages_<locale>.properties) inside a theme's messages/ directory supplying translated text for ${msg(\"key\")} references in templates. Keycloak's base theme ships dozens of built-in locale bundles out of the box; a provider can also contribute its own theme-resources/messages/messages_en.properties that gets merged into every theme's bundle.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Theme-resources (provider-contributed)", definition: "FTL templates, stylesheets, and message bundles that a custom SPI provider (e.g. a custom authenticator) ships inside its own JAR under theme-resources/, which Keycloak merges into whichever theme a realm is actually using at render time, rather than requiring the provider to fork the theme itself.", category: "Theming & Localization", chapters: ["themes-and-branding", "custom-idp-and-required-actions"] },

  { term: "Admin REST API", definition: "Keycloak's administrative HTTP API, with every endpoint hanging off the base pattern {server}/admin/realms/{realm}/{resource}. Every call requires a bearer access token (no cookie/session the way a browser login uses one); the Admin Console, kcadm.sh, and any custom script are three equally valid clients of this exact same API — confirmed in chapter 27 by reproducing a kcadm.sh action with a raw curl call against the identical endpoint.", category: "Keycloak Operations", chapters: ["admin-api-and-cli", "service-to-service-auth"] },
  { term: "admin-cli (client)", definition: "Keycloak's built-in, public (no-secret) OAuth client used for interactive Admin REST API scripting via the Resource Owner Password Credentials grant with a real administrator's own username/password — the client kcadm.sh authenticates as by default. Contrast with a dedicated service-account client used for unattended automation.", category: "Keycloak Operations", chapters: ["admin-api-and-cli", "service-to-service-auth"] },
  { term: "kcadm.config", definition: "The local file kcadm.sh writes after a successful config credentials call, caching the obtained access and refresh tokens so later commands in the same shell reuse that session instead of re-authenticating. Confirmed live at /opt/keycloak/.keycloak/kcadm.config inside the official container image (the Linux default is $HOME/.keycloak/kcadm.config). Scripts run on shared/CI infrastructure should pass --no-config or an isolated config path to avoid leaking a cached session into an unrelated later job.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "kcadm.sh generic resource verbs", definition: "kcadm.sh's get/create/update/delete subcommands, which map directly onto HTTP GET/POST/PUT/DELETE against the same Admin REST API paths a raw curl call would use. -r sets the target realm, -s key=value sets a request-body field, -q key=value adds a query-string parameter, and --fields filters which response keys print. Some endpoints return a body with no Location header, in which case create exits 0 with no printed output at all unless -o is passed to force the real response body to print — confirmed directly in chapter 27 on the partial-export endpoint.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "kcadm.sh config credentials", definition: "The kcadm.sh subcommand that performs an OAuth token request against a given server/realm with a given username and password, then caches the result in kcadm.config for reuse by later commands in the same session.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "kcadm.sh scripting output (--format csv --noquotes)", definition: "A kcadm.sh get flag combination that renders a JSON array response as plain, unquoted values instead of formatted JSON — used to extract an internal resource id (a group id, a user id) directly into a shell variable for a follow-up call, since most Admin REST API resources are addressed by an internal UUID the caller usually has to look up first, not by a human-chosen name.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "Pagination (Admin REST API)", definition: "Keycloak's collection endpoints (e.g. the users list) page via first/max query parameters rather than a response header — confirmed live that a paginated response carries no total-count header of any kind. Getting a true total requires a separate call to that resource's own /count endpoint.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "Count endpoint (Admin REST API)", definition: "A dedicated sub-resource (e.g. GET /admin/realms/{realm}/users/count) that returns a collection's true total as a plain number, since ordinary paginated list calls carry no total-count header to read instead.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "Partial export (realm)", definition: "The Admin REST API's POST /admin/realms/{realm}/partial-export operation (also reachable via the Admin Console's own export screen), returning realm settings plus, optionally, clients/groups/roles — but never user accounts, confirmed live: the response carries no users key at all. Server stays running; this is an ordinary authenticated REST call, not a special launch mode.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "Full export (realm)", definition: "Keycloak's server-CLI export command (kc.sh export --dir <dir> --realm <realm>), a separate one-shot \"nonserver\" launch mode distinct from any REST call. Unlike partial export, it genuinely includes user accounts, each with its real (Argon2-hashed-and-salted, not plaintext) credential data — confirmed live by reading an exported user's credential block directly. Per Keycloak's own docs, only this mechanism, not the Admin Console's partial export, is suitable for backup or server-to-server transfer. Requires the Keycloak server process to not be running at the time.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "partialImport (Admin REST API)", definition: "POST /admin/realms/{realm}/partialImport, which merges a submitted JSON payload (which can include users) into a live, running realm, with conflicts resolved per an explicit ifResourceExists policy. Confirmed live by adding one new user to a realm that already had others.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "ifResourceExists policy", definition: "The partialImport request field controlling what happens when an incoming resource's name or id already exists in the target realm: SKIP (leave the existing resource untouched), OVERWRITE (replace it), or FAIL (abort the import). Confirmed live with SKIP against a realm with pre-existing users.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },
  { term: "Admin-scoped access token", definition: "An access token whose aud (audience) claim targets the Admin REST API itself (e.g. .../admin/realms/master) rather than some other application's own resource server, and whose scope includes kc-admin-api — confirmed by base64url-decoding a real token obtained via the admin-cli client's password grant. The concrete mechanism behind \"this token can administer Keycloak,\" distinct from an ordinary OIDC client's access token.", category: "Keycloak Operations", chapters: ["admin-api-and-cli", "service-to-service-auth"] },
  { term: "Infrastructure as Code (IAM/Keycloak context)", definition: "Managing Keycloak's realm/client/role configuration as versioned, scripted definitions (Terraform, Ansible, a CI pipeline calling kcadm.sh or the Admin REST API directly) rather than one-off manual Admin Console clicks — the same discipline chapter 26's theme-name pitfall warned matters, since the REST API validates none of what it's given and a typo in an IaC script will \"succeed\" silently.", category: "Keycloak Operations", chapters: ["admin-api-and-cli"] },

  { term: "Login event (Keycloak)", definition: "A recorded login/user event — an EventRepresentation — triggered by an authentication-adjacent action such as a password check, a token exchange, or a logout. Gated by the realm's eventsEnabled flag, independent of admin events.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "Admin event (Keycloak)", definition: "A recorded administrative action — an AdminEventRepresentation — triggered by any Admin Console or Admin REST API call that creates, updates, or deletes a resource. Gated by the realm's adminEventsEnabled flag, independent of login/user events. Disabled by default (adminEventsEnabled: false on a fresh realm); chapter 27 deliberately reproduced the resulting governance gap live — a bulk-onboarding script's accounts left zero admin-event trail until logging was turned on, and turning it on afterward does not retroactively record what already happened.", category: "Keycloak Operations", chapters: ["events-and-auditing", "admin-api-and-cli"] },
  { term: "RealmEventsConfigRepresentation", definition: "The REST representation of a realm's event configuration: eventsEnabled, eventsExpiration, eventsListeners, enabledEventTypes, adminEventsEnabled, and adminEventsDetailsEnabled — six independent fields, not one master switch. Read/written via GET/PUT /admin/realms/{realm}/events/config.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "EventRepresentation", definition: "The JSON shape of one recorded login/user event: id, time, type (e.g. LOGIN, LOGIN_ERROR), realmId, clientId, userId, sessionId, ipAddress, error, and a details map. Returned by GET /admin/realms/{realm}/events.", category: "Keycloak Operations", chapters: ["events-and-auditing", "custom-spis"] },
  { term: "AdminEventRepresentation", definition: "The JSON shape of one recorded admin event: id, time, realmId, authDetails (who made the change, from where, through which client), operationType (CREATE/UPDATE/DELETE), resourceType, resourcePath, an optional representation (the full JSON body, only populated when adminEventsDetailsEnabled is true), error, and a details map. Returned by GET /admin/realms/{realm}/admin-events.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "eventsEnabled", definition: "The RealmEventsConfigRepresentation boolean controlling whether login/user events are recorded at all. Defaults to false on a new realm. Independent of adminEventsEnabled.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "adminEventsEnabled", definition: "The RealmEventsConfigRepresentation boolean controlling whether admin events are recorded at all. Defaults to false on a new realm. Independent of eventsEnabled.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "adminEventsDetailsEnabled", definition: "The RealmEventsConfigRepresentation boolean controlling whether a recorded admin event also carries the full JSON representation of what was created, updated, or deleted — a third, independent switch layered on top of adminEventsEnabled alone. Captures the submitted body verbatim, with no field-level filtering.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "eventsExpiration", definition: "The RealmEventsConfigRepresentation field (seconds) controlling how long a recorded login/user event is retained before it ages out.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "eventsListeners (realm config)", definition: "The RealmEventsConfigRepresentation field listing which Event Listener SPI provider(s) receive every event as it occurs, independent of whether the event is also saved to the database. jboss-logging is the built-in default on every realm, enabled or not.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "enabledEventTypes", definition: "The RealmEventsConfigRepresentation field listing which specific login/user event type constants (e.g. LOGIN, LOGIN_ERROR) are actually saved. A fresh realm's default list already contains 102 distinct type constants, confirmed by direct inspection — not a short list requiring manual expansion.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "Event Listener SPI", definition: "The Keycloak Service Provider Interface that lets a provider receive every event as it occurs and trigger an action. Two built-in implementations ship by default: the Logging Event Listener and the Email Event Listener. A custom implementation (chapter 39) is one of the real paths to pushing events into an external SIEM.", category: "Keycloak Operations", chapters: ["events-and-auditing", "custom-spis"] },
  { term: "Logging Event Listener (jboss-logging)", definition: "Keycloak's built-in Event Listener SPI implementation that writes to the org.keycloak.events log category when an error event occurs, by default at error level only (success-level logging can be enabled via --spi-events-listener--jboss-logging--success-level). Present on every realm by default, whether or not eventsEnabled/adminEventsEnabled are on.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "Email Event Listener", definition: "Keycloak's other built-in Event Listener SPI implementation, which sends a message to the affected user's own email address when specific event types occur (e.g. Login Error, Update Password, Update/Remove TOTP, Update Credential) — distinct from the Logging Event Listener, which writes to the server log instead.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "Health check (Keycloak)", definition: "The /health, /health/ready, /health/live, and /health/started endpoints, served on the separate management interface (port 9000 by default) once KC_HEALTH_ENABLED is set. Answers whether the server itself is alive and able to process requests — a monitoring concern, distinct from the events subsystem's audit concern of who did what.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "Metrics endpoint (Keycloak)", definition: "The /metrics endpoint, served on the management interface once KC_METRICS_ENABLED is set (a separate opt-in from KC_HEALTH_ENABLED, same default-false pattern), returning real-time Prometheus-exposition-format counters and gauges (e.g. keycloak_credentials_password_hashing_validations_total, broken out by realm and outcome). Gives aggregate signal, not per-event detail — it cannot answer which user or IP address, only how many.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },
  { term: "SIEM-style export (Keycloak)", definition: "The general pattern of getting Keycloak's recorded events into an external security information and event management system. Keycloak ships no built-in SIEM connector; real integrations require one of: polling the events/admin-events REST endpoints on a schedule, shipping the org.keycloak.events log category via an external log pipeline, or writing a custom Event Listener SPI provider (chapter 39) that pushes events as they occur.", category: "Keycloak Operations", chapters: ["events-and-auditing"] },

  { term: "Session ID (sid claim)", definition: "The identifier tying a minted token back to the specific server-side SSO session that issued it: present as the sid claim inside ID/access tokens, and as the id field returned by GET users/{id}/sessions. This is the value DELETE sessions/{session} expects — not a user id, not a token value.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "GET /admin/realms/{realm}/users/{user-id}/sessions", definition: "The Admin REST API call that lists a user's active sessions. Returns 200 with an array of session objects (empty array when none exist). Confirmed live against Keycloak 26.8.2 in chapter 29's lab, matching the OpenAPI definition's own summary, \"Get sessions associated with the user.\"", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "DELETE /admin/realms/{realm}/sessions/{session}", definition: "The Admin REST API call that revokes one specific session by its own session id (not a user id or token). Confirmed live: returns 204 with no body; per the OpenAPI spec, any client with an admin URL is also told to invalidate that particular session.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "POST /admin/realms/{realm}/users/{user-id}/logout", definition: "The Admin REST API call that revokes every session belonging to one user at once (\"logout everywhere\" for that user) — confirmed live: 204, no body, and a follow-up GET users/{id}/sessions independently confirmed an empty array afterward.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "POST /admin/realms/{realm}/logout-all", definition: "The Admin REST API call that revokes every session in the entire realm at once, notifying any client with an admin URL to invalidate its sessions too. Documented from Keycloak's published OpenAPI spec; deliberately not exercised live in chapter 29's lab as too destructive for a shared lab realm.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "GET /admin/realms/{realm}/clients/{client-uuid}/user-sessions", definition: "The per-client counterpart to the per-user session listing: returns every user session associated with one specific client across the realm. Documented from Keycloak's OpenAPI spec; not exercised live in chapter 29's lab.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "KEYCLOAK_SESSION cookie", definition: "The cookie Keycloak sets on its own domain (not either relying client's) once a browser successfully authenticates. This cookie is the literal mechanism behind SSO-across-clients: a second, completely different registered client's authorization request from the same browser is checked silently against this cookie, and if a live session is found, Keycloak redirects back with a fresh authorization code with no login prompt at all. Demonstrated live in chapter 29 with a curl cookie jar reused across two independently registered clients, both ending up tied to the same session_state value.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "Refresh token rotation (reuse detection)", definition: "The behavior Keycloak's Revoke Refresh Token setting (ch. 21) actually produces: each successful refresh-token grant issues a brand-new refresh token and invalidates the one just used; presenting that already-used refresh token a second time is rejected. Observed live, verbatim: {\"error\":\"invalid_grant\",\"error_description\":\"Maximum allowed refresh token reuse exceeded\"}. Matches RFC 9700 (OAuth 2.0 Security BCP) §2.2.2 and §4.14's refresh-token-protection guidance. Distinct from session-level revocation — the underlying session was confirmed still alive while this error was returned.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "Session-level vs. refresh-token-level revocation", definition: "Two genuinely different things Keycloak can do that both get loosely called \"revocation.\" Session-level (DELETE sessions/{id} or POST users/{id}/logout) kills the session entirely — any later refresh attempt against it fails with invalid_grant / \"Session not active,\" confirmed live by an independent GET returning an empty array. Refresh-token-level (Revoke Refresh Token's rotation/reuse-detection) only rejects one stale, already-spent refresh token; the session itself survives, confirmed live via a follow-up GET still showing it active.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "RP-Initiated Logout", definition: "One of Keycloak's four documented OIDC logout mechanisms: a browser redirect to Keycloak's own logout endpoint, typically triggered by a user clicking a \"Log Out\" link in an application. Keycloak then sends logout requests to every client attached to that browser's current SSO session.", category: "Protocols", chapters: ["sessions-deep-dive"] },
  { term: "Front-Channel Logout", definition: "An OIDC logout mechanism relying on the browser rendering hidden iframes per client to deliver logout requests. Per Keycloak's own Server Administration Guide, it can be impacted by Content Security Policies and blocked, and a session may survive if the browser is closed before the logout page finishes rendering — the guide recommends Back-Channel Logout as more reliable.", category: "Protocols", chapters: ["sessions-deep-dive"] },
  { term: "Back-Channel Logout", definition: "An OIDC logout mechanism using a direct server-to-server logout request to each client's own Back-Channel Logout URL (falling back to its Admin URL if unset) — no browser involvement. Keycloak's own documentation recommends this as \"a more reliable and secure approach\" than Front-Channel Logout.", category: "Protocols", chapters: ["sessions-deep-dive"] },
  { term: "OIDC Session Management (logout mechanism)", definition: "One of Keycloak's four documented OIDC logout mechanisms: a browser-based approach where an application polls Keycloak at regular intervals for session status; when the session is terminated at Keycloak, the application notices and triggers its own logout. This is what lets logging out in one browser tab trigger automatic logout in other tabs of apps using the Keycloak JavaScript adapter.", category: "Protocols", chapters: ["sessions-deep-dive"] },
  { term: "Realm revocation policy (\"Push\")", definition: "A realm-wide, timestamp-based tool under Sessions → Actions → Revocation in the Admin Console: an administrator sets a cutoff date/time, and any session or token issued before it is treated as invalid; optionally \"Push\" propagates that policy to every registered OIDC client running Keycloak's own adapter. A blunter, realm-wide tool distinct from the per-session/per-user REST endpoints — reserved for genuine breach scenarios, not routine single-user offboarding. Documented from the live Server Administration Guide; not exercised in chapter 29's lab (too destructive for a shared lab realm).", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },
  { term: "User Session Count Limiter", definition: "An authentication-flow execution that caps the number of concurrent sessions a user can have, per realm and/or per client, with a configurable behavior when the limit is reached: \"Deny new session\" (block the new login) or \"Terminate oldest session\" (kill the oldest session to make room for the new one). Configured as a required step added to an authentication flow, per Keycloak's Server Administration Guide; not exercised live in chapter 29's lab.", category: "Keycloak Operations", chapters: ["sessions-deep-dive"] },

  { term: "Password policy (Keycloak)", definition: "The realm's passwordPolicy REST field: a single string of policy-type clauses joined with the literal word \"and\" (not a semicolon, despite how it's sometimes described) — e.g. length(12) and digits(1) and specialChars(1). Confirmed directly against a live 26.8.2 realm in this chapter's lab, correcting an initial semicolon assumption.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "notUsername vs. notContainsUsername", definition: "notUsername rejects a password only if it is exactly equal to the username; it does nothing against a password that merely contains the username as a substring with extra characters appended. notContainsUsername (and notContainsEmail) exist specifically to catch that substring case. Confirmed in this chapter's lab: a password containing the username passed notUsername(undefined) cleanly.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Password history (passwordHistory)", definition: "A password policy type rejecting a new password that matches any of the user's last N passwords. Triggered for real in this chapter's lab (invalidPasswordHistoryMessage) by resetting a password back to a value used two changes earlier under passwordHistory(3).", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Brute-force detection (Keycloak)", definition: "The realm-level mechanism (master switch: bruteForceProtected) that temporarily or permanently disables a user account after too many consecutive failed logins. Keycloak's own concrete implementation of chapter 9's generic brute-force-attack threat. Fully configured and tested — including a real triggered lockout confirmed via the Admin REST API — in this chapter.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Max Login Failures (failureFactor)", definition: "The brute-force detection field (REST name failureFactor) setting how many consecutive failed logins are tolerated before a wait is imposed. This chapter's lab used a deliberately low value (3) to trigger and confirm a real lockout quickly; a production realm would typically use a much higher number.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Wait Increment (waitIncrementSeconds)", definition: "The brute-force detection field controlling how much additional wait time is added each time the failure count crosses another multiple of Max Login Failures, under the default MULTIPLE strategy.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Max Wait (maxFailureWaitSeconds)", definition: "The brute-force detection field capping how long a single temporary lockout can last, regardless of how high the failure count climbs.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Quick Login Check (quickLoginCheckMilliSeconds)", definition: "The brute-force detection field defining how close together (in milliseconds) two failed logins must be before Keycloak treats the second as an automated \"quick\" retry rather than a normal one, applying minimumQuickLoginWaitSeconds instead of the normal wait calculation.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Minimum Quick Login Wait (minimumQuickLoginWaitSeconds)", definition: "The wait period applied specifically to failed logins arriving faster than quickLoginCheckMilliSeconds apart — Keycloak's defense against automated, rapid-fire guessing specifically, distinct from the normal human-paced wait calculation.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Permanent lockout (Keycloak)", definition: "The permanentLockout realm field (boolean): when true, a triggered brute-force lockout disables the account until an administrator manually re-enables it, instead of auto-expiring after a wait period. This chapter's lab used the default (false, auto-expiring) form and confirmed the auto-recovery directly.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Brute-force strategy (bruteForceStrategy)", definition: "A newer realm field (MULTIPLE or LINEAR) controlling how the lockout wait time grows as failures accumulate past Max Login Failures — MULTIPLE (the default, confirmed in this chapter's lab) grows in steps at each multiple of the threshold; LINEAR grows by a fixed increment per failure past the threshold.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Max Temporary Lockouts (maxTemporaryLockouts)", definition: "A newer realm field: once a user has been temporarily locked out this many separate times, the account escalates to a permanent lockout requiring admin intervention. 0 (the confirmed default) disables this escalation entirely.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Attack Detection API (Keycloak)", definition: "The Admin REST API's /admin/realms/{realm}/attack-detection/brute-force/users/{id} endpoint: GET returns a user's real-time brute-force state (numFailures, disabled, failedLoginNotBefore, numTemporaryLockouts, lastIPFailure); DELETE clears it, immediately un-locking the account without waiting. Both verbs were exercised for real against a live lockout in this chapter's lab.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "OTP Policy (Keycloak)", definition: "The Realm Settings → Authentication → Policy → OTP Policy tab's fields (otpPolicyType, otpPolicyAlgorithm, otpPolicyDigits, otpPolicyPeriod, otpPolicyLookAheadWindow, otpPolicyCodeReusable, otpPolicyInitialCounter), governing how every TOTP/HOTP code in the realm is generated and validated — the concrete Keycloak implementation of chapter 5's TOTP/HOTP mechanics.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "OTP hash algorithm (otpPolicyAlgorithm)", definition: "The realm OTP Policy field selecting which HMAC variant (HmacSHA1 default, HmacSHA256, HmacSHA512) generates OTP codes. Changing it does not retroactively re-derive already-enrolled users' secrets — existing enrollments can effectively stop validating and need re-enrollment, confirmed as a real operational risk, not just a theoretical one, in this chapter.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Look-ahead window (otpPolicyLookAheadWindow)", definition: "The OTP Policy field (console label \"Look around window\") setting how many time steps before and after the current one the server still accepts a code for — existing specifically to tolerate realistic clock drift between a user's device and the server, the synchronization requirement chapter 5's TOTP glossary entry already flagged.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },
  { term: "Reusable OTP code (otpPolicyCodeReusable)", definition: "The OTP Policy boolean field (default false, confirmed) controlling whether a successfully-used OTP code can be submitted again while still inside its valid time window. Leaving it false closes a real replay opportunity that a short validity period alone does not fully close.", category: "Keycloak Core", chapters: ["password-policies-and-mfa"] },

  { term: "Identity Provider alias", definition: "The short, unique, realm-scoped name (e.g. northwind-corporate-idp) that identifies one configured Identity Provider resource, used in the kc_idp_hint query parameter and baked into the fixed broker-endpoint redirect URI convention. Does not have to match the external realm's own name, though this chapter's lab made them match for clarity.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "kc_idp_hint", definition: "A query parameter on Keycloak's authorization endpoint naming a specific Identity Provider's alias, which skips the realm's own login-picker page and redirects straight to that external IdP. An unrecognized or misspelled value fails open to the ordinary picker rather than erroring, confirmed in this chapter's lab.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Broker endpoint URI", definition: "Keycloak's fixed redirect URI convention for identity brokering: /realms/{broker realm}/broker/{IdP alias}/endpoint. This exact path must be registered as a valid redirect URI on the client the external IdP's own realm uses to authenticate the broker; a wrong segment produces an invalid-redirect-uri rejection at the external IdP's own authorize step, confirmed live in this chapter.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Federated identity record", definition: "The link Keycloak creates and stores after a successful brokered login, pairing a local user's id with a specific external Identity Provider's alias and that IdP's own user id/username. Confirmed live via GET users/{id}/federated-identity — this record, not anything on the user object itself, is what lets Keycloak recognize the same external person on a later login.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Account linking (brokered)", definition: "The First Broker Login outcome where a brokered external identity is attached to an existing local user (matched by email, with Trust Email enabled) instead of a new local user being just-in-time provisioned. Contrast with JIT provisioning, the outcome when no matching local account exists.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Sync Mode (legacy / import / force)", definition: "A Keycloak Identity Provider setting controlling whether user attributes update after first login. import (this chapter's setting) copies attributes once, at first login, and never again automatically; force updates them from the external IdP on every subsequent login where possible; legacy preserves pre-this-feature Keycloak behavior. Confirmed against Keycloak's own Server Administration Guide.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Identity Provider mapper", definition: "A realm-scoped rule attached to an Identity Provider that copies an external claim or attribute into a local user attribute, role, or group membership — the mechanism behind mapping, e.g., an external IdP's department claim onto a Keycloak group. This chapter's lab used none (default attribute import already populated name/email), but role/group mapping for a real enterprise rollout requires them explicitly.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Trust Email (Identity Provider setting)", definition: "An Identity Provider setting that treats the external IdP's email claim as already verified. Combined with Sync Mode and a matching existing local user, this is what triggers account linking instead of a new JIT-provisioned user on first brokered login.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Default Identity Provider (realm setting)", definition: "A realm-level setting naming one configured Identity Provider that Keycloak redirects every login to automatically, with no caller needing to pass kc_idp_hint. If the configured default IdP isn't found, the realm's ordinary login form is shown instead (confirmed in Keycloak's own Server Administration Guide) — the same kc_idp_hint-processing authenticator handles both mechanisms.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "First Login Flow (Identity Provider setting)", definition: "A per-Identity-Provider setting choosing which authentication flow Keycloak runs the first time a user logs in via that specific IdP — defaults to the realm's built-in First Broker Login flow, but can be pointed at a different, customized flow per IdP.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Post Login Flow (Identity Provider setting)", definition: "A per-Identity-Provider setting naming a flow Keycloak runs after every brokered login finishes, not just the first — the mechanism for demanding an extra step (e.g. MFA) on top of an external IdP's own login every time, regardless of whether the user is already linked.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Hide on Login Page (Identity Provider setting)", definition: "An Identity Provider setting that, when on, removes that provider's button from the realm's login picker entirely — callers can still reach it only via kc_idp_hint (confirmed directly in Keycloak's Server Administration Guide, which names kc_idp_hint specifically as the way to reach a hidden provider). The real mechanism behind an enterprise-only broker that should never appear as an option to ordinary consumer users.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Account Linking Only (Identity Provider setting)", definition: "An Identity Provider setting that restricts a configured IdP to linking existing accounts only — it cannot be used to log a user in directly, and does not appear on the login page at all. Distinct from an ordinary brokering IdP, which can both authenticate and (via First Broker Login) create or link accounts.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Identity Provider instance (Keycloak resource)", definition: "The concrete, realm-scoped configuration resource (alias, providerId, and a config map of endpoint URLs, client credentials, and behavior settings) that implements chapter 7's abstract Identity Provider role inside Keycloak. Distinct from the generic IAM concept of an IdP: this is the specific administrative object a realm's admin creates and edits, confirmed in this chapter via kcadm.sh create identity-provider/instances.", category: "Keycloak Core", chapters: ["identity-brokering"] },
  { term: "Review Profile (required action)", definition: "A required action Keycloak can attach to the First Broker Login flow, prompting a newly brokered user to confirm or edit their profile fields (name, email) before a local account is finalized. This chapter's lab left it unconfigured, so First Broker Login completed without showing any form.", category: "Keycloak Core", chapters: ["identity-brokering"] },

  { term: "User Federation (Keycloak)", definition: "Keycloak's mechanism for consuming an external identity store's existing user population — most commonly an LDAP or Active Directory directory — instead of migrating accounts into Keycloak's own database. Implements chapter 7's abstract federation concept concretely: the external store remains the authoritative source for the data (and, in the default configuration, the credential), and Keycloak only ever reads from or syncs against it.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "LDAP User Federation Provider", definition: "Keycloak's built-in, no-custom-code provider (providerId \"ldap\") that federates a realm against an LDAP-speaking directory — configured with a connection URL, a Bind DN/Credential, a Users DN, and an edit mode, among other fields, confirmed live via the Admin REST API's /admin/realms/{realm}/components endpoint.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Edit Mode (LDAP federation)", definition: "The LDAP User Federation provider setting that determines where a write made through Keycloak on a federated attribute actually ends up: READ_ONLY (rejected), WRITABLE (pushed to the real directory), or UNSYNCED (stored only as a local Keycloak-side override). Distinct from whether Keycloak can read an attribute at all, which sync and mappers control separately.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "READ_ONLY edit mode", definition: "An LDAP federation edit mode where Keycloak cannot write any change back to the directory at all; an attempted write on a federated attribute is rejected. The realistic default for federating against a directory a separate team owns and operates — the mode this course's own lab uses for Meridian Trust's case study.", category: "Keycloak Core", chapters: ["user-federation-ldap", "case-study-riverside"] },
  { term: "WRITABLE edit mode", definition: "An LDAP federation edit mode where a write made through Keycloak (e.g. a password reset or profile edit) is pushed through to the real LDAP directory record in real time, requiring a bind credential with write permission on that directory.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "UNSYNCED edit mode", definition: "An LDAP federation edit mode where a write made through Keycloak is neither rejected (as in READ_ONLY) nor pushed to the directory (as in WRITABLE); instead Keycloak stores its own local override of just that attribute, leaving the source directory's record completely unchanged.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "LDAP Mapper", definition: "A sub-component of an LDAP User Federation Provider that translates one LDAP attribute into one Keycloak concept (a user-model field, a group, a role). Five user-attribute mappers (username, first name, last name, email, and two timestamps) are created automatically; any other attribute or group membership needs an explicit mapper of its own, confirmed directly in this course's own lab where neither a custom attribute nor group membership appeared until a mapper was added for each.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "User Attribute LDAP Mapper", definition: "An LDAP mapper type that copies one specific LDAP attribute into one specific Keycloak user attribute. Needed for anything beyond Keycloak's five built-in fields — this course's lab added one for Meridian Trust's employeeType attribute, which otherwise never appeared on the synced user no matter how many times the provider was synced.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Group LDAP Mapper", definition: "An LDAP mapper type that reads a directory's own group entries (e.g. groupOfNames entries under a groups subtree) and materializes them as real Keycloak groups with real membership, rather than requiring group membership to be re-created by hand inside Keycloak. Without one, a federated user's real directory group membership is invisible to Keycloak entirely.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Full sync (LDAP federation)", definition: "An on-demand or scheduled operation that reads every entry under an LDAP provider's Users DN and writes (or updates) the corresponding Keycloak user records, reporting counts of added/updated/removed/failed users. A successful full sync (zero failed) only confirms the read-and-write operation itself succeeded — it says nothing about whether the configured mappers are reading the attributes a specialist actually intended, as this course's own lab demonstrated directly.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Vendor setting (LDAP federation)", definition: "An LDAP User Federation Provider configuration field that tells Keycloak which directory product it's talking to (e.g. Active Directory, or \"Other\" for a generic LDAP server), enabling or disabling vendor-specific behaviors. Set to \"Other\" for a plain OpenLDAP directory, since the Active Directory preset turns on AD-specific assumptions a generic LDAP server doesn't satisfy.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Users DN (LDAP federation)", definition: "The Distinguished Name of the subtree an LDAP User Federation Provider searches for user entries. A Users DN that doesn't actually contain the real user entries doesn't produce a visible sync error — it produces a sync that completes successfully and simply finds nothing, which is why this is a common, quiet misconfiguration to check first when a sync reports zero users with no error.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Bind DN / Bind Credential (LDAP federation config)", definition: "The Distinguished Name and password an LDAP User Federation Provider itself authenticates to the directory with, in order to search for and read user entries — distinct from the end user's own credential, which is checked by a separate, later Bind operation at login time. A wrong value here fails loudly and specifically (confirmed live via testLDAPConnection's testAuthentication action returning an AuthenticationFailure error), unlike a wrong Users DN, which fails silently.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "testLDAPConnection (Admin REST endpoint)", definition: "The Admin REST API endpoint (POST /admin/realms/{realm}/testLDAPConnection) backing the Admin Console's \"Test connection\" and \"Test authentication\" buttons for an LDAP provider, confirmed live in this course's lab: a testConnection action checks only reachability, and a separate testAuthentication action checks the bind credential specifically — isolating two different failure causes that would otherwise both just look like \"the LDAP provider doesn't work.\"", category: "Keycloak Operations", chapters: ["user-federation-ldap"] },
  { term: "Federated user (Keycloak)", definition: "A Keycloak user record whose data originates from, and is kept in sync with, an external store via a User Federation provider — identifiable by a non-empty federationLink field pointing at the provider's component id. Distinct from a locally-created user: deleting the federation provider orphans the synced copy rather than deleting a real account, since the real account never lived in Keycloak's own store.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Custom User LDAP Filter", definition: "An optional LDAP User Federation Provider setting that further restricts which entries under the Users DN are treated as valid users via an additional LDAP search filter, on top of the configured object classes. Like a wrong Users DN, a filter that excludes real user entries fails silently — a sync completes with no error and simply imports fewer users than expected.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },
  { term: "Search Scope (LDAP federation config)", definition: "An LDAP User Federation Provider setting (one level vs. subtree, following standard LDAP search-scope semantics) controlling how deep under the Users DN the provider searches for user entries. A subtree scope (the setting this course's lab used) searches the full tree beneath the Users DN; a one-level scope only searches entries directly beneath it.", category: "Keycloak Core", chapters: ["user-federation-ldap"] },

  { term: "User Storage SPI", definition: "The Keycloak Service Provider Interface for bridging an external user store Keycloak doesn't understand natively (neither its own local database nor LDAP) into its internal UserModel. Like every Keycloak SPI, it follows a Factory (discovered once, at boot, via Java's ServiceLoader) plus Provider (created fresh per transaction) pattern. Keycloak's own built-in LDAP federation provider (chapter 32) is itself written against this exact SPI, not special-cased.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "UserStorageProvider", definition: "The base interface every custom user federation provider implements, plus whichever optional capability interfaces (UserLookupProvider, CredentialInputValidator, UserQueryMethodsProvider, ...) it actually needs. As of Keycloak 26.4+, this interface lives in the keycloak-model-storage Maven module, not keycloak-server-spi — confirmed live for 26.8.2 by inspecting both Maven Central's metadata and the real jars inside the running server image.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "UserStorageProviderFactory", definition: "The factory interface Keycloak discovers once, at server boot, via a META-INF/services/org.keycloak.storage.UserStorageProviderFactory file (the standard Java ServiceLoader convention). Its getId() is the provider id shown in the Admin Console's User Federation 'Add provider' dropdown; its create(KeycloakSession, ComponentModel) is called fresh per Keycloak transaction to produce a UserStorageProvider instance.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "Provider capability interface", definition: "An optional interface (UserLookupProvider, CredentialInputValidator, UserQueryMethodsProvider, UserRegistrationProvider, ...) a UserStorageProvider implements to opt into specific behavior. A provider implementing only UserLookupProvider and CredentialInputValidator, for instance, can authenticate a federated user by exact username but won't appear in the Admin Console's user search, which additionally requires UserQueryMethodsProvider — confirmed live in chapter 33's own lab.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "AbstractUserAdapter", definition: "A keycloak-model-storage base class that implements nearly all of UserModel with read-only defaults — every method except getUsername(), plus (confirmed the hard way via a real compile error in chapter 33) UserModel.credentialManager(), which it leaves abstract. Every update method throws ReadOnlyException unless explicitly overridden, which is the correct behavior for a provider bridging a store Keycloak has no way to write back into.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "Federated user id (StorageId convention)", definition: "The id format Keycloak assigns a user sourced from a UserStorageProvider: 'f:' + the federation component's own UUID + ':' + the external username, e.g. f:f3e51733-...:jmartinez. org.keycloak.storage.StorageId.externalId() strips this prefix back off so a provider's getUserById() can delegate to its own getUserByUsername().", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "META-INF/services provider registration", definition: "The plain-text file convention (the standard Java ServiceLoader mechanism) a Keycloak SPI provider JAR bundles to announce itself — e.g. META-INF/services/org.keycloak.storage.UserStorageProviderFactory, containing one fully qualified factory class name. A missing or misnamed file fails silently: the provider simply never appears anywhere, with no error logged.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "kc.sh build (re-augmentation)", definition: "The Keycloak server CLI command that re-runs Quarkus's build-time augmentation step so a newly deployed provider JAR (dropped into /opt/keycloak/providers/) is actually picked up, followed by a server restart. Required before a production deployment started with plain start notices a new provider at all; a server started with start-dev re-augments automatically on every boot, but running kc.sh build explicitly still makes that mechanism visible — confirmed live in chapter 33.", category: "Keycloak Operations", chapters: ["custom-user-storage-spi"] },
  { term: "SubjectCredentialManager", definition: "The interface UserModel.credentialManager() returns, covering the full surface of credential operations (isValid, updateCredential, getStoredCredentialsStream, ...). A federated provider built on the older CredentialInputValidator-style capability interfaces doesn't need to implement this whole surface itself — Keycloak core's own org.keycloak.credential.UserCredentialManager bridges one to the other.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "CredentialInputValidator", definition: "The provider capability interface with three methods — supportsCredentialType, isConfiguredFor, isValid — that lets a UserStorageProvider answer 'is this submitted password correct for this user?' without implementing a full custom authenticator. isValid() receives a CredentialInput carrying the submitted value and is where a provider compares it against its own external store.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "CredentialInput", definition: "The object carrying a submitted credential's type and raw value (via getChallengeResponse()) into a CredentialInputValidator's isValid() check. It is the same shape whether the caller is a browser login form, a direct-grant curl call, or any other Keycloak authentication path.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "Component (Keycloak) / parentId", definition: "Keycloak's internal representation of a configurable, pluggable piece of a realm — key providers, client-registration policies, and user federation providers (including custom SPI providers) are all components. Every realm-level component's parentId must be the realm's actual UUID id, not its human-readable realm name; setting it to the name instead creates a component that is accepted (HTTP 201) but silently orphaned, confirmed directly in chapter 33's own lab.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "Provided dependency scope (Keycloak SPI jars)", definition: "The Maven scope a custom Keycloak provider's pom.xml should declare for keycloak-server-spi/keycloak-model-storage: the running server already supplies these exact classes from its own /opt/keycloak/lib at runtime, so the provider's own JAR should not bundle them. Confirmed directly in chapter 33: the built JAR contained only the chapter's own 5 classes, a CSV resource, and its service-registration file — no Keycloak classes at all.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "SPI version skew (classloading conflict)", definition: "The real failure mode where a custom provider's JAR is built against (or bundles) a different version of Keycloak's SPI classes than the server actually running it, placing two incompatible or duplicate copies of the same classes on the server's classloader. Avoided in chapter 33 by live-verifying exact matching 26.8.2 coordinates on Maven Central and inside the real running server image before writing the POM, rather than guessing.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },
  { term: "Read-only user storage provider", definition: "A UserStorageProvider whose adapter (typically extending AbstractUserAdapter) overrides no write methods at all, so every attempted update throws ReadOnlyException by default — the correct shape for bridging a legacy external system Keycloak has no mechanism to write back into, as opposed to one that also implements UserRegistrationProvider/CredentialInputUpdater to support writes.", category: "Keycloak Core", chapters: ["custom-user-storage-spi"] },

  { term: "spring-boot-starter-oauth2-resource-server", definition: "The Spring Boot starter dependency that turns an application into an OAuth2 Resource Server: once added alongside an issuer-uri configuration property, Spring Security automatically fetches the issuer's OpenID Connect discovery document, caches and refreshes its JWKS, and verifies every incoming bearer token's signature, issuer, and expiry on every request — with no custom code for any of those three checks.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "OAuth2 Resource Server (Spring Security)", definition: "Spring Security's name for the role chapter 13 calls the Resource Server: an application that accepts no credentials of its own and instead authenticates every request solely by validating an incoming bearer token against a configured authorization server's issuer and keys.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "issuer-uri (Spring Boot property)", definition: "The spring.security.oauth2.resourceserver.jwt.issuer-uri property naming the authorization server a resource server trusts. Spring Boot fetches <issuer-uri>/.well-known/openid-configuration from it at startup to learn the token issuer string and JWKS endpoint; a token whose own issuer claim doesn't exactly match this value (scheme, host, and port included) is rejected with 401, even if otherwise perfectly valid.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "JwtAuthenticationConverter", definition: "The Spring Security class that converts a validated Jwt into an Authentication object, combining default claim extraction (e.g. sub as the principal name) with a pluggable Converter<Jwt, Collection<GrantedAuthority>> for turning token claims into granted authorities.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "JwtGrantedAuthoritiesConverter (default)", definition: "Spring Security's built-in default converter from a validated Jwt's claims to GrantedAuthority objects. It reads a flat, space-separated scope or scp claim — the shape a generic OAuth2 authorization server's access token carries — and does not read Keycloak's nested realm_access.roles claim at all, which silently produces zero authorities (and a 403 on any role-protected endpoint) against an otherwise perfectly valid Keycloak-issued token.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "realm_access claim", definition: "A Keycloak-specific (non-standard, not part of RFC 9068's JWT access-token profile) access-token claim shaped {\"roles\": [...]}, carrying every realm-level role the token's subject holds. A generic OAuth2 library's default authorities-from-claims mapping does not know to look here, which is the root cause of a well-documented real-world gotcha when wiring a Keycloak realm up to a generic OAuth2 resource-server library.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "GrantedAuthority (Spring Security)", definition: "Spring Security's interface representing one permission held by an authenticated principal — the unit an authorization check (hasRole, hasAuthority, @PreAuthorize) actually tests against. An authenticated request with zero granted authorities still passes authentication but fails every authorization check, producing 403, not 401.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "ROLE_ authority prefix", definition: "Spring Security's convention that hasRole(\"x\")/hasAnyRole(...)/@PreAuthorize(\"hasRole('x')\") actually check for an authority literally named ROLE_x — a custom GrantedAuthoritiesConverter mapping Keycloak roles into Spring Security authorities must add this prefix itself, since Keycloak's own role names (e.g. billing-admin) never carry it.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "SecurityFilterChain (bean)", definition: "The Spring Security configuration bean (returned from an HttpSecurity builder) that declares, per URL pattern, which requests require authentication and which authorities they require — the filter-chain-level counterpart to method-level @PreAuthorize.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "@PreAuthorize", definition: "A Spring Security method-security annotation evaluating a SpEL authorization expression (e.g. hasRole('billing-admin')) before a method body runs, requiring @EnableMethodSecurity to be active. A complementary enforcement point to filter-chain-level requestMatchers(...).hasRole(...) — both can protect the same application at different layers.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "@EnableMethodSecurity", definition: "The Spring Security annotation that turns on method-level security annotations such as @PreAuthorize/@PostAuthorize across a Spring application context; without it, those annotations are silently ignored rather than enforced.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "Stateless session policy (resource server)", definition: "A SessionCreationPolicy.STATELESS setting telling Spring Security to never create or rely on an HTTP session — appropriate for a pure bearer-token resource server where every request is expected to carry its own complete proof of authentication, with nothing stored server-side between requests.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "CSRF protection (and when to disable it)", definition: "A defense against a forged cross-site request riding on a victim's browser automatically attaching a session cookie to a request the victim never intended. Meaningful only for cookie-authenticated, browser-submitted requests; a stateless bearer-token resource server that never authenticates via a cookie has nothing for CSRF protection to defend, which is why disabling it there is correct rather than a shortcut — the same reasoning does not apply to a cookie-authenticated server-rendered app.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "401 vs. 403 (resource server)", definition: "401 Unauthorized means authentication itself failed — a missing, malformed, expired, or wrong-issuer bearer token; the request never established who (or what) is calling. 403 Forbidden means authentication succeeded but the resulting authorities don't satisfy the endpoint's requirement. Conflating the two wastes debugging time: a 403 on a token that decodes correctly almost never means the token is bad, it means the authorization check (or the claims-to-authorities mapping feeding it) is wrong.", category: "Spring Security / Resource Servers", chapters: ["securing-a-backend-api"] },
  { term: "VERIFY_PROFILE (dynamic required action)", definition: "A Keycloak required action computed dynamically against the realm's Declarative User Profile at login time — e.g. when a required attribute like firstName/lastName is missing — rather than stored in a user's own persisted requiredActions list. Because it isn't stored, inspecting a user's requiredActions via the Admin REST API can show an empty list even while a direct-grant token request for that user fails with \"Account is not fully set up\" — confirmed live in this chapter's own lab, and independently hit again in chapter 41's two-node clustering lab, where it had nothing to do with clustering at all — a recurring trap worth recognizing on sight regardless of what else a lab happens to be testing.", category: "Keycloak Core", chapters: ["securing-a-backend-api", "high-availability-clustering"] },
  { term: "docker compose !override (YAML merge tag)", definition: "A Compose Specification YAML tag (ports: !override [...]) forcing a field to be fully replaced rather than merged when a -f override file is layered on a base compose file — needed because Compose's default list-merge behavior for fields like ports concatenates entries from every -f file instead of replacing them, which can cause a spurious host-port-already-allocated collision if a base file's own port mapping is still present underneath an intended override.", category: "Lab infrastructure", chapters: ["securing-a-backend-api"] },
  { term: "Client-credentials vs. direct-grant token (as test techniques)", definition: "Two ways to obtain a real token for testing a resource server: a client-credentials token represents a pure machine caller with no human identity (matching a real unattended service), while a direct-grant token represents a specific human identity (carrying a real sub/preferred_username), useful for proving role-based differences between two distinct users. A resource server must handle both identically, since both are ordinary, equally valid bearer tokens by the time they reach it.", category: "OAuth grants", chapters: ["securing-a-backend-api"] },

  { term: "react-oidc-context", definition: "A React library providing an <AuthProvider> component and a useAuth() hook that perform the full OIDC authorization-code-with-PKCE flow (chapters 13/15) on a client's behalf — signinRedirect(), the token exchange, and decoded ID-token claims exposed as user.profile — without the application reimplementing the handshake by hand. Wraps oidc-client-ts.", category: "Tooling", chapters: ["securing-a-frontend-spa"] },
  { term: "oidc-client-ts", definition: "The underlying TypeScript OIDC/OAuth2 client library react-oidc-context wraps — manages PKCE pair generation, the token endpoint exchange, and (by default, when no custom store is configured) in-memory token storage.", category: "Tooling", chapters: ["securing-a-frontend-spa"] },
  { term: "AuthProvider (react-oidc-context)", definition: "The React context provider wrapping an application's root, configured with the OIDC authority, client_id, redirect_uri, and scope; makes auth state available to every descendant component via useAuth().", category: "Tooling", chapters: ["securing-a-frontend-spa"] },
  { term: "useAuth (react-oidc-context hook)", definition: "A React hook exposing the current authentication state (isLoading, isAuthenticated, user.profile, error) and actions (signinRedirect(), removeUser()) anywhere inside an <AuthProvider> tree.", category: "Tooling", chapters: ["securing-a-frontend-spa"] },
  { term: "Silent token renewal", definition: "Obtaining a new access token in the background, without interrupting the user, before the current one expires — either via a refresh token POSTed directly to the token endpoint, or via an iframe re-running the authorization request with prompt=none. The iframe variant is more fragile because it depends on third-party cookie behavior that browsers like Safari restrict.", category: "OAuth/OIDC Security", chapters: ["securing-a-frontend-spa"] },
  { term: "Backend-for-frontend (BFF) pattern", definition: "An architecture where a server-side component, not the browser, holds OAuth/OIDC tokens and talks to the authorization server and resource APIs directly; the browser holds only a session cookie. Removes tokens from the browser's JavaScript context entirely, at the cost of an extra server component the simpler SPA-direct pattern doesn't need.", category: "OAuth/OIDC Security", chapters: ["securing-a-frontend-spa"] },
  { term: "In-memory token storage", definition: "Keeping OIDC/OAuth tokens only in a running JavaScript variable (never localStorage/sessionStorage), so they are lost on a full page reload but are only exposed to an attacker's script for as long as that script and the page both remain live. oidc-client-ts's default when no persistent userStore is configured.", category: "OAuth/OIDC Security", chapters: ["securing-a-frontend-spa"] },
  { term: "post_logout_redirect_uri", definition: "An OIDC end-session parameter naming where the authorization server should send the browser after it has ended its own session, distinct from and registered alongside a client's ordinary redirect_uri. Needed for a complete logout — clearing only the SPA's local state (e.g. react-oidc-context's removeUser()) without this leaves the IdP's own session alive, which a later silent renewal could reuse.", category: "OAuth/OIDC Security", chapters: ["securing-a-frontend-spa"] },
  { term: "Single-page application (SPA)", definition: "A web application that loads once and then updates its own DOM via JavaScript rather than requesting whole new pages from a server. The textbook OAuth public client: its entire source, including anything resembling a secret, ships to and is readable in the user's browser.", category: "OAuth/OIDC Security", chapters: ["securing-a-frontend-spa"] },
  { term: "npm engines field", definition: "A package.json field (and the corresponding npm view <pkg> engines lookup) declaring the Node.js version range a package actually supports. Checking it before installing — rather than after an install fails or silently misbehaves — is how this chapter determined current Vite needs Node 20.19+/22.12+ while Vite 6.x still supports Node 18.", category: "Tooling", chapters: ["securing-a-frontend-spa"] },
  { term: "Vite", definition: "A frontend build tool and dev server providing fast module reloading with no separate bundling step during development. Its current major (7.x/8.x at time of writing) requires Node 20.19+/22.12+; Vite 6.x is the newest major that still supports Node 18, live-verified for this chapter's lab rather than assumed.", category: "Tooling", chapters: ["securing-a-frontend-spa"] },
  { term: "onSigninCallback", definition: "An AuthProvider configuration callback invoked once react-oidc-context has processed the ?code=...&state=... query string returned from the authorization server, typically used to strip those parameters from the URL (via history.replaceState) so a page refresh doesn't attempt to replay an already-consumed, single-use authorization code.", category: "Tooling", chapters: ["securing-a-frontend-spa"] },
  { term: "PKCE Code Challenge Method (Keycloak client setting)", definition: "An advanced Keycloak client attribute (pkce.code.challenge.method) forcing a specific PKCE method — typically S256 — so the client cannot complete an authorization-code flow without presenting a verifying code_verifier at the token endpoint, even if the requesting code omitted PKCE parameters.", category: "Keycloak core", chapters: ["securing-a-frontend-spa"] },
  { term: "Token exfiltration via XSS", definition: "The specific attack a browser-based client's token-storage choice is defending against: a cross-site-scripting bug running attacker-controlled JavaScript inside the page, which can read any token kept in a JS-accessible location (an in-memory variable while the script runs, or persistently in sessionStorage/localStorage) and exfiltrate it to an attacker-controlled endpoint.", category: "OAuth/OIDC Security", chapters: ["securing-a-frontend-spa"] },
  { term: "PKCE error specificity (Keycloak finding)", definition: "A live, verified finding: unlike the Duende demo server chapter 13 tested (which returns the identical generic invalid_grant for a bad code, a reused code, and a wrong PKCE verifier), a real Keycloak instance returns the same invalid_grant error code but a distinct, diagnostic error_description for each distinct PKCE failure cause (\"Code not valid\" / \"PKCE verification failed: Code mismatch\" / \"PKCE code verifier not specified\") — a genuine, honestly-reported difference between two real authorization servers' error-handling philosophies.", category: "Keycloak core", chapters: ["securing-a-frontend-spa"] },

  { term: "realm-management client", definition: "Keycloak's own built-in, per-realm client (created automatically alongside every realm) whose client roles — view-users, manage-users, view-realm, manage-realm, query-users, query-groups, and more — are the concrete permission units the Admin REST API checks against a caller's resource_access claim. Confirmed live in chapter 36 by listing this client's full role set and mapping one of its roles directly onto a service account's dedicated user.", category: "Keycloak Core", chapters: ["service-to-service-auth"] },
  { term: "view-users (realm-management client role)", definition: "A composite, read-only client role on Keycloak's built-in realm-management client, granting the ability to list and read user records via the Admin REST API without granting any write access. Composes further into query-users and query-groups, both of which appear automatically in a token carrying it. The narrow, least-privilege choice for a caller — like a fraud-scoring service — that only ever needs to read account data.", category: "Keycloak Core", chapters: ["service-to-service-auth"] },
  { term: "manage-users (realm-management client role)", definition: "The read-write counterpart to view-users on Keycloak's built-in realm-management client, additionally granting the ability to create, modify, and delete user records via the Admin REST API. Over-granting this to a caller that only ever needs to read data turns a leaked credential into a much larger incident than the caller's actual job justifies.", category: "Keycloak Core", chapters: ["service-to-service-auth"] },
  { term: "Scope-gated authentication check (kc-admin-api)", definition: "An earlier, independent check the Admin REST API performs before any role is consulted: does the presented bearer token carry the kc-admin-api client scope at all? A token missing it is rejected with a flat 401 Unauthorized, regardless of whether its role mappings would otherwise be sufficient — confirmed live in chapter 36 against a service account with a verified-correct role mapping that still failed this earlier gate.", category: "Keycloak Operations", chapters: ["service-to-service-auth", "admin-api-and-cli"] },
  { term: "Role-gated authorization check (Admin REST API)", definition: "The second, later check the Admin REST API performs, only after a token has already cleared the scope-gated authentication check: does the token's resource_access for the realm-management client contain the specific role this exact endpoint and HTTP verb require? A token that clears the first check but fails this one is rejected with a 403 Forbidden, not a 401 — a genuinely different failure confirmed as distinct in chapter 36's lab.", category: "Keycloak Operations", chapters: ["service-to-service-auth"] },
  { term: "Under-scoped service account (no role mappings)", definition: "A service account whose client correctly carries the kc-admin-api scope (so its tokens clear the Admin REST API's authentication gate) but holds no realm-management role mappings at all. Such a token is recognized and authenticated, then rejected with a 403 Forbidden on every protected call — a clean authorization failure, confirmed in chapter 36 as distinct from an unscoped token's 401.", category: "Keycloak Operations", chapters: ["service-to-service-auth"] },
  { term: "Per-resource access flags (Admin REST API)", definition: "A small access object (e.g. {\"manage\": false}) Keycloak's Admin REST API embeds directly into certain response representations, stating what the current caller is itself permitted to do with that specific returned resource. Confirmed live in chapter 36: a view-users-scoped token's GET on a user record returned access.manage: false inline, without a second request being needed to learn that fact.", category: "Keycloak Operations", chapters: ["service-to-service-auth"] },
  { term: "Meridian Trust fraud-detection service (case study)", definition: "Meridian Trust's nightly, unattended fraud-scoring pipeline, modeled in chapter 36 as a confidential Keycloak client (fraud-detection-service) with its service account scoped to the narrow, read-only view-users role rather than the broad manage-users role an earlier, over-provisioned version held — the chapter's concrete illustration of least-privilege scoping for a machine caller under PCI-DSS review.", category: "Keycloak Core", chapters: ["service-to-service-auth"] },

  { term: "Resource server (Keycloak Authorization Services)", definition: "An OAuth 2.0 role (RFC 6749) for the API/application that hosts and protects resources. In Keycloak, switching on Authorization Enabled for a confidential client turns that client itself into a resource server, adding its own Resources, Authorization Scopes, Policies, and Permissions sub-API (the authz/resource-server REST namespace this chapter's lab drove directly).", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Resource (Keycloak authorization)", definition: "A protected object registered with a resource server — a name, optional type, optional URIs, an owner (the client by default, or a specific user under owner-managed access), and a list of authorization scopes it can be accessed through. Confirmed live: a resource's own scopes array must list a scope before any permission can reference that resource+scope pair together.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Authorization scope (Keycloak)", definition: "A named action a resource can be accessed through (e.g. view, edit), attached to one or more resources and referenced by permissions. Deliberately not the same mechanism as an OAuth scope (chapters 13, 24) despite sharing the word \"scope\" — an authorization scope is attached ahead of time to a resource inside one resource server and evaluated by policy at decision time, never negotiated in a token request.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Policy (Keycloak authorization)", definition: "A reusable rule — role, user, client, group, client-scope, time, regex, or aggregate — that evaluates to a PERMIT/DENY vote, independent of any specific resource. The same policy can back many permissions. Live-verified on Keycloak 26.8.2: the policy-provider list no longer includes a JavaScript/\"script\" policy type at all — attempting the old .../policy/js REST endpoint directly returns a 404, not a disabled feature.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Permission (Keycloak authorization)", definition: "The object that ties a resource (a resource-based permission) or a resource+scope pair (a scope-based permission) to one or more policies, plus a decision strategy for combining their votes into one outcome. The join point of Keycloak's Authorization Services model.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Decision strategy", definition: "The rule a Keycloak permission (or an aggregated policy) uses to combine multiple referenced policies' individual votes into one PERMIT/DENY: Unanimous (default — every policy must vote PERMIT), Affirmative (one PERMIT vote is enough), or Consensus (majority rules; a tie denies). Confirmed to genuinely change outcomes live: the identical request from the identical role-less user returned 403 under Unanimous and 200 under Affirmative once a second, trivially-true policy was added.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services", "case-study-riverside"] },
  { term: "UMA 2.0 (User-Managed Access)", definition: "An OAuth 2.0-based authorization protocol, standardized by the Kantara Initiative, built around a resource owner delegating access to their own resources to other parties at runtime rather than an admin pre-assigning static roles. Its defining shape is two separate exchanges: an initial rejection that carries a permission ticket, then a separate ticket-for-token exchange at the authorization server's token endpoint. Keycloak's Authorization Services implements this grant directly at its realm token endpoint.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Permission ticket", definition: "An opaque, short-lived, signed token a resource server's Protection API issues (POST .../authz/protection/permission) naming exactly which resource and authorization scopes a pending request needs access to — but not yet who is asking. Exchanged, once, at the token endpoint (grant_type=urn:ietf:params:oauth:grant-type:uma-ticket) for a Requesting Party Token.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Requesting Party Token (RPT)", definition: "The OAuth access token issued after a successful UMA ticket exchange, carrying an authorization.permissions claim that lists exactly which resource+scope pairs this specific subject was just granted, computed at request time from a live policy evaluation rather than a role assigned in advance. Confirmed live: the Authorization: Bearer header on the ticket-exchange request is how Keycloak learns the requesting party's identity.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Policy Enforcement Point (PEP)", definition: "The component in front of a protected resource that intercepts a request, obtains a permission ticket on an unauthenticated/unticketed request, and enforces whichever decision the Policy Decision Point ultimately returns. In Keycloak's model this is your own application/resource server; Keycloak itself never plays this role.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Policy Decision Point (PDP)", definition: "The component that actually evaluates registered policies against a request and returns PERMIT or DENY. Keycloak's Authorization Services engine is the PDP for any client with Authorization Enabled — the application (the PEP) never computes this decision itself, only enforces it.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Protection API (Keycloak)", definition: "Keycloak's realm-level REST endpoints under /realms/{realm}/authz/protection/*, used by a resource server to register resources/scopes and to request permission tickets, authenticated with the resource server's own service-account (client credentials) token. The real PEP-facing surface this chapter's lab called directly.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Policy evaluate tool", definition: "An admin-console feature (and its plain REST backing, POST .../authz/resource-server/policy/evaluate) that simulates a specific user/client against a resource server's live resources, scopes, and policies and returns the PERMIT/DENY result with full per-policy reasoning — without issuing any real token or ticket. Useful for debugging a permission before wiring up a real client.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Owner-managed access (Keycloak)", definition: "A per-resource toggle (ownerManagedAccess) that lets the actual resource owner — a specific user, not just a realm admin — manage who else can access their own resource via Keycloak's Account Console. The closest built-in approximation to UMA's full \"resource owner in the loop\" workflow; this chapter's lab left it off (false) and used an admin-managed role policy instead.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Aggregated policy", definition: "A Keycloak policy type that nests several child policies and applies its own decision strategy to combine their votes into one reusable, named policy — distinct from setting a decision strategy directly on a permission, since an aggregated policy can be reused across many different permissions as a single unit.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Script policy removal (Keycloak 26.x)", definition: "Keycloak's JavaScript-based (\"script\") authorization policy type, present in older versions, is fully absent from the REST API in 26.8.2 — live-verified two ways: the policy-provider list (GET .../policy/providers) never lists a js/script type, and a direct POST to the legacy .../policy/js endpoint returns a flat 404 Resource not found, not a feature-flag rejection. Older tutorials describing a JavaScript policy tab describe a removed capability, not a hidden one.", category: "Authorization Services (Keycloak)", chapters: ["keycloak-authorization-services"] },
  { term: "Open Policy Agent (OPA)", definition: "A general-purpose, open-source policy engine (not ReBAC-specific, though relationship logic can be expressed in it) that evaluates policies written in Rego against JSON input and returns a decision. A CNCF Graduated project since January 29, 2021, typically deployed as a sidecar process or embedded library, decoupled from any single calling application. Check github.com/open-policy-agent/opa/releases for the current release rather than trusting a number written down here, since it will already be stale. One of two dedicated policy engines chapter 38 contrasts with Keycloak's own Authorization Services (chapter 37).", category: "Authorization models", chapters: ["fine-grained-access-patterns"] },
  { term: "Rego", definition: "The declarative, Datalog-flavored query language Open Policy Agent (OPA) policies are written in, purpose-built for expressing rules over nested JSON documents rather than reading like a general-purpose programming language.", category: "Authorization models", chapters: ["fine-grained-access-patterns"] },
  { term: "Cedar (policy language)", definition: "An authorization policy language and evaluation engine originally built by AWS and open-sourced under the Apache License 2.0 in May 2023, designed alongside a formal model so policy properties (e.g. \"this policy can never grant more than intended\") can be proven, not just tested. Powers Amazon Verified Permissions, AWS's managed authorization service, but is usable standalone with no AWS dependency. Its version numbering is genuinely ambiguous across sources — the Cedar language specification version and the cedar-policy SDK/crate version are tracked separately but both get called \"version 4\"; this course could not fully reconcile the two from public sources and says so rather than asserting one.", category: "Authorization models", chapters: ["fine-grained-access-patterns"] },
  { term: "Zanzibar model (relationship-tuple authorization)", definition: "The relationship-based authorization model described in Google's 2019 paper \"Zanzibar: Google's Consistent, Global Authorization System,\" which stores authorization data as tuples (object#relation@subject, e.g. branch:downtown#manager@user:alex) and supports relationships defined in terms of other relationships, so multi-hop checks (e.g. \"can approve transactions on an account\" defined via \"is manager of the branch that owns it\") are native queries rather than application-side logic. OpenFGA is the most widely used open-source implementation of this pattern — this course verified it is an active, Zanzibar-derived project but did not independently pin down its exact current CNCF maturity level or release version, and flags that as unverified-to-precision rather than asserting a specific designation.", category: "Authorization models", chapters: ["fine-grained-access-patterns", "case-study-meridian"] },

  { term: "SPI (Service Provider Interface) — general pattern", definition: "Keycloak's general extensibility mechanism, instantiated three different ways in chapter 39 (Authenticator, Event Listener, Protocol Mapper) and once already in chapter 33 (User Storage): a Factory interface, discovered exactly once at server boot via Java's standard ServiceLoader mechanism (a META-INF/services text file naming the factory's fully qualified class name), which then produces Provider instances on demand. Chapter 33's own \"User Storage SPI\" entry explains this same shape in that SPI's specific context; this entry generalizes it across every Keycloak SPI, not just that one.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Provider discovery (/opt/keycloak/providers)", definition: "The directory Keycloak scans for third-party provider JARs at build/start time (via kc.sh build, or automatically under start-dev). A JAR placed here is picked up only if it also carries a correctly named/contented META-INF/services registration file for the SPI it implements — get either the directory or the registration file wrong and the provider is silently absent, with no error naming why.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Authenticator factory", definition: "The class discovered once, at server boot, implementing AuthenticatorFactory — distinct from the Authenticator instance it hands back per authentication attempt via create(KeycloakSession). Also implements ConfigurableAuthenticatorFactory, which is what makes an authenticator admin-configurable (getConfigProperties(), isConfigurable(), getRequirementChoices()) rather than a fixed, unconfigurable REQUIRED/DISABLED toggle.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "ConfigurableAuthenticatorFactory", definition: "The interface an AuthenticatorFactory also implements to expose itself as configurable in the Authentication flow editor: getDisplayType(), getReferenceCategory(), isConfigurable(), getRequirementChoices() (which Requirement values — REQUIRED, ALTERNATIVE, CONDITIONAL, DISABLED — an admin may choose for this execution), and getConfigProperties() (the admin-facing config form fields). Meridian Trust's business-hours authenticator exposes exactly two config properties this way: startHourUtc and endHourUtc.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Authenticator lifecycle methods", definition: "The Authenticator interface's five required methods: authenticate() (the main check), action() (handles a form submission — never invoked for an authenticator that shows no form, confirmed in chapter 39's own lab), requiresUser() (whether a UserModel must already be resolved before this authenticator runs), configuredFor() (whether this user has already set up whatever credential this authenticator checks), and setRequiredActions() (attach a required action if setup is missing). Meridian Trust's business-hours gate returns false from requiresUser() because its decision depends only on the wall clock, never on which user is logging in.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Authenticator execution config (AuthenticatorConfigModel)", definition: "Per-execution configuration data, distinct from both the realm-wide SPI provider config (Config.Scope, set once at boot) and from a client's own config: the same Authenticator class can be added to a flow multiple times, each with its own AuthenticatorConfigModel, retrieved in authenticate() via context.getAuthenticatorConfig(). Confirmed live in chapter 39's lab: the identical meridian-business-hours authenticator produced opposite real outcomes (one real HTTP 403, one real HTTP 200) purely by changing this one execution's config, with the real server clock held constant throughout.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "AuthenticationFlowError", definition: "An enum (org.keycloak.authentication.AuthenticationFlowError) an Authenticator passes to context.failure()/context.failureChallenge() to tell the framework why it is failing — ACCESS_DENIED, INVALID_CREDENTIALS, USER_TEMPORARILY_DISABLED, and others. A real, live-confirmed gotcha from chapter 39's own lab: the single-argument context.failure(AuthenticationFlowError) overload correctly tags the resulting LOGIN_ERROR event but then threw an uncaught AuthenticationFlowException on the Direct Grant code path specifically, surfacing to the client as a bare HTTP 500 rather than a clean OAuth error — fixed by always supplying an explicit challenge Response via the two-argument context.failure(AuthenticationFlowError, Response) overload instead.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Protocol Mapper SPI", definition: "The Java interface (org.keycloak.protocol.ProtocolMapper, plus its OIDC-specific subinterfaces OIDCAccessTokenMapper/OIDCIDTokenMapper/UserInfoTokenMapper) you implement to create a genuinely new kind of claim-injection logic — distinct from \"Protocol mapper\" (chapter 24), which is the admin-configured instance of an already-existing mapper type attached to a client scope. Northwind Apps' tenant_id mapper is a new Protocol Mapper SPI implementation; chapter 24's hardcoded-claim and user-attribute mappers are built-in Protocol Mapper SPI implementations an admin merely configures, not writes.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "OIDCAttributeMapperHelper (shared claim-injection helper)", definition: "A static helper class (org.keycloak.protocol.oidc.mappers.OIDCAttributeMapperHelper) both Keycloak's own built-in OIDC mappers and a custom ProtocolMapper implementation call into to actually place a computed value into a token at the configured claim.name path, honoring the same id.token.claim/access.token.claim/userinfo.token.claim/introspection.token.claim config flags chapter 24 already covers — confirmed live: a custom mapper gets the exact same config-flag behavior as a built-in one for free by calling this helper, rather than reimplementing claim placement.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "OIDC token-transform hooks (access/ID/UserInfo)", definition: "The three methods a Protocol Mapper SPI implementation overrides to affect a given token type: transformAccessToken() (OIDCAccessTokenMapper), transformIDToken() (OIDCIDTokenMapper), and transformUserInfoToken() (UserInfoTokenMapper) — three separate interfaces a single mapper class can implement all at once. Confirmed live in chapter 39's lab: implementing all three let Northwind's tenant_id claim appear, independently verified by decoding a real access token and ID token and calling the real /userinfo endpoint, in all three places from one shared helper method.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Dual event dispatch (EventListenerProvider)", definition: "EventListenerProvider declares two onEvent() overloads — onEvent(Event) for ordinary login/user events, and onEvent(AdminEvent, boolean) for administrative actions (chapter 28's \"Admin event\") — a single provider class handles both streams, and may legitimately implement only one as a no-op, as chapter 39's Riverside Health listener deliberately does for admin events (out of this chapter's scope).", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Lightweight access token", definition: "A Keycloak access-token mode (client setting \"Always use lightweight access token\", enabled by default on the admin-cli client) that omits most user-profile claims from the access token itself to keep it small. A real, live-confirmed gotcha from chapter 39's lab: calling the /userinfo endpoint with a lightweight access token returns HTTP 401 with error_description \"Lightweight access token not allowed for userinfo endpoint\" — fixed by disabling the setting on the client under test, not by changing anything about the protocol mapper itself.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Internal SPI warning (KC-SERVICES0047)", definition: "A WARN-level message Keycloak 26.8.2 prints at build/boot time for every third-party provider factory implementing the Authenticator, Event Listener, or Protocol Mapper SPIs: \"<id> (<class>) is implementing the internal SPI <name>. This SPI is internal and may change without notice.\" Confirmed live during chapter 39's own kc.sh build, and independently confirmed against Keycloak's own Server Developer Guide, whose Authentication SPI and Event Listener SPI sections both carry the identical disclaimer in prose — unlike chapter 33's User Storage SPI, which the guide does not flag this way.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Stale bind-mounted provider JAR (post-mvn-clean)", definition: "A real Docker gotcha, distinct from chapter 33's \"bind-mounted JAR becomes an empty directory\" failure: if a provider JAR is rebuilt (mvn clean package) while its container is already running with that file bind-mounted, the running container keeps serving the old file's content even after the host-side file is replaced — confirmed live in chapter 39's lab by comparing file size/timestamp on both sides after a rebuild. A plain docker compose restart is not enough to pick up the change; the container must be recreated (docker compose up -d --force-recreate <service>) so the bind mount re-resolves against the current host file.", category: "Keycloak Core", chapters: ["custom-spis"] },
  { term: "Factory/Provider collapse (Protocol Mapper SPI)", definition: "A real structural asymmetry confirmed directly from the real interface: unlike Authenticator and EventListenerProvider, which each need a separate Factory class (discovered once at boot) and Provider/instance class (created per use), ProtocolMapper extends ProviderFactory<ProtocolMapper> itself, and AbstractOIDCProtocolMapper.create() simply returns this — collapsing Factory and Provider into one class, because a protocol mapper is cheap and stateless enough that Keycloak's own SPI design doesn't need the split. Not a shortcut chapter 39's lab took; confirmed by inspecting the real method on the real 26.8.2 jar before writing the class.", category: "Keycloak Core", chapters: ["custom-spis"] },

  { term: "Identity Provider SPI (custom)", definition: "Keycloak's Service Provider Interface for registering a brand-new broker type Keycloak has no built-in implementation for (contrast with configuring an instance of an existing built-in type, chapter 31's \"Identity Provider instance (Keycloak resource)\"). Implemented via IdentityProvider/IdentityProviderFactory (and typically AbstractIdentityProvider/AbstractIdentityProviderFactory), confirmed live for Keycloak 26.8.2 to live in org.keycloak:keycloak-server-spi-private, not keycloak-server-spi alone. Chapter 40 writes one from scratch to broker a toy legacy protocol no built-in broker understands.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Required Action SPI (custom)", definition: "Keycloak's Service Provider Interface for registering a brand-new required action Keycloak has no built-in implementation of, implemented via RequiredActionProvider/RequiredActionFactory (confirmed live for 26.8.2 in org.keycloak:keycloak-server-spi-private, the same artifact as the Identity Provider SPI despite being an unrelated SPI family). Distinct from the Authenticator SPI (chapter 39): a required action runs only after a credential has already verified and can only add a mandatory step, never cause a correct credential to fail.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "AbstractIdentityProvider (Keycloak)", definition: "The abstract base class most custom Identity Providers extend directly, implementing UserAuthenticationIdentityProvider's shared plumbing. Confirmed by decompiling its real bytecode: performLogin() and callback() both return null by default (a subclass must override both), getMarshaller() already has a sane default (DefaultDataMarshaller), and retrieveToken() is left fully abstract. Distinct from AbstractOAuth2IdentityProvider (in the much heavier keycloak-services artifact), which every built-in OAuth2/OIDC/social broker extends instead but which bakes in OAuth2-specific assumptions a non-OAuth2 toy protocol doesn't need.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "BrokeredIdentityContext", definition: "The object a custom Identity Provider's callback logic builds to hand Keycloak the asserted external identity (id, username, email, first/last name, the IdP config it came from) before Keycloak's own First Broker Login logic decides whether to link an existing local account or just-in-time provision a new one. Passed to AuthenticationCallback.authenticated(context), which is what actually lets the broker flow proceed.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Resource locator pattern (broker callback)", definition: "The JAX-RS pattern a custom Identity Provider's callback(RealmModel, AuthenticationCallback, EventBuilder) method uses: instead of returning a Response directly, it returns a small plain object (a static nested Endpoint class) annotated with its own @GET/@Path methods, which JAX-RS then dispatches the actual HTTP request to as a sub-resource. The same pattern Keycloak's own built-in OIDC/OAuth2 broker implementations use for their own callback endpoints.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Redirect-out/callback-in (custom broker pattern)", definition: "The general shape every Identity Provider broker needs, custom or built-in: performLogin() redirects the browser out to the external system carrying Keycloak's own broker-endpoint redirect_uri and an opaque state value; the external system authenticates the user entirely itself; it then redirects the browser back in to that exact URL, and the provider's callback logic verifies (never simply trusts) whatever comes back before letting Keycloak's own First Broker Login logic run.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Callback signature verification (custom broker)", definition: "The custom-protocol equivalent of validating a SAML assertion's XML signature (chapter 17) or an OIDC ID token's JWS signature (chapter 16): a custom Identity Provider's callback endpoint must cryptographically verify that the fields on an external system's redirect-in actually originated from that trusted system, rather than merely accepting whatever query parameters arrive at the predictable, publicly knowable broker-endpoint URL shape (chapter 31's \"Broker endpoint URI\"). Chapter 40's lab used an HMAC-SHA256 signature over the callback's fields, keyed with a secret shared out-of-band, verified with a constant-time comparison (java.security.MessageDigest.isEqual) rather than a plain string-equality check, to avoid a timing side-channel.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Clock-skew tolerance (broker callback replay window)", definition: "A deliberately bounded window (chapter 40's lab used 300 seconds) within which a signed external-IdP callback's own timestamp must fall for a custom Identity Provider to accept it, rejecting anything older as a stale or replayed callback. The same general defense-in-depth idea chapter 21's realm clock-skew setting and chapter 16's JWT exp/iat claims apply elsewhere, reapplied here for a callback that has no token-revocation mechanism of its own to fall back on.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Unregistered required action", definition: "The state every custom Required Action starts in on every realm, confirmed live via GET /admin/realms/{realm}/authentication/unregistered-required-actions: the provider jar is deployed and discovered server-wide, but it is not yet usable on any specific realm. Distinct from a custom Identity Provider, which is immediately selectable in a realm's \"Add provider\" picker the moment its jar is deployed — the Required Action SPI has a per-realm enable switch the Identity Provider SPI simply has no equivalent of.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "register-required-action (Admin REST endpoint)", definition: "POST /admin/realms/{realm}/authentication/register-required-action, the call that moves a custom required action out of that realm's unregistered-required-actions list and into its ordinary required-actions list (enabled, with a default priority), confirmed live in chapter 40's lab. Assigning the action's provider id to a user's requiredActions list has no effect at login until this registration step has run on that specific realm.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "requiredActionChallenge() / processAction()", definition: "The two methods a custom RequiredActionProvider implements: requiredActionChallenge(context) builds and hands context.challenge(...) the HTTP response shown to the user (typically context.form().createForm(\"some.ftl\")); processAction(context) reads the submitted form data back (context.getHttpRequest().getDecodedFormParameters()) and calls either context.success() (the queued login proceeds) or context.failure(...) (the whole login attempt ends). Modeled directly, in chapter 40, on Keycloak's own built-in TermsAndConditions required action's real bytecode.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Required action failure message code", definition: "The string argument passed to RequiredActionContext.failure(messageCode) — a realm message-bundle key, not display text. If no theme-resources/messages/ entry defines that key, Keycloak renders its generic \"An error occurred, please login again through your application\" error page instead of anything action-specific; the session still correctly ends either way. Confirmed live in chapter 40's lab by declining the HIPAA acknowledgment and reading the resulting (generically worded) error page.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Provider provenance attribute (JIT-provisioned user)", definition: "A custom attribute an Identity Provider's importNewUser()/updateBrokeredUser() override sets on a newly JIT-provisioned local user to record which external system it originated from (chapter 40's lab used legacySource=\"cascade-sso\"), letting an auditor later distinguish a brokered-in identity from a natively created one (chapter 11's compliance concerns, made concrete). Subject to the same Declarative User Profile unmanagedAttributePolicy gotcha chapter 33 already documented for a different SPI family — the attribute is silently dropped unless the realm's user profile has unmanagedAttributePolicy set to ENABLED.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },
  { term: "Cascade SSO (toy protocol)", definition: "A deliberately minimal, invented-for-this-course redirect-and-signed-callback protocol used as chapter 40's lab stand-in for an acquired institution's legacy, proprietary SSO system (the fictional Cascade Savings Bank, acquired by Meridian Trust) — explicitly NOT a real named vendor product. Exists only so the chapter's custom Identity Provider SPI has a real, working external system to redirect to and receive a real signed callback from.", category: "Keycloak Core", chapters: ["custom-idp-and-required-actions"] },

  { term: "JGroups", definition: "The group-communication toolkit underneath Infinispan's clustering, responsible for node discovery and message delivery between cluster members. Distinct from Infinispan itself: JGroups handles \"who else is out there and how do I talk to them,\" while Infinispan is the cache/data-grid layer built on top that actually stores and replicates Keycloak's in-memory data. Confirmed live in chapter 41's lab boot log, which names the JGroups channel \"ISPN\" and its discovery stack \"jdbc-ping\" explicitly.", category: "Keycloak Architecture", chapters: ["high-availability-clustering"] },
  { term: "Cache stack (--cache-stack)", definition: "The Keycloak server option selecting which JGroups discovery mechanism an embedded Infinispan cluster uses. Confirmed live against the real Keycloak 26.8.2 start --help-all output: its documented default is jdbc-ping, with kubernetes, jdbc-ping-udp, tcp, udp, ec2, azure, and google all explicitly marked deprecated — a materially different picture from older Keycloak-version guidance that recommended a static TCPPING host list or UDP multicast.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "JDBC_PING (discovery protocol)", definition: "The JGroups discovery protocol Keycloak 26.8.2 defaults to for a non-Kubernetes deployment: cluster members discover each other by writing and reading their own physical address in a small table inside the same database Keycloak already connects to for everything else, rather than via a hand-maintained static host list or network multicast. Confirmed live in chapter 41's lab boot log (\"JGroups JDBC_PING discovery enabled\"), and the mechanism this chapter's two-node cluster actually used to find each other with zero extra configuration beyond the shared database connection string both nodes already needed.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "Cache mode: ispn vs. local (--cache)", definition: "The Keycloak server option that decides whether clustering is even attempted. Confirmed live from the real 26.8.2 help text: ispn is production mode's default and clusters nodes together over JGroups/Infinispan; local is start-dev's own default and disables clustering outright, silently giving every node its own isolated, non-clustered cache with no warning. Chapter 41's lab had to explicitly override start-dev's local default with --cache=ispn — without that override, its entire two-node premise would have been a silent no-op.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "Cluster view (JGroups/Infinispan)", definition: "The agreed-upon list of currently known member nodes a JGroups channel reports once discovery succeeds, logged by Keycloak as \"Received new cluster view for channel ISPN: [...]\". Confirmed live in chapter 41's lab as the first sign two nodes found each other — but, as the chapter's own lab discovered the hard way, a healthy cluster view only proves the transport layer sees both members; it does not by itself prove application-level session data actually replicates usably, which needed a separate, decisive cross-node test.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "Cache rebalance (Infinispan)", definition: "The state-transfer operation Infinispan runs automatically whenever cluster membership changes (a node joins or leaves), redistributing/copying each distributed cache's entries so every current member holds the data it's supposed to. Confirmed live in chapter 41's lab logs immediately after the two-node cluster view formed: separate rebalance operations ran for the sessions, clientSessions, offlineSessions, offlineClientSessions, authenticationSessions, actionTokens, and work caches specifically — directly confirming, from the real log output rather than from documentation alone, which caches are actually distributed.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "Local cache vs. distributed cache (Keycloak's embedded Infinispan)", definition: "A real split confirmed directly from Keycloak 26.8.2's own start --help-all output: per-cache size options for sessions, clientSessions, offlineSessions, and offlineClientSessions are explicitly annotated \"available only when embedded Infinispan clusters configured\" (i.e. genuinely distributed/replicated across nodes), while the equivalent options for realms, users, keys, authorization, and crl carry no such annotation (local caches, present on every node regardless of clustering, kept fresh via cross-node invalidation messages and a database fallback rather than full replication). Chapter 41's lab log independently confirmed the same split: only the session-family caches (plus authenticationSessions/actionTokens/work) appeared in the post-cluster-formation rebalance log.", category: "Keycloak Architecture", chapters: ["high-availability-clustering"] },
  { term: "JGroups mTLS (--cache-embedded-mtls-enabled)", definition: "Encryption of the network traffic between embedded Infinispan/JGroups cluster nodes, enabled by default (true) whenever a TCP-based cache stack is used — which jdbc-ping is. With no keystore/truststore configured, Keycloak automatically generates and rotates ephemeral certificates (default rotation: 30 days). Confirmed live in chapter 41's lab boot log, unprompted: \"JGroups Encryption enabled (mTLS)\" appeared with zero extra configuration on either node.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "--cache-embedded-node-name", definition: "The Keycloak server option naming a specific cluster member for log messages and management tooling (e.g. node-a, node-b). Used directly in chapter 41's lab to make its own cluster-formation logs and rebalance output unambiguous about which physical container was which cluster member, rather than relying on auto-generated UUID-style names.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "Token issuer mismatch across cluster nodes (KC_HOSTNAME)", definition: "A real, reproducible bug chapter 41's lab hit on its first cross-node test: Keycloak derives a token's iss (issuer) claim from the request's own Host header by default, so two nodes reached on two different host:port combinations compute two different issuers — a token minted via one is then rejected by the other with invalid_grant / \"Invalid token issuer.\" Not a clustering or cache-replication bug at all; fixed by forcing an identical KC_HOSTNAME on every node, which is what a real deployment achieves structurally by putting every node behind one load balancer with one public hostname.", category: "Keycloak Operations", chapters: ["high-availability-clustering"] },
  { term: "Sticky session vs. replicated session", definition: "Two different strategies for making multi-node session handling work, worth distinguishing explicitly. A sticky session relies on a load balancer consistently routing the same client back to the same backend node (by cookie or source IP), so that node's own local, non-replicated session state is always the one that's asked for it — fragile the moment that one node goes away. A replicated session (what chapter 41's embedded-Infinispan cluster actually does, and what its lab proves end to end) makes the session itself visible to every node, so a load balancer can route a request to any node without caring which one originally created the session. Keycloak's own architecture is built around the replicated-session model, not sticky routing, though a reverse proxy/load balancer may still use session affinity for other reasons (e.g. minimizing cross-node cache lookups) without that affinity being load-bearing for correctness.", category: "Keycloak Architecture", chapters: ["high-availability-clustering"] },
  { term: "Split-brain (cluster partition)", definition: "The scenario where a network partition causes a cluster's members to split into two or more groups that can each still see their own members but not the other group, each potentially believing it is the sole surviving cluster. Named explicitly in chapter 41 as something its own lab does NOT test or prove anything about: both of that lab's \"nodes\" are containers sharing one Docker host, one kernel, and one bridge network, which cannot actually partition the way a real multi-host network can — demonstrating split-brain behavior honestly would require genuinely separate hosts. Chapter 44 cites Keycloak's own multi-cluster v2 documentation naming this exact failure mode at the multi-site scope: without active load-balancer health probing, \"site failures are not detected automatically, and traffic continues to be routed to a failed site or split-brain partitions until manual intervention.\"", category: "Keycloak Architecture", chapters: ["high-availability-clustering", "backup-and-disaster-recovery"] },
  { term: "Single-cluster HA vs. multi-site HA", definition: "Keycloak's own documented distinction (per its High Availability Guide) between resilience within one cluster/site (multiple nodes behind one load balancer sharing one database and one embedded-Infinispan cluster — chapter 41's subject) and resilience across multiple data centers/regions (replicating state between genuinely separate sites, with its own harder consistency and latency trade-offs — chapter 44's subject). Chapter 41 deliberately scopes itself to the first and names the second explicitly as a different, later chapter's territory rather than conflating the two.", category: "Keycloak Architecture", chapters: ["high-availability-clustering", "backup-and-disaster-recovery"] },

  { term: "Operator pattern (Kubernetes)", definition: "An ordinary controller program paired with one or more Custom Resource Definitions that extends the Kubernetes API with a new resource type and then continuously reconciles the real cluster toward whatever that resource's spec currently declares — the same 'declare desired state, let a controller enforce it' idea every built-in Kubernetes controller already uses, applied to an application (here, Keycloak) Kubernetes never shipped with.", category: "Keycloak Operations", chapters: ["keycloak-on-kubernetes"] },
  { term: "Custom Resource Definition (CRD)", definition: "A Kubernetes API extension that registers a brand-new resource type (e.g. Keycloak, KeycloakRealmImport) with the cluster's API server, so clients like kubectl can create, read, and update instances of it exactly like a built-in type such as Pod or Service. The Keycloak Operator installs four: Keycloak, KeycloakRealmImport, KeycloakOIDCClient, and KeycloakSAMLClient.", category: "Lab infrastructure", chapters: ["keycloak-on-kubernetes"] },
  { term: "Keycloak custom resource (Keycloak CR)", definition: "A YAML object of kind Keycloak (apiVersion k8s.keycloak.org/v2beta1) that declares the desired state of a Keycloak deployment — instance count, database connection, TLS, hostname, Ingress — which the Keycloak Operator reconciles into an actual StatefulSet, Services, and Secrets. Functionally the Kubernetes-native replacement for a docker-compose.yml service definition.", category: "Keycloak Operations", chapters: ["keycloak-on-kubernetes"] },
  { term: "Reconciliation loop", definition: "The continuous cycle an Operator's controller runs: watch for a custom resource being created or changed, compare the cluster's actual state to that resource's declared desired state, and take action (create/update/delete other objects) to close the gap — then repeat, rather than running once at apply time.", category: "Keycloak Operations", chapters: ["keycloak-on-kubernetes"] },
  { term: "kind (Kubernetes in Docker)", definition: "A tool that runs an entire single- or multi-node Kubernetes cluster as Docker container(s), each acting as one Kubernetes node with its own internal containerd image store separate from the host Docker engine's. Used in this course in place of minikube (not installed on the build machine) to stand up a real, disposable cluster for chapter 42's lab.", category: "Lab infrastructure", chapters: ["keycloak-on-kubernetes"] },
  { term: "Helm chart", definition: "A packaged, templated bundle of Kubernetes manifests, installed and upgraded as one unit via the helm CLI. The Keycloak project ships its own chart for the Operator itself labeled 'Experimental'; a long-popular third-party alternative, the Bitnami Keycloak chart, had its free container images moved to a legacy/paid repository around August 2025 and is no longer a safe default for new deployments as of this chapter's live-verification.", category: "Lab infrastructure", chapters: ["keycloak-on-kubernetes"] },
  { term: "Operator Lifecycle Manager (OLM)", definition: "A Kubernetes component for installing, upgrading, and managing the lifecycle of Operators themselves, via Subscription and InstallPlan objects. Keycloak's own documentation calls OLM the 'recommended' way to install the Keycloak Operator, but it requires OLM already running in the cluster — this course's kind lab used the simpler, equally official plain-kubectl/kustomize path instead, since OLM is an unnecessary extra component for a one-off teaching cluster.", category: "Lab infrastructure", chapters: ["keycloak-on-kubernetes"] },
  { term: "StatefulSet", definition: "A Kubernetes workload controller for stateful applications, giving each replica a stable, unique network identity and (optionally) its own persistent storage across restarts — unlike a Deployment, where replica pods are interchangeable. The Keycloak Operator creates a StatefulSet (not a Deployment) to run Keycloak's own pods, and this chapter's ephemeral dev Postgres is also a StatefulSet.", category: "Lab infrastructure", chapters: ["keycloak-on-kubernetes"] },
  { term: "kubectl port-forward", definition: "A kubectl subcommand that opens a direct, temporary TCP tunnel from a local port to a port on a Kubernetes Pod or Service, without needing an Ingress, a LoadBalancer, or any DNS. The Keycloak Operator's own documentation names this as the way to reach a deployment 'for debugging and development purposes' — used in chapter 42's lab to reach the Keycloak admin console and token endpoint from outside a kind cluster that has no Ingress controller.", category: "Lab infrastructure", chapters: ["keycloak-on-kubernetes"] },
  { term: "Ingress (Kubernetes)", definition: "A Kubernetes API object that describes HTTP(S) routing rules from outside a cluster to Services inside it, actually enforced by a separately installed Ingress controller (e.g. ingress-nginx) — an Ingress object with no controller running simply never gets an address. A stock kind cluster ships no Ingress controller by default, which is why chapter 42's lab set ingress.enabled: false on the Keycloak CR and used kubectl port-forward instead.", category: "Lab infrastructure", chapters: ["keycloak-on-kubernetes"] },
  { term: "Operator-issued initial-admin Secret", definition: "The Keycloak Operator's bootstrap-credentials mechanism: instead of a persistent admin account from fixed environment variables (as in chapter 20's Docker Compose install), the Operator creates a one-time temporary admin user (confirmed live: username temp-admin) and writes its random password into a generated Kubernetes Secret named <cr-name>-initial-admin, read via kubectl get secret ... -o jsonpath.", category: "Keycloak Operations", chapters: ["keycloak-on-kubernetes"] },
  { term: "Namespace-scoped vs. cluster-wide Operator install", definition: "The Keycloak Operator's two install modes: namespace-scoped (the default; the Operator watches Keycloak CRs only in its own namespace) and cluster-wide (reconciles CRs in every namespace, but as of this chapter's live-verification is still labeled a preview feature, supports only one Keycloak version per Operator instance, and ignores spec.podTemplate.spec.serviceAccountName). Chapter 42's lab used the namespace-scoped default.", category: "Keycloak Operations", chapters: ["keycloak-on-kubernetes"] },

  { term: "Agroal (connection pool)", definition: "The JDBC connection pool implementation built into Quarkus, and — confirmed directly from Keycloak's own observability documentation, which names the metrics agroal_active_count, agroal_available_count, and agroal_awaiting_count — the actual connection pool technology underneath Keycloak's Quarkus distribution. Keycloak's own database guide never names it in prose (it only documents the db-pool-* option names), so the metric names are the most authoritative confirmation available that this is Agroal rather than HikariCP or another pool library.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Fixed-size connection pool (db-pool-initial/min/max equal)", definition: "Keycloak's own High Availability guide's specific recommendation for sizing the database connection pool: set db-pool-initial-size, db-pool-min-size, and db-pool-max-size to the same value, rather than leaving initial/min low to save resources when idle. Two reasons back it: opening a new database connection mid-request is slow, so a pool that creates connections on demand pays that cost during a real traffic spike (a \"stampede\" effect if many connections are needed at once); and keeping a connection open preserves server-side statement caching, which a pool that keeps closing/reopening connections under light load throws away repeatedly.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "db-pool-max-lifetime", definition: "The Keycloak connection-pool option controlling how long a pooled database connection stays open before being forcibly recycled. For MySQL and MariaDB, Keycloak defaults this to 7 hours 50 minutes specifically because those databases' own default wait_timeout is 8 hours — the pool must recycle a connection before the database server itself silently closes it, or the pool starts handing out dead connections that fail with \"No operations allowed after connection closed.\" If an organization lowers its own wait_timeout, it must lower db-pool-max-lifetime to stay below it, or this exact failure reappears.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Connection pool exhaustion (agroal_awaiting_count)", definition: "The condition where every connection in Keycloak's Agroal pool is in active use and additional requests must wait, surfaced directly by the agroal_awaiting_count metric (threads waiting for a database connection to become available) in Keycloak's own observability guide. The instinctive fix — raise db-pool-max-size — isn't always correct: Keycloak's own guidance warns a larger pool can simply push the real bottleneck onto the database itself, and recommends checking whether http-pool-max-threads (the HTTP worker thread count) is set higher than the database can actually support before growing the pool further.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "http-pool-max-threads", definition: "The Quarkus/Keycloak option controlling the number of concurrent HTTP worker threads. Keycloak's own observability guide recommends reducing this value to match the number of available database connections rather than leaving it high and growing the database connection pool to compensate — fewer, well-matched worker threads reduce contention and resource usage at the source, instead of just moving a bottleneck from the HTTP layer onto the database.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Server-side statement caching", definition: "A database optimization where a query sent repeatedly over the same open connection gets promoted to a cached, pre-parsed execution plan instead of being re-parsed every time — PostgreSQL, for example, promotes a query to a server-side prepared statement only after it runs (by default) at least five times on the same connection. Closing and reopening a database connection discards this cache for that connection entirely, which is one of the two reasons Keycloak's own High Availability guide recommends a fixed-size connection pool (initial = min = max) rather than one that opens and closes connections on demand.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "targetServerType=primary (writer/reader instance targeting)", definition: "A JDBC driver property Keycloak sets to primary by default when connecting to PostgreSQL or Amazon Aurora PostgreSQL, ensuring it always connects to the writable primary/writer instance and never to a secondary reader instance during a failover or switchover. Exists because Keycloak's own reads and writes (e.g. reading whether a session exists, then immediately updating it within one login) are tightly coupled within a single transaction boundary — a reader instance lagging the writer by even a small amount could serve stale or missing data mid-login. Can be overridden for additional (non-primary) datasources, where the same constraint may not apply.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Asynchronous commit (PostgreSQL, Keycloak)", definition: "A PostgreSQL optimization (synchronous_commit = off) that Keycloak enables by default for transactions touching only ephemeral tables — persisted user sessions, client sessions, and events — trading a small window of durability risk on a server crash for lower write latency on exactly the high-volume, comparatively low-stakes writes that session/event traffic generates. Logouts are deliberately excluded and still force a synchronous commit, because losing a logout record has real security consequences. Can be disabled entirely with --spi-connections-jpa--quarkus--async-commit=false if an organization's durability requirements demand it.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Stateless mode (Keycloak feature)", definition: "An optional Keycloak feature (--features=stateless, off by default; promoted from preview to fully supported in Keycloak 26.8.0) that moves volatile data — authentication sessions, action tokens, brute-force login-failure counters — out of Infinispan caches and into the database instead. Eliminates the need for an external, cross-site-replicated Infinispan cluster (chapter 41's subject) at a documented, concrete cost: roughly 8-10ms of added latency per authentication interaction, and database CPU/IOPS load roughly doubling, because state that used to be a memory lookup becomes a database round trip on every request. For multi-site use it additionally requires a synchronously replicated database with sub-10ms inter-site latency, which rules it out across genuinely separate geographic regions. A real, sized trade-off, not a drop-in upgrade.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Vertical vs. horizontal scaling (Keycloak context)", definition: "Two different responses to a Keycloak deployment running out of capacity: vertical scaling gives existing nodes more CPU/memory, while horizontal scaling adds more nodes. Keycloak's own Getting Started guide states a preference for vertical scaling specifically when the underlying problem is memory pressure — \"adjusting the memory request and limit is preferable to horizontal scaling\" — because adding nodes doesn't fix an individually undersized node; each new node inherits the same sizing mistake. Horizontal scaling remains the right response to raw throughput limits once each node is already correctly sized.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Heap-dump-driven JVM sizing", definition: "Keycloak's own stated approach to resizing JVM heap under memory pressure: take a heap dump and determine what is actually contributing to increased memory use before changing any heap flag, rather than guessing at a larger number. Pairs with the general heap-sizing trade-off: a heap set too small forces garbage collection to run more often (frequent, shorter pauses); a heap set too large lengthens individual GC pauses — the correct size sits between the two and is found by measuring real load, not estimated in advance.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "G1GC tuning flags (Keycloak/Quarkus)", definition: "The specific, narrow set of JVM garbage-collection flags named in Keycloak's own benchmark/tuning guidance: -XX:+UseG1GC (enable the G1 collector), -XX:MaxGCPauseMillis (target maximum GC pause time), and -Xlog:gc:file=<path> (write GC activity to a log for analysis), alongside heap-sizing flags (-XX:MaxRAMPercentage for containers, -Xms/-Xmx for fixed hosts). Keycloak's own guidance does not state a universal default GC algorithm or specific pause-time target for 26.8.2 — treat any claim about what's \"already the default\" as something to verify against the running server (jcmd 1 VM.flags) rather than assumed.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Generated invisible primary keys (MySQL 8.0.30+ migration gotcha)", definition: "A MySQL 8.0.30+ server feature (sql_generate_invisible_primary_key) that auto-generates a primary key for any InnoDB table created without one — which collides directly with Keycloak's own schema initialization and causes migrations to fail with a \"Multiple primary key defined (1068)\" error. Must be set to OFF at the MySQL server level before installing or upgrading Keycloak on MySQL 8.0.30 or later; not a Keycloak defect when it occurs.", category: "Keycloak Operations", chapters: ["performance-tuning"] },
  { term: "Cache warm-up gap", definition: "The period immediately after a Keycloak node restarts (or a rolling deploy/failover) during which its local caches (chapter 41's realms/users/keys caches) are empty and have not yet reached steady-state hit ratios, during which the database absorbs load a fully-warmed cache would otherwise have deflected. Keycloak's own High Availability sizing guidance warns explicitly against capacity-planning from steady-state measurements alone — \"do not set resources too tight based on the stable state measured once the caches have been filled\" — since the minutes right after every restart are a distinct, heavier-load regime.", category: "Keycloak Operations", chapters: ["performance-tuning"] },

  { term: "Database backup and restore (Keycloak)", definition: "The actual disaster-recovery mechanism for Keycloak: backing up the underlying relational database directly (pg_dump, continuous WAL archiving, a managed database's snapshot feature) rather than using Keycloak's own export tooling. Covers everything Keycloak persists — realms, clients, users, credentials, roles, groups, sessions, events, and keys — because the database is Keycloak's actual source of truth, unlike realm export/import's narrower scope.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Realm export (Keycloak)", definition: "The kc.sh export CLI command that writes a realm's configuration (and, optionally, its users) to JSON file(s), for moving a realm definition between environments or snapshotting its configuration — not a backup mechanism. Requires the server to be stopped; does not capture user/admin events, persisted sessions, workflow state, or revoked tokens, per Keycloak's own current documentation.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Realm import (Keycloak)", definition: "The kc.sh import CLI command (or the start --import-realm startup-time variant) that loads realm configuration and optional users from JSON file(s) produced by a realm export. The --override flag (default true) controls whether an existing realm of the same name is replaced; importing with override requires every cluster node to be stopped first, since the command does not coordinate with a live Infinispan cache cluster.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Partial export / partial import (Admin Console)", definition: "A browser-driven realm export/import path under a realm's Settings → Action menu, usable while the cluster is online — unlike the CLI export/import, which requires stopping the server. Keycloak's own documentation explicitly states this path is not suitable for backups or server-to-server transfers: it masks passwords and client secrets as \"*\" and cannot include users at all.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Recovery Point Objective (RPO)", definition: "The maximum acceptable amount of data loss, measured as the time gap between the last good backup and the moment of failure — not a Keycloak-specific term, but essential for stating any backup strategy precisely. A nightly backup implies an RPO of up to 24 hours; continuous replication to a standby can shrink it to seconds. Tightening RPO generally means backing up (or replicating) more frequently.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Recovery Time Objective (RTO)", definition: "The maximum acceptable downtime after a failure, measured as the time gap between the failure and the service being usable again — the counterpart to RPO. A manual restore-from-backup procedure might imply an RTO of hours; a warm standby a load balancer can fail over to might shrink it to minutes. Keycloak's own high-availability guides explicitly leave RTO/RPO validation to the deployer rather than publishing a guaranteed number.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Multi-cluster v2 (Keycloak)", definition: "Keycloak's current, recommended multi-site high-availability topology: two or more fully independent Keycloak clusters, each without a shared embedded-Infinispan cluster across sites, coordinated only through a synchronously replicated database and an external load balancer. Stores authentication sessions and tokens in the database rather than relying on cross-site cache replication. Needs no special transparent networking between sites, but roughly doubles database CPU and write IOPS versus a single-site deployment, per Keycloak's own live-verified documentation.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Multi-cluster v1 (Keycloak, deprecated)", definition: "Keycloak's older multi-site topology: two clusters, each running its own embedded-Infinispan cluster, bridged across sites. Keycloak's own documentation states it is deprecated and will be removed in a future release, recommending migration to multi-cluster v2. Still useful context for regulatory scenarios demanding physically distinct deployments, but it requires two full Kubernetes control planes and is not supported across three or more availability zones.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Single-cluster multi-AZ/DC stretch (Keycloak)", definition: "The simplest of Keycloak's three documented multi-site shapes: one Kubernetes/cluster deployment whose own nodes happen to span multiple availability zones or data centers with sufficiently low latency, rather than running as genuinely separate independent clusters. Sessions are stored in the database and authentication sessions in memory, as in any single-cluster deployment — but the shared control plane remains a single point of failure, since a control-plane outage can affect every node across every zone at once.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Synchronous database replication (cross-site)", definition: "The database replication mode every one of Keycloak's documented multi-site topologies requires between sites: a write is not acknowledged as committed until it has also been durably written at the other site(s), as opposed to asynchronous replication, where a committed write might not yet exist elsewhere if a failure happens immediately after. Keycloak's current multi-cluster v2 documentation cites a need for sub-10-millisecond commit latency between sites, which in practice limits this topology to sites close enough geographically (or network-wise) to hit that bound.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Clock skew (cross-site cache invalidation)", definition: "A documented failure mode in Keycloak's multi-cluster v2 topology: clock skew of more than ten seconds between clusters can cause Infinispan cache-invalidation messages not to be delivered correctly, leaving a node's local cache stale relative to the database. Named explicitly in Keycloak's own live-verified multi-cluster v2 guide as a caveat operators must account for (e.g. via NTP) rather than assume away.", category: "Keycloak Operations", chapters: ["backup-and-disaster-recovery"] },
  { term: "Contingency Plan standard (HIPAA, 45 CFR §164.308(a)(7))", definition: "A HIPAA Security Rule administrative-safeguard standard, confirmed directly from the regulation's text, requiring covered entities to establish three Required implementation specifications — a data backup plan (retrievable exact copies of ePHI), a disaster recovery plan (procedures to restore lost data), and an emergency mode operation plan (continuation of critical business processes during an emergency) — plus two Addressable specifications (testing/revision procedures; an applications-and-data criticality analysis). Distinct from the Security Rule's technical safeguards (chapter 11's §164.312 material); this standard is what makes backup/DR planning a compliance requirement rather than an optional ops practice for an organization like Riverside Health.", category: "Compliance & Governance", chapters: ["backup-and-disaster-recovery"] },
  { term: "Emergency mode operation plan (HIPAA)", definition: "One of the three Required implementation specifications under HIPAA's Contingency Plan standard (45 CFR §164.308(a)(7)(ii)(C)): procedures enabling continuation of critical business processes for the protection of ePHI security while an organization operates in emergency mode. For an organization whose workforce authenticates through a central identity system (chapter 1's centralization argument, inverted), that identity system's own availability during an incident is part of what this plan has to account for — not only the clinical or financial data sitting behind it.", category: "Compliance & Governance", chapters: ["backup-and-disaster-recovery"] },

  { term: "Server-Side Request Forgery (SSRF) — Keycloak context", definition: "A class of attack where an attacker-influenced URL causes the server itself to issue a request on the attacker's behalf — in Keycloak, this risk shows up specifically in features where an administrator (or, in a multi-tenant setup, a self-registering client) supplies a URL the server will later fetch: an identity provider's discovery endpoint, a client's JWKS URI, or a backchannel logout URL. If that URL is attacker-influenced, the server can be made to issue requests to internal-only addresses it would never otherwise reach. Keycloak's own mitigation — the Secure Client URIs pattern executor — is a client-policy control that restricts which URI patterns are accepted for exactly these server-fetched fields. Confirmed as a named subsection (\"Mitigating Server-Side Request Forgery (SSRF)\") of Keycloak's live 26.8.2 Server Administration Guide.", category: "Security Hardening", chapters: ["security-hardening-and-upgrades"] },
  { term: "Secure Client URIs pattern executor", definition: "A Keycloak client-policy component that restricts which URI patterns a client registration (or an admin-configured field like a backchannel logout URL or JWKS URI) is allowed to use for server-fetched URLs, as a direct mitigation for SSRF. It turns \"any admin (or self-registering client) can configure any URL the server will later fetch\" into \"only URLs matching an allow-listed pattern are accepted.\" Chapter 24 introduced client policies generally; this executor is the specific SSRF-relevant one, covered first in chapter 45.", category: "Security Hardening", chapters: ["security-hardening-and-upgrades"] },
  { term: "Admin REST API audience check (kc-admin-api scope)", definition: "A Keycloak 26.8.2 hardening change, confirmed live against the official Upgrading Guide: tokens used against the Admin REST API must now carry the kc-admin-api scope and its matching audience, on top of whatever realm-management role-based permissions the token's subject already has. A custom automation client or service account that previously worked by holding any valid token now receives a flat 401 Unauthorized until that scope is explicitly assigned — a default-deny change closing the kind of \"ambient trust\" an admin-isolation checklist exists to remove. Disabling the check (--spi-admin-audience-check-enabled=false) is possible but explicitly discouraged in the docs, and a rolling upgrade across this change can produce temporary 401s.", category: "Security Hardening", chapters: ["security-hardening-and-upgrades"] },
  { term: "Rolling upgrade", definition: "Upgrading a clustered server one node at a time, so the cluster as a whole stays available throughout — the opposite of a full stop-everything-then-restart-everything upgrade. Not every Keycloak change supports it: the official 26.8.2 Upgrading Guide explicitly states a rolling upgrade \"is not supported\" for that release's client-registration-policy security fix (CVE-2026-109081), requiring a full cluster stop instead — a concrete reason to read a target version's own release notes before assuming any upgrade can simply be rolled through node by node.", category: "Keycloak Operations", chapters: ["security-hardening-and-upgrades"] },
  { term: "Backward-compatibility guarantee (Keycloak versioning)", definition: "Keycloak's own stated policy (announced October 2024, effective from version 26 onward): \"the currently default version for a Feature or an API can not change in a minor release,\" and a feature or API version deprecated in a minor release \"will not be removed until the next major version.\" The guarantee applies only to fully-supported features and APIs — preview features and non-public APIs can change at any time. A documented security fix (a named CVE) is the one exception this course found in practice to the \"no default changes in a minor\" rule, since several 26.8.x patch-release security fixes did change default behavior deliberately.", category: "Keycloak Operations", chapters: ["security-hardening-and-upgrades"] },
  { term: "Tenant isolation (authorization-time vs. platform-boundary)", definition: "The guarantee that one tenant's users, data, and permissions cannot affect another's. Keycloak can enforce this as a platform boundary (one realm per tenant — isolation is structural, but admin/operational cost grows linearly with tenant count) or it can be left to be enforced at authorization time (one shared realm, every role/permission check required to also verify a tenant_id claim or attribute — isolation becomes a discipline in application code, not a platform guarantee). Northwind Apps chose the latter specifically to avoid realm-per-tenant's operational cost at thousands-of-tenants scale, accepting that a missed resource-scope check becomes a real cross-tenant bug class to defend against.", category: "Authorization models", chapters: ["case-study-northwind"] },
  { term: "Realm-per-tenant model", definition: "A multi-tenant SaaS architecture pattern that gives each customer tenant its own fully isolated Keycloak realm. Gives strong, structural tenant isolation for free, but its admin and operational overhead (duplicated role definitions, a separate admin context per tenant, realm-wide policy changes needing to be scripted and reapplied per realm) scales linearly with tenant count — workable for a handful of large tenants, unworkable past a few dozen. Contrast with a shared realm plus a tenant_id claim, which Northwind Apps chose instead.", category: "Keycloak Core", chapters: ["case-study-northwind"] }
];
